insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8ba8221c-6d95-5df5-909a-ad7382256ec3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 35 year old woman has had diarrhoea and abdominal cramps 2 hours after eating reheated fried rice from a takeaway. Several of her friends have similar symptoms. She is now vomiting profusely. What is the SINGLE most likely organism?', 'Bacillus cereus produces a preformed emetic toxin in reheated rice, causing vomiting within 1-6 hours. Staphylococcus aureus also causes rapid-onset vomiting (1-6 hours) from preformed toxin in foods such as meats and dairy. Management is supportive. Salmonella and Campylobacter have longer incubation periods (12-72 hours).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
