  ('d3a27cf5-b52a-58ce-912d-4b2ccf7c5f76', '8ba8221c-6d95-5df5-909a-ad7382256ec3', 'A', 'Campylobacter', false, 0),
  ('7f1cb1b6-1406-50e3-b4a8-43ed8694b48c', '8ba8221c-6d95-5df5-909a-ad7382256ec3', 'B', 'E. coli O157', false, 1),
  ('4ebcaa9c-c68a-5357-a8bc-c8fe41bb8e53', '8ba8221c-6d95-5df5-909a-ad7382256ec3', 'C', 'Bacillus cereus', true, 2),
  ('eab90c5f-d941-5018-aec9-c24b4b7b21cb', '8ba8221c-6d95-5df5-909a-ad7382256ec3', 'D', 'Salmonella', false, 3),
  ('7c9acfd1-0406-5688-8ccf-5fb096e835b0', '8ba8221c-6d95-5df5-909a-ad7382256ec3', 'E', 'Norovirus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58807244-327a-5b52-8cc2-2e7341843b9d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 28 year old man has a red, hot, swollen right forearm after injecting drugs. There is a tender, fluctuant area at the injection site. He is febrile. Swabs from a previous abscess grew MRSA. What is the SINGLE most appropriate management?', 'A skin abscess needs incision and drainage. With known MRSA colonisation, antibiotics should cover MRSA (doxycycline, clindamycin or co-trimoxazole orally, or IV vancomycin or teicoplanin if systemically unwell). People who inject drugs are at risk of endocarditis, necrotising fasciitis and blood-borne viruses, so harm reduction and BBV testing are important.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b05a601-4c35-5630-8e6a-9348e15c36a7', '58807244-327a-5b52-8cc2-2e7341843b9d', 'A', 'Oral flucloxacillin alone', false, 0),
  ('0bbb2704-f8ad-5db6-8a35-90b6bd88c9b4', '58807244-327a-5b52-8cc2-2e7341843b9d', 'B', 'Topical mupirocin alone', false, 1),
  ('6d990b6c-2add-5e85-8c43-a4ab11f0c0e6', '58807244-327a-5b52-8cc2-2e7341843b9d', 'C', 'No antibiotics', false, 2),
  ('296fc4ad-d7f1-5407-bfdd-de55642a4cc0', '58807244-327a-5b52-8cc2-2e7341843b9d', 'D', 'Oral amoxicillin', false, 3),
  ('167b3ffe-9b62-5e1a-89ed-78701522ebb1', '58807244-327a-5b52-8cc2-2e7341843b9d', 'E', 'Incision and drainage plus an antibiotic active against MRSA (e.g. doxycycline or IV vancomycin if severe)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('089f5230-c4d7-5ff3-86f4-903278c662d9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 52 year old man with diabetes has a rapidly spreading, exquisitely painful red swelling of his thigh, with pain far worse than the visible skin changes. He has crepitus, tachycardia and hypotension. What is the SINGLE most appropriate management?', 'Necrotising fasciitis is a surgical emergency. Pain out of proportion to the signs, rapid spread, crepitus, skin necrosis and systemic toxicity are features. Type 1 is polymicrobial (in diabetes, after surgery), type 2 is group A streptococcus. Immediate surgical debridement and IV broad-spectrum antibiotics (including clindamycin to reduce toxin production) are needed. Imaging must not delay surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('da342d98-6178-5fc9-b43c-d4fa3b96bb02', '089f5230-c4d7-5ff3-86f4-903278c662d9', 'A', 'Oral flucloxacillin and review in 48 hours', false, 0),
  ('4a9edac4-ac82-5f37-a469-d68f67787731', '089f5230-c4d7-5ff3-86f4-903278c662d9', 'B', 'Topical antibiotics', false, 1),
  ('2011e925-b90d-5537-a4b9-ea8709f14ab9', '089f5230-c4d7-5ff3-86f4-903278c662d9', 'C', 'MRI before any treatment', false, 2),
  ('d7457501-ffdc-5140-b52c-de00ee3763c8', '089f5230-c4d7-5ff3-86f4-903278c662d9', 'D', 'Urgent surgical debridement and IV broad-spectrum antibiotics', true, 3),
  ('00fed391-ef35-5a61-8711-d421ff1955d4', '089f5230-c4d7-5ff3-86f4-903278c662d9', 'E', 'Elevation only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d48d977f-153c-51a1-9c99-041dcf125d4d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 32 year old woman is 16 weeks pregnant and has a cat. She asks how to avoid infection. Which infection is she MOST at risk of from cat faeces?', 'Toxoplasma gondii is spread through cat faeces and undercooked meat. Primary infection in pregnancy can cause congenital toxoplasmosis (chorioretinitis, hydrocephalus, intracranial calcification). Pregnant women should avoid cleaning cat litter (or wear gloves), cook meat thoroughly and wash vegetables. Listeria comes from unpasteurised dairy, soft cheeses and pâté.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c4bd656-5bfb-5ce0-98b8-1088459a6a67', 'd48d977f-153c-51a1-9c99-041dcf125d4d', 'A', 'Group B streptococcus', false, 0),
  ('5e3538d3-29d6-5bbf-b1f2-147f036a97ec', 'd48d977f-153c-51a1-9c99-041dcf125d4d', 'B', 'Toxoplasmosis', true, 1),
  ('d7287790-3aef-5b48-9c11-50908ef33d03', 'd48d977f-153c-51a1-9c99-041dcf125d4d', 'C', 'Cytomegalovirus', false, 2),
  ('371a7aa5-8f3c-5dee-9493-56c847cbc4c8', 'd48d977f-153c-51a1-9c99-041dcf125d4d', 'D', 'Rubella', false, 3),
  ('7a16f581-6591-5a5a-9e39-ac69dc714efb', 'd48d977f-153c-51a1-9c99-041dcf125d4d', 'E', 'Listeriosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 38 year old man is a close household contact of a patient with active pulmonary TB. He is well and has no symptoms. His interferon-gamma release assay (IGRA) is positive and his chest X-ray is normal. HIV test is negative. What is the SINGLE most appropriate management?', 'A positive IGRA or Mantoux with no evidence of active disease means latent TB infection. Treatment (3 months of rifampicin plus isoniazid, or 6 months of isoniazid with pyridoxine) reduces the risk of progression to active TB. It is offered especially to people aged 65 and under, and those with risk factors (HIV, immunosuppression, recent contact). LFTs are monitored.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eb6e4fd5-211c-5627-9b99-a45cd1c691bf', '55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'A', 'Repeat chest X-ray in 5 years', false, 0),
  ('c3196563-dfea-5b2f-86db-251a698298e5', '55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'B', 'Treat latent TB (e.g. 3 months of rifampicin and isoniazid, or 6 months of isoniazid)', true, 1),
  ('c43717e9-1783-5151-b8d1-da00bb58c425', '55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'C', 'BCG vaccination', false, 2),
  ('8a26cc44-80ac-5dc6-9f59-ccfa99dbb71d', '55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'D', 'Full 6-month quadruple therapy', false, 3),
  ('d79b681f-41aa-502c-8bac-cf108998365c', '55f79811-3fd5-5335-9e45-a0c24ff52e4b', 'E', 'No treatment needed', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 70 year old man is in hospital with pneumonia. Blood cultures grow Staphylococcus aureus. He has a long-term central line. What is the SINGLE most important investigation?', 'S. aureus bacteraemia carries a high risk of metastatic infection (endocarditis, osteomyelitis, discitis, septic arthritis). Management includes source control (removing the infected line), at least 14 days of IV antibiotics, repeat blood cultures to confirm clearance, and echocardiography (TOE if there is high suspicion) to exclude endocarditis. Infectious disease consultation improves outcomes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e45e696a-8c4e-5544-99bc-a00f802c7e79', '504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'A', 'Repeat blood cultures in 6 weeks', false, 0),
  ('5d107414-34b2-5d71-af70-0d704071ce6c', '504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'B', 'Chest X-ray only', false, 1),
  ('5e72e6da-9aa7-5a6d-a7c1-d92f6fc315c9', '504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'C', 'Urine culture', false, 2),
  ('c34e8551-b6c2-56b9-ab29-5db94550be59', '504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'D', 'Echocardiography to exclude infective endocarditis', true, 3),
  ('a1260a4c-d944-565d-bee9-ae9ce52d1e03', '504c4f4c-82dc-5a5d-aa2e-dfaae517ed5b', 'E', 'CT abdomen', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a8ae037e-beb3-52b9-b359-bae57fb18867', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 40 year old man who keeps sheep has had fever for 3 weeks, sweats and arthralgia, with a dry cough. He has hepatosplenomegaly. He drinks unpasteurised milk. Which organism is MOST likely?', 'Brucellosis (from unpasteurised dairy and contact with livestock) causes an undulant fever, sweats, arthralgia, sacroiliitis, hepatosplenomegaly and lymphadenopathy. It is diagnosed by blood cultures (warning the lab) and serology. Treatment is doxycycline plus rifampicin or gentamicin. Q fever (Coxiella) causes atypical pneumonia and hepatitis in farm workers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9255146d-fa15-5c9a-930d-9930ee067086', 'a8ae037e-beb3-52b9-b359-bae57fb18867', 'A', 'Coxiella burnetii', false, 0),
  ('a4e79761-4410-59a8-96dd-80b5076effdb', 'a8ae037e-beb3-52b9-b359-bae57fb18867', 'B', 'Toxoplasma', false, 1),
  ('f8883070-5d69-533c-bfa5-97c7008f392b', 'a8ae037e-beb3-52b9-b359-bae57fb18867', 'C', 'Brucella', true, 2),
  ('dec5a8d6-4c75-5da9-bfd6-873b589815d9', 'a8ae037e-beb3-52b9-b359-bae57fb18867', 'D', 'Listeria', false, 3),
  ('3ab0eb86-2993-5909-b593-c8d20d82cc3d', 'a8ae037e-beb3-52b9-b359-bae57fb18867', 'E', 'Leptospira', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b6c82f35-0744-5972-a357-348ebd4c22cd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 4 year old child has had a perianal itch, worse at night, for 2 weeks. Her mother saw small white thread-like worms around the anus. What is the SINGLE most appropriate management?', 'Threadworms (Enterobius vermicularis) are common in children. Treatment is a single dose of mebendazole (in those over 6 months), repeated after 2 weeks if needed, for the whole household at the same time, plus strict hygiene measures for 2 weeks (handwashing, short nails, morning baths, washing bedding). In pregnancy and under 6 months, hygiene measures alone are used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('16cabb92-7cf2-59e7-93a0-8f1fa51414e9', 'b6c82f35-0744-5972-a357-348ebd4c22cd', 'A', 'Mebendazole for the child and all household members, plus hygiene measures', true, 0),
  ('3203a5c4-e6dc-5fc1-972b-d634a0b50407', 'b6c82f35-0744-5972-a357-348ebd4c22cd', 'B', 'No treatment', false, 1),
  ('b7e15cb5-4f2b-52ab-a9d7-ae66aef00352', 'b6c82f35-0744-5972-a357-348ebd4c22cd', 'C', 'Oral albendazole for 3 months', false, 2),
  ('fe8d0ef3-0b2f-5463-8098-1037978be8f6', 'b6c82f35-0744-5972-a357-348ebd4c22cd', 'D', 'Oral metronidazole', false, 3),
  ('a3e077ca-2b19-5c9d-824b-2bd51f259f57', 'b6c82f35-0744-5972-a357-348ebd4c22cd', 'E', 'Treat the child only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 15 year old girl attends her GP asking for contraception. She has been in a sexual relationship with her 16 year old boyfriend for 3 months and will continue whether or not she gets contraception. She refuses to involve her parents. She understands the advice given and there are no safeguarding concerns. What is the SINGLE most appropriate action?', 'Under the Fraser guidelines, a doctor can give contraceptive advice or treatment to a young person under 16 without parental consent if: she understands the advice; she cannot be persuaded to tell her parents; she is likely to continue having sex; her physical or mental health is likely to suffer without contraception; and it is in her best interests. Confidentiality should be kept unless there are safeguarding concerns, such as a much older partner, coercion or exploitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('440e4996-3f61-5a41-abac-46b984c90b71', '244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'A', 'Advise her to come back when she is 16', false, 0),
  ('125f9996-550e-5cbd-8915-3c15df825fff', '244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'B', 'Inform her parents before prescribing', false, 1),
  ('8879b0ad-95d7-58f1-bc84-f11d4813b896', '244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'C', 'Refer to social services before prescribing', false, 2),
  ('6beecb7d-f428-5499-9fa4-4f3a12e1adfa', '244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'D', 'Prescribe contraception if the Fraser guidelines are met', true, 3),
  ('fa076b21-a6aa-5912-8dce-d426f96ebfc9', '244cb320-da58-5b04-b7b3-17fabe2d4ce9', 'E', 'Refuse to prescribe without parental consent', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 34 year old car driver attends the Emergency Department after his first unprovoked generalised seizure. CT head and blood tests are normal and he has made a full recovery. He drives a car only, not a bus or lorry. He asks when he can drive again. What is the SINGLE most appropriate advice?', 'It is the patient''s legal responsibility to tell the DVLA. After a first unprovoked seizure with no relevant findings on investigation, a Group 1 (car) licence is usually revoked for 6 months (12 months if there are features suggesting a high risk of recurrence). The doctor should advise him clearly. If he continues to drive against advice, the GMC allows disclosure to the DVLA after telling the patient you intend to do so.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e39db1d0-acbe-5b07-bea4-ad7876bf99b6', 'd8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'A', 'Stop driving for 1 month; there is no need to inform the DVLA', false, 0),
  ('8737829b-54bb-51a9-9d8f-db41a13fe132', 'd8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'B', 'He can continue driving as it was a single seizure', false, 1),
  ('cf41bc60-e992-5c1e-876e-32d9c4b942f5', 'd8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'C', 'The doctor must inform the DVLA immediately without telling the patient', false, 2),
  ('bae379b2-709c-50e7-80e5-5631ff34ea88', 'd8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'D', 'Stop driving and inform the DVLA; he is usually unable to drive for 6 months', true, 3),
  ('3b577e02-1c22-5ab5-8fc0-dff160a5ed75', 'd8dc291b-f1fa-547d-9ef8-29baf5c087c4', 'E', 'Stop driving for 10 years', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 78 year old man with mild dementia is advised to have a hip replacement. He understands the benefits and risks explained to him, remembers them long enough to discuss them, weighs them up and clearly says he does not want the operation because he is ''too old for surgery''. His daughter insists he must have it. What is the SINGLE most appropriate action?', 'Under the Mental Capacity Act 2005, capacity is presumed, is specific to the decision and is assessed with the two-stage test. The person must be able to understand, retain, weigh up and communicate the decision. A diagnosis of dementia does not mean someone lacks capacity, and an unwise decision does not prove a lack of capacity. Relatives cannot consent for an adult unless they hold a relevant Lasting Power of Attorney and the person lacks capacity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c383d3f-f144-5b95-9655-528ad49ea770', '9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'A', 'Proceed with surgery in his best interests', false, 0),
  ('74c730ad-2fa2-5118-bbc8-4228a8db2795', '9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'B', 'Respect his decision as he has capacity', true, 1),
  ('ff79c165-266c-52ed-b8be-90d1702dbaa5', '9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'C', 'Apply to the Court of Protection', false, 2),
  ('9b20f78b-3f7c-569c-93b4-439d306d925c', '9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'D', 'Detain him under the Mental Health Act', false, 3),
  ('2f6bcf8d-6a07-5667-8b80-754ad2b26ad8', '9f9d301b-f6f1-5a99-a6f0-f92fc9019260', 'E', 'Ask the daughter to sign the consent form', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 40 year old man has just been diagnosed with sputum-smear-positive pulmonary tuberculosis. He asks the doctor not to tell anyone, including public health authorities, because he is worried about his job. What is the SINGLE most appropriate action?', 'Tuberculosis is a notifiable disease under the Health Protection (Notification) Regulations 2010. The registered medical practitioner has a legal duty to notify the local health protection team, which does not need the patient''s consent. The doctor should explain this sensitively. Disclosure should be limited to what is necessary, so his employer should not be told directly; contact tracing is done by the health protection team.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d764af46-9205-595a-9eee-8eb76b29e297', 'fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'A', 'Tell his neighbours to get tested', false, 0),
  ('c737bcbc-814a-5df4-b21f-39fa6885b6e3', 'fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'B', 'Explain that TB is a notifiable disease and notify the UKHSA health protection team', true, 1),
  ('59a46dc1-7b0b-53cd-b006-fde5f66a3061', 'fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'C', 'Notify only if he consents in writing', false, 2),
  ('5853bfad-634d-551f-866b-e311f3786d6a', 'fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'D', 'Respect his wishes and do not notify anyone', false, 3),
  ('0002f385-8e79-5665-8710-8a7e2d1be835', 'fb350f77-9ae3-56b3-b4dd-38fdc10299ad', 'E', 'Inform his employer directly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('72e94f4c-427a-599a-9022-496c49a7abc4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor notices that a colleague smells strongly of alcohol, is slurring his words and is about to start a ward round. What is the SINGLE most appropriate initial action?', 'GMC guidance (Good Medical Practice) requires doctors to act promptly if patient safety may be at risk from a colleague''s health or conduct. The immediate priority is to stop him from treating patients and to escalate to a senior clinician. Local procedures are then followed, and referral to the GMC is considered if needed. Concerns should also be raised supportively, because the colleague may need occupational health help.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5cc1f80-1909-5fe5-9bc7-da7ad06cc3ee', '72e94f4c-427a-599a-9022-496c49a7abc4', 'A', 'Discuss it with him next week', false, 0),
  ('0e87cf89-2ff9-5322-85ef-787cfd7c29e1', '72e94f4c-427a-599a-9022-496c49a7abc4', 'B', 'Report him directly to the GMC before speaking to anyone', false, 1),
  ('df6a83d9-b7fe-530f-863f-09858ed3f635', '72e94f4c-427a-599a-9022-496c49a7abc4', 'C', 'Tell the patients on the ward', false, 2),
  ('d0078910-b828-5d60-8261-85bbe2a7de35', '72e94f4c-427a-599a-9022-496c49a7abc4', 'D', 'Ensure patient safety by stopping him from seeing patients and inform a senior (consultant or clinical director) immediately', true, 3),
  ('035547b2-0a43-53f8-a0a0-477e4decbd84', '72e94f4c-427a-599a-9022-496c49a7abc4', 'E', 'Do nothing as it is not your responsibility', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'During a laparoscopic cholecystectomy, the surgeon accidentally damages the common bile duct, which is repaired. The patient recovers well. On the ward the next day, the patient asks how the operation went. What is the SINGLE most appropriate action?', 'The professional duty of candour (GMC/NMC) and the statutory duty of candour require doctors to be open and honest when something goes wrong with a patient''s care that causes, or could cause, harm. They should tell the patient, apologise, offer an appropriate remedy and explain the likely short- and long-term effects. An apology is not an admission of legal liability. The incident should also be reported locally.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('118e70d2-046b-5b80-a0ab-37d2d4714e90', '5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'A', 'Tell the patient about the complication, apologise and explain what will happen next', true, 0),
  ('d679acf2-d4b6-5fb2-9964-afa39be48764', '5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'B', 'Do not mention it as the patient has recovered', false, 1),
  ('6dc82bc9-b2f0-521c-8add-bdb411c0b4eb', '5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'C', 'Document it but do not tell the patient', false, 2),
  ('f844b38f-10fc-5877-8e46-ca3a031859da', '5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'D', 'Tell only the patient''s family', false, 3),
  ('d959b277-4eb3-5ce0-8582-5f843732519f', '5ea184ce-4ea0-550e-a062-b8389be7cc1c', 'E', 'Wait until the patient asks specifically about complications', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 35 year old woman who is a Jehovah''s Witness has a severe postpartum haemorrhage. She is conscious and has capacity. She has a signed advance decision refusing blood transfusion, even if she dies. Her husband begs the team to transfuse her. What is the SINGLE most appropriate action?', 'An adult with capacity can refuse any treatment, including life-saving treatment, and a valid applicable advance decision refusing life-sustaining treatment remains binding if she later loses capacity. Giving blood against her wishes would be assault. All acceptable alternatives should be used: uterotonics, tranexamic acid, cell salvage if acceptable to her, surgical measures and early senior input. Relatives cannot override her decision.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1e739de4-813f-59f3-b903-11d30cd6df34', '3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'A', 'Follow the husband''s wishes', false, 0),
  ('1759f9dd-69ae-5607-9395-366ba7274858', '3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'B', 'Transfuse blood as it is life-saving', false, 1),
  ('28f25a14-ef40-5232-940f-2650e992c6eb', '3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'C', 'Transfuse once she becomes unconscious', false, 2),
  ('8572d95d-1feb-5142-a752-65214c5c1f27', '3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'D', 'Respect her refusal and use all other non-blood measures', true, 3),
  ('40ca30f7-6c84-5d3a-94e3-62d27060eb40', '3bf48e6e-e1e8-5414-8c07-17a1c76706a9', 'E', 'Seek a court order immediately before treating', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'An 89 year old man with advanced heart failure and severe frailty is admitted with pneumonia. The consultant believes CPR would not be successful. The patient has capacity and asks to discuss his resuscitation status. What is the SINGLE most appropriate approach?', 'If CPR would not be successful, doctors are not obliged to offer it, but following the Tracey case (2014) there is a legal duty to discuss a DNACPR decision with a patient who has capacity unless this would cause physical or psychological harm. The reasoning should be explained sensitively and documented clearly. A DNACPR decision applies only to CPR, and all other appropriate treatment continues.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('84938a1e-74be-5b6a-ae21-a1cbb40331e3', '8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'A', 'Discuss the DNACPR decision with him, explaining why CPR is unlikely to work, and document it', true, 0),
  ('98135e15-d6ea-5043-a766-6526af5c1115', '8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'B', 'Let his family decide', false, 1),
  ('962e929d-4830-5896-8138-43558c43bf4c', '8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'C', 'Offer CPR because the patient must consent to a DNACPR', false, 2),
  ('d290fc97-770f-5385-a971-2a9a74f9e97e', '8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'D', 'Make the DNACPR decision without telling him to avoid distress', false, 3),
  ('aeb83966-4e19-586e-8a2a-40680569228e', '8394c7f7-92d1-58db-baeb-6acd2f1a9413', 'E', 'Avoid discussion until he loses capacity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('de48b100-494a-53bd-804e-9375c049d206', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 16 year old boy with a broken arm needs an operation under general anaesthesia. He understands the procedure, its risks and alternatives, and agrees. His parents are abroad and cannot be contacted. What is the SINGLE most appropriate action regarding consent?', 'Young people aged 16 and 17 are presumed to have capacity to consent to treatment, and the Mental Capacity Act applies to them. Under 16, a child can consent if Gillick competent. Refusal of life-saving treatment by a young person under 18 may be overridden by a person with parental responsibility or the court, though this is rare and needs legal advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4ccd2420-65f6-586b-9dbe-afcccaa9b807', 'de48b100-494a-53bd-804e-9375c049d206', 'A', 'He can consent for himself as a 16-17 year old is presumed to have capacity (Family Law Reform Act 1969)', true, 0),
  ('eaf17602-3ad1-5d8e-ad4b-66f07870b805', 'de48b100-494a-53bd-804e-9375c049d206', 'B', 'Wait until his parents can be contacted', false, 1),
  ('a8ada3a4-29a2-5553-8dbb-eac692a39d28', 'de48b100-494a-53bd-804e-9375c049d206', 'C', 'Treat without consent as an emergency', false, 2),
  ('21dab5e4-ed1e-58d1-8c83-8a3f21fa0a4b', 'de48b100-494a-53bd-804e-9375c049d206', 'D', 'Apply to the court', false, 3),
  ('04123df0-fb09-5f8a-84b3-cb1bf6e25da1', 'de48b100-494a-53bd-804e-9375c049d206', 'E', 'Ask a teacher to consent', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 13 year old girl attends the GP with her 21 year old boyfriend and requests contraception. She says they have been having sex for a month. What is the SINGLE most appropriate action?', 'A child under 13 cannot legally consent to sexual activity, which is classed as rape under the Sexual Offences Act 2003. Here she is 13, and the large age gap raises concerns about exploitation. Safeguarding procedures must be followed, involving the designated safeguarding lead and children''s social care. Confidentiality can be breached to protect a child from serious harm. Her health needs should still be addressed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bd17d0f3-cb1b-52a2-afc4-0e67c700cedd', 'c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'A', 'Inform the school only', false, 0),
  ('134f3a63-4a6d-5ecd-bd5b-7ee8df70468d', 'c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'B', 'Follow safeguarding procedures and refer to children''s social care', true, 1),
  ('b1fadc89-b01c-5b39-94cc-a012d7dfe7ef', 'c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'C', 'Report to the GMC', false, 2),
  ('041a6a18-620e-530d-ab70-cfc8e28c033e', 'c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'D', 'Prescribe contraception and keep confidential', false, 3),
  ('65b28d47-309b-5563-bf8e-65c84551d93f', 'c7ac0b31-e933-5921-9a1e-8f4b63e3dc1b', 'E', 'Refuse and send her home', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9dd1761f-6b84-559a-a7a3-efefbbabf991', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 45 year old man with epilepsy continues to drive despite repeated advice not to, and he has had a seizure 2 months ago. He refuses to inform the DVLA. What is the SINGLE most appropriate action?', 'GMC guidance allows doctors to disclose information to the DVLA without consent if a patient continues to drive when unfit and refuses to stop or to inform the DVLA, because there is a risk of death or serious harm to others. The patient should be told before disclosure, and the decision documented. The DVLA medical adviser can also be contacted for advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('95eefe3d-f4b2-504c-bd59-a1051e78cd32', '9dd1761f-6b84-559a-a7a3-efefbbabf991', 'A', 'Remove him from the practice list', false, 0),
  ('bdaca70a-28d5-530a-ad87-5719c951ec2e', '9dd1761f-6b84-559a-a7a3-efefbbabf991', 'B', 'Tell his employer', false, 1),
  ('de406f28-2b96-5c0f-998b-3016c3f386f0', '9dd1761f-6b84-559a-a7a3-efefbbabf991', 'C', 'Inform the DVLA after telling the patient you intend to do so', true, 2),
  ('1094658f-65df-5f45-afe0-31008f240e2b', '9dd1761f-6b84-559a-a7a3-efefbbabf991', 'D', 'Do nothing as it would breach confidentiality', false, 3),
  ('1c849165-e1b4-5364-aa00-83d246243352', '9dd1761f-6b84-559a-a7a3-efefbbabf991', 'E', 'Inform the police', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bb32c154-9679-5f46-bfef-34fc93d99ffd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 34 year old man has been diagnosed with HIV. He refuses to tell his long-term female partner, with whom he has unprotected sex. Despite counselling over several consultations, he still refuses. What is the SINGLE most appropriate action?', 'GMC guidance allows disclosure to a known sexual partner at risk of a serious communicable disease if the patient refuses to tell them or to stop putting them at risk, after reasonable efforts to persuade them. The patient should be told first, and only the minimum necessary information disclosed. Advice from senior colleagues or a defence organisation is wise.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7e5f61dd-2db9-566d-86d6-4bab23ce1a29', 'bb32c154-9679-5f46-bfef-34fc93d99ffd', 'A', 'Never disclose under any circumstances', false, 0),
  ('aca9fa1a-40ab-5970-967f-b2c41059914f', 'bb32c154-9679-5f46-bfef-34fc93d99ffd', 'B', 'Consider disclosing to the partner after informing the patient, as there is a serious risk of harm', true, 1),
  ('19889f49-5275-5fd7-bc85-db42539ad49b', 'bb32c154-9679-5f46-bfef-34fc93d99ffd', 'C', 'Inform the police', false, 2),
  ('628f199f-c637-5bf4-8b69-7f14e2f849c5', 'bb32c154-9679-5f46-bfef-34fc93d99ffd', 'D', 'Report the patient to the GMC', false, 3),
  ('28b9532e-633a-5836-b9d9-541c316dd923', 'bb32c154-9679-5f46-bfef-34fc93d99ffd', 'E', 'Tell his employer', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor is asked by a patient''s employer to provide information about her recent hospital admission. The patient has not consented. What is the SINGLE most appropriate response?', 'Patient information is confidential and should not be disclosed to third parties such as employers or insurers without explicit consent, except where required by law or justified in the public interest. Under the Access to Medical Reports Act 1988, patients can see employment reports before they are sent.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('144d8e25-6b8c-581d-9b87-7c13a51f7371', '09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'A', 'Call the patient''s family', false, 0),
  ('5d8a4b63-9b16-5590-9c6e-8aa68ee92af4', '09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'B', 'Provide a full summary as the employer is paying', false, 1),
  ('fe2a4b88-a3c8-56f9-a885-458bad2fe9fb', '09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'C', 'Disclose only the diagnosis', false, 2),
  ('4f2fb322-87ac-5520-b7d7-1cb25d612086', '09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'D', 'Decline to disclose without the patient''s explicit consent', true, 3),
  ('a0c6ad1f-7472-54f2-8847-dd7eece7f3fa', '09b03e1d-426a-5ae1-bbf1-7a92a2039b6b', 'E', 'Report the employer to the police', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A police officer phones the Emergency Department asking whether a named man was treated there last night following a fight. He does not have a court order. There is no evidence of a serious crime. What is the SINGLE most appropriate response?', 'Confidentiality applies even to confirming that someone is a patient. Disclosure to the police without consent is justified only when required by law (such as a court order or the Road Traffic Act for driver identification), or in the public interest to prevent or detect serious crime, such as gunshot or knife wounds (GMC guidance). Decisions should be documented, and senior or Caldicott Guardian advice sought.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('47052ab5-bd24-5eb2-8677-4c0896be777f', '90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'A', 'Confirm the details as police have a right to know', false, 0),
  ('d424c691-a79c-5afd-837e-2171b61dd7e0', '90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'B', 'Send the medical notes', false, 1),
  ('7ac878ad-3b0e-54fe-bbe3-cf0e251b7b5c', '90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'C', 'Ask the patient''s family for permission', false, 2),
  ('d6b59d7d-839c-5bb8-a78c-f74c2cd77361', '90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'D', 'Disclose only the address', false, 3),
  ('6dd036b1-30dc-5a06-88b2-64b3659e4801', '90acb425-ac1c-5a92-b4ad-be2f5792e9d9', 'E', 'Do not confirm or deny without the patient''s consent, unless disclosure is required by law or justified in the public interest', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 20 year old man attends the Emergency Department with a stab wound. He asks the doctor not to tell anyone. What is the SINGLE most appropriate action regarding disclosure?', 'GMC guidance states that the police should usually be informed when a person arrives with a gunshot or knife wound (not self-inflicted or accidental), so they can assess the risk to the public. Identifying details are not usually needed at first. The patient should still be treated and told about the disclosure where possible.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d33da03b-870c-5f0b-a902-144fe955b0d2', '6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'A', 'Inform his family', false, 0),
  ('4e9b1d63-9860-5160-b213-ce047572b3fb', '6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'B', 'Refuse treatment until he agrees to police involvement', false, 1),
  ('66785a25-0cd1-5abe-8515-bb8ca6b73728', '6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'C', 'Tell the media', false, 2),
  ('3e850ff7-f139-51ed-9a4f-6da93c4eb9f5', '6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'D', 'Keep it completely confidential', false, 3),
  ('4bd2e5e7-3aaa-52cd-ae6c-dd17c54d4afd', '6d482a41-6305-5eaa-9f4b-65052f8e9e57', 'E', 'Inform the police that a person with a knife wound has attended (without initially giving identifying details)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d45ab303-e492-562f-965f-b9204bd215b9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 30 year old woman refuses a caesarean section recommended for fetal distress. She has capacity and understands the risks to herself and the baby. What is the SINGLE most appropriate action?', 'A competent pregnant woman can refuse any treatment, even if it may result in the death of her fetus (St George''s Healthcare NHS Trust v S). The fetus has no independent legal personality until birth. Doctors should continue to provide support and explore her concerns. The MHA cannot be used to force obstetric treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f95fca86-4450-5263-9135-d31d6cee7716', 'd45ab303-e492-562f-965f-b9204bd215b9', 'A', 'Respect her refusal; the fetus has no separate legal rights before birth in UK law', true, 0),
  ('d39788c8-df85-5dfa-ba82-dfb447c775a8', 'd45ab303-e492-562f-965f-b9204bd215b9', 'B', 'Perform the caesarean section in the fetal interests', false, 1),
  ('a828673e-1abe-5017-bb12-ecf1e129e647', 'd45ab303-e492-562f-965f-b9204bd215b9', 'C', 'Detain her under the Mental Health Act', false, 2),
  ('6bf22192-9cf4-5485-8136-61a71868702f', 'd45ab303-e492-562f-965f-b9204bd215b9', 'D', 'Apply to the court to override her decision', false, 3),
  ('c94ca851-215d-5b7e-b789-702a6e95b7d3', 'd45ab303-e492-562f-965f-b9204bd215b9', 'E', 'Ask her partner to consent', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 70 year old man is unconscious after a stroke. He has a valid Lasting Power of Attorney for Health and Welfare naming his daughter. A decision is needed about inserting a feeding tube. What is the SINGLE most appropriate approach?', 'A registered Lasting Power of Attorney for Health and Welfare allows the attorney to make healthcare decisions when the person lacks capacity, within the scope of the document. Life-sustaining treatment decisions need express authority in the LPA. Attorneys must act in the person''s best interests. Without an LPA or advance decision, the clinician decides in best interests, consulting relatives.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eb614868-7957-5d99-9e28-03eeb9f1e2ff', '4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'A', 'An IMCA must decide', false, 0),
  ('e12159c4-aebe-5d88-8b67-40fbd5d1d854', '4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'B', 'The court must decide', false, 1),
  ('61f07da7-a2d5-5cf4-9961-2384cdf8e52e', '4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'C', 'His wife automatically decides', false, 2),
  ('d6e4d1c8-0c08-5228-971d-3edff5faff20', '4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'D', 'The doctor decides alone', false, 3),
  ('166db239-6b34-5b9e-b1c3-ebfaaa5e47ac', '4d3a6d97-e302-50d3-9766-3f7828d9d7d1', 'E', 'His daughter can make the decision (within the scope of the LPA) in his best interests', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b288dc07-d685-595c-8334-9d215946779f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 55 year old woman with no family or friends lacks capacity because of a severe brain injury. A decision is needed about long-term accommodation in a care home. What is the SINGLE most appropriate step?', 'Under the Mental Capacity Act, an IMCA must be instructed for a person who lacks capacity and has no appropriate family or friends to consult, when a decision is needed about serious medical treatment or a long-term change of accommodation (over 28 days in hospital or 8 weeks in a care home). The IMCA represents the person''s views and interests.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9fd92e70-0987-53a0-992e-2078debd41b7', 'b288dc07-d685-595c-8334-9d215946779f', 'A', 'Wait until she regains capacity', false, 0),
  ('d019ad5d-2f8f-580b-a469-c1a1aee62e3a', 'b288dc07-d685-595c-8334-9d215946779f', 'B', 'Make the decision without further input', false, 1),
  ('008ba896-e315-5612-b144-74124512fb19', 'b288dc07-d685-595c-8334-9d215946779f', 'C', 'Instruct an Independent Mental Capacity Advocate (IMCA)', true, 2),
  ('c9ebaf7f-82bf-5bd4-85e3-17885c652fa7', 'b288dc07-d685-595c-8334-9d215946779f', 'D', 'Ask a neighbour to decide', false, 3),
  ('dac66fb1-0a7e-56c3-9fff-25941cd0ec6e', 'b288dc07-d685-595c-8334-9d215946779f', 'E', 'Apply to the GMC', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('12692ce2-b249-5222-92c8-6e74940d2e0a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'An 85 year old woman with advanced dementia has an advance decision, valid and applicable, refusing antibiotics for any life-threatening infection. She now has pneumonia. Her son wants her treated. What is the SINGLE most appropriate action?', 'A valid and applicable advance decision to refuse treatment is legally binding. To refuse life-sustaining treatment, it must be in writing, signed and witnessed, and state that it applies even if life is at risk. Family members cannot override it. Comfort and palliative care should continue.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('610b5bd4-9393-5005-a66e-311765c2f7fc', '12692ce2-b249-5222-92c8-6e74940d2e0a', 'A', 'Ask an IMCA to decide', false, 0),
  ('47c67325-bcc2-5c5a-af84-8f3827370070', '12692ce2-b249-5222-92c8-6e74940d2e0a', 'B', 'Follow the advance decision and provide comfort care', true, 1),
  ('d660438f-a029-57e3-ba4e-66454ede3653', '12692ce2-b249-5222-92c8-6e74940d2e0a', 'C', 'Seek a court order', false, 2),
  ('3dd7433d-7edc-5b6b-a8c5-8298969683aa', '12692ce2-b249-5222-92c8-6e74940d2e0a', 'D', 'Ignore the advance decision because she has dementia', false, 3),
  ('fe4d8eba-16c1-54eb-ad7f-30afcf8e3680', '12692ce2-b249-5222-92c8-6e74940d2e0a', 'E', 'Treat with antibiotics as the son wishes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A junior doctor notices that a consultant regularly does not wash his hands between patients, and the infection rate on the ward has increased. The junior doctor has raised it informally, without change. What is the SINGLE most appropriate next step?', 'GMC guidance requires doctors to raise concerns about patient safety. If informal approaches fail, the concern should be escalated through local formal channels (clinical director, medical director, infection control, Freedom to Speak Up Guardian), then to regulators (GMC, CQC) if local action is inadequate. Whistleblowing is protected under the Public Interest Disclosure Act.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6834758e-f4e9-58ec-ae15-0be8c9922c70', '21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'A', 'Raise the concern through the hospital''s formal channels (e.g. clinical director, infection control, or Freedom to Speak Up Guardian)', true, 0),
  ('b41cbe15-7531-5d9b-8934-dd63bb5efd29', '21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'B', 'Report directly to the newspapers', false, 1),
  ('c4d6ad7e-3781-5b4f-ac50-3f8fdd723299', '21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'C', 'Leave the job', false, 2),
  ('bb2c0349-a501-5b4b-a7cb-dd602991af6a', '21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'D', 'Confront the consultant in front of patients', false, 3),
  ('7a17c961-20b8-5153-9abb-89bcdf4fe922', '21b3f6e5-4fda-5b1a-a54e-3eefb8a8e9a4', 'E', 'Do nothing as he is senior', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('121b8c84-414a-5d8a-a64e-6369ff325f6d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor realises she prescribed a ten-fold overdose of a drug to a patient, who has had no harm because a pharmacist intercepted it. What is the SINGLE most appropriate action?', 'Near misses should be reported through local incident reporting systems (such as Datix) so the organisation can learn and improve systems. Reflection on the event, and discussion with a supervisor, supports professional development. Honesty is required. Duty of candour applies to incidents causing harm, but openness about near misses is good practice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2b1141d4-c4ed-5c83-9da0-a75698d77479', '121b8c84-414a-5d8a-a64e-6369ff325f6d', 'A', 'Inform the GMC directly', false, 0),
  ('6f8166d7-cb0c-517b-9574-4cf956f20fa9', '121b8c84-414a-5d8a-a64e-6369ff325f6d', 'B', 'Resign', false, 1),
  ('99f04a28-a85c-5d2a-b3eb-c8f2f3a1a109', '121b8c84-414a-5d8a-a64e-6369ff325f6d', 'C', 'Do nothing as no harm occurred', false, 2),
  ('3930cf2a-287f-52c7-a15e-3b095422bc36', '121b8c84-414a-5d8a-a64e-6369ff325f6d', 'D', 'Report it through the local incident reporting system and reflect on it as a learning event', true, 3),
  ('fd709f7b-1236-53b2-b450-4d7ccffe5750', '121b8c84-414a-5d8a-a64e-6369ff325f6d', 'E', 'Change the record to hide the error', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 40 year old man has died unexpectedly in hospital 12 hours after an elective operation. The cause of death is not clear. What is the SINGLE most appropriate action regarding the death certificate?', 'Deaths must be referred to the coroner when the cause is unknown, or when death is sudden or unexpected, related to a medical procedure or treatment, violent, unnatural, from an industrial disease, or in state detention. Since 2024 in England and Wales, medical examiners scrutinise all deaths not investigated by the coroner. Doctors should not complete a certificate if the cause is uncertain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e716b1ae-eacf-506f-80ca-bc48010cc898', 'e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'A', 'Wait 7 days then complete it', false, 0),
  ('34ef06b4-8e3a-51bf-b5ec-3bdd65899a1b', 'e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'B', 'Ask the family what to write', false, 1),
  ('3eeb50ad-ecf3-5a8d-ad77-8b1009ce514e', 'e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'C', 'Refer the death to the coroner (and medical examiner)', true, 2),
  ('c707f98f-2c05-5d2e-9fef-c9bf9172acbb', 'e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'D', 'Complete the death certificate with ''surgical complication''', false, 3),
  ('7be0305e-b372-5daf-acc2-dd8315d6a97d', 'e2a2b028-7504-57ae-9e54-a333cfa6fe2c', 'E', 'Complete a cremation form only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor is offered expensive concert tickets by a drug company representative in return for considering prescribing a new drug. What is the SINGLE most appropriate response?', 'GMC guidance says doctors must not accept gifts or hospitality that may affect, or be seen to affect, their judgement about patient care. Conflicts of interest must be declared. Prescribing should be based on clinical evidence and the patient''s best interests.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7651c4eb-4feb-54be-bc0d-279e2f550751', '1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'A', 'Accept if it is under £500', false, 0),
  ('9e71e47c-f082-5a64-93c2-e62ee75e6eac', '1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'B', 'Decline the gift, as it could influence or be seen to influence prescribing', true, 1),
  ('893ccd9f-ed33-54f5-9bb1-b84d4c767e36', '1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'C', 'Accept and prescribe the drug', false, 2),
  ('8c110141-40f8-5009-af15-d5cf24cf4016', '1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'D', 'Accept as long as it is declared', false, 3),
  ('e2d02ddd-02ee-589a-bdb3-cda15fb47d09', '1ae9a6d3-74c1-5f0e-b145-ae4a42daf2ab', 'E', 'Accept and give tickets to colleagues', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4838ed7a-73f5-5773-b666-31874da5a545', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 60 year old patient asks to see her medical records. What is the SINGLE most accurate statement about her right of access?', 'Under UK GDPR and the Data Protection Act 2018, patients can access their health records by subject access request, usually free and within one month. Information may be withheld if disclosure is likely to cause serious harm to the patient or others, or if it identifies third parties without consent. The Access to Health Records Act covers deceased patients'' records.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('525005c7-67c6-5df9-a458-cf9f4223d4d7', '4838ed7a-73f5-5773-b666-31874da5a545', 'A', 'She has no right to see her records', false, 0),
  ('973bc3bc-3b9a-5850-bb49-1647bf0baca0', '4838ed7a-73f5-5773-b666-31874da5a545', 'B', 'Access requires a court order', false, 1),
  ('7f148494-489f-577c-ab04-061be62ef3e5', '4838ed7a-73f5-5773-b666-31874da5a545', 'C', 'Only her solicitor can request them', false, 2),
  ('3bc26727-24c1-5a89-9623-aa1918d4b136', '4838ed7a-73f5-5773-b666-31874da5a545', 'D', 'She has a right of access under data protection law (UK GDPR), with limited exceptions such as information likely to cause serious harm', true, 3),
  ('25ab10ca-0544-5713-8ad3-8a1f9ff0d828', '4838ed7a-73f5-5773-b666-31874da5a545', 'E', 'She must pay £500', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('238bcc03-37a1-57a1-a020-b9308340610a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A newly qualified doctor is asked by a senior to perform a procedure she has never done or been trained in, while unsupervised. What is the SINGLE most appropriate response?', 'GMC Good Medical Practice says doctors must recognise and work within the limits of their competence. She should explain this and seek appropriate supervision. Patient safety comes first. This is not refusing to help, because she should make sure the patient''s needs are met by someone competent.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f624168f-3969-5c51-b400-df9d444aeaa6', '238bcc03-37a1-57a1-a020-b9308340610a', 'A', 'Do it anyway to avoid conflict', false, 0),
  ('44ed89a2-7704-5dcc-96f8-f9d71832e31d', '238bcc03-37a1-57a1-a020-b9308340610a', 'B', 'Ask a medical student to do it', false, 1),
  ('b99d66dc-61e9-57a8-9e60-1a48b349026c', '238bcc03-37a1-57a1-a020-b9308340610a', 'C', 'Explain she is not competent to do it unsupervised and seek supervision or training', true, 2),
  ('d25991a4-cfdf-509d-831c-c40db4c7c285', '238bcc03-37a1-57a1-a020-b9308340610a', 'D', 'Refuse and leave the patient', false, 3),
  ('fac5f79e-131c-5be6-a0dc-3cc106ca8999', '238bcc03-37a1-57a1-a020-b9308340610a', 'E', 'Watch a video and then perform it', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A GP is asked by a patient''s wife whether her husband, who is also a patient, has been treated for a sexually transmitted infection. The husband has not given consent. What is the SINGLE most appropriate response?', 'Spouses or family members have no automatic right to a patient''s information. The GP should not confirm or deny without consent. The wife can be encouraged to talk to her husband and offered her own STI testing. Partner notification is usually done through sexual health services with the patient''s agreement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('701886c9-b547-5f07-b78e-f07d5b682a3a', 'e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'A', 'Tell her to ask the practice manager', false, 0),
  ('ee52951c-30a8-542d-935d-529f3c2fca4a', 'e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'B', 'Do not disclose without the husband''s consent', true, 1),
  ('c7fd1499-2cc3-53be-b013-67fcf7047fb3', 'e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'C', 'Disclose because she may be at risk, without further steps', false, 2),
  ('91e64ef0-0e71-507b-90aa-ef2a69ab3e75', 'e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'D', 'Disclose only the test result', false, 3),
  ('4aa38c33-dcf8-5427-b512-1e8a782389a3', 'e3d3da43-554f-56cd-bc58-2d4f699aee1f', 'E', 'Disclose as she is his wife', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7598d194-fd51-5c13-9715-25a07c02bdd9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 45 year old man is admitted for elective surgery. On the consent form the surgeon has written ''and proceed'' without discussing an extra possible procedure. During surgery, an unexpected but non-urgent finding is seen. What is the SINGLE most appropriate action?', 'Consent covers only the procedures discussed. Additional non-urgent procedures should not be carried out without consent, even if beneficial. They should be discussed once the patient can decide. Only treatment that is immediately necessary to save life or prevent serious deterioration can be given without consent. Montgomery (2015) requires disclosure of material risks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6ac350a2-1adb-503e-9b8a-3c60a521c376', '7598d194-fd51-5c13-9715-25a07c02bdd9', 'A', 'Do not perform the additional non-urgent procedure; discuss it with the patient when he has capacity', true, 0),
  ('2cbd88ec-50a5-52a4-bbf4-f38e844d875b', '7598d194-fd51-5c13-9715-25a07c02bdd9', 'B', 'Perform any procedure seen as beneficial', false, 1),
  ('084d7bb6-ae17-5d57-abd7-6aead6ab1843', '7598d194-fd51-5c13-9715-25a07c02bdd9', 'C', 'Perform the procedure as ''and proceed'' covers everything', false, 2),
  ('4c35a95e-8f95-571d-9e97-8a25ff4429f9', '7598d194-fd51-5c13-9715-25a07c02bdd9', 'D', 'Ask the anaesthetist to consent', false, 3),
  ('b8a9d18a-f275-5d29-8421-31d6454607c3', '7598d194-fd51-5c13-9715-25a07c02bdd9', 'E', 'Ask the family in the waiting room', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A patient asks which risks a doctor must discuss before an operation. According to the Montgomery ruling, what must doctors disclose?', 'Montgomery v Lanarkshire Health Board (2015) replaced the Bolam test for consent. Doctors must take reasonable care to ensure the patient is aware of any material risks and reasonable alternatives, including no treatment. Materiality depends on what matters to the individual patient, not a fixed percentage.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b2b4945c-a24c-5892-9520-8c1eb4adfceb', '7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'A', 'Any material risks — those a reasonable person in the patient''s position would consider significant, or that the doctor knows this patient would', true, 0),
  ('b6372ec8-4bf0-58c5-89da-24216a24f36a', '7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'B', 'No risks if the operation is routine', false, 1),
  ('6c6d1421-85da-59e1-a0a6-da20d1a984e7', '7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'C', 'Only risks a responsible body of doctors would disclose', false, 2),
  ('454788ff-d23d-5125-b419-b60223020c98', '7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'D', 'Only risks the patient asks about', false, 3),
  ('4e9c8d4f-0fad-526c-82ea-ec15243854fc', '7918a8c2-0036-50e3-8d9b-7394b2d849aa', 'E', 'Only risks above 1%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 25 year old woman with anorexia nervosa and a BMI of 12.5 kg/m2 refuses nasogastric feeding. She is deemed to lack capacity about this decision because of her illness. Which legal framework allows feeding against her will as treatment for her mental disorder?', 'Under the Mental Health Act, feeding can be treatment for the mental disorder itself in anorexia nervosa (case law: Re KB, Riverside Mental Health Trust v Fox). The MHA can therefore authorise nasogastric feeding against her will when she is detained. Decisions should be made with specialist eating disorder input and, where possible, the least restrictive approach.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0738b091-f181-5ffa-b0d9-4046590c3659', 'da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'A', 'No legal framework allows this', false, 0),
  ('560ca765-2447-575e-ac15-46ddb603543c', 'da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'B', 'Common law', false, 1),
  ('0ea60ec6-4ee7-557a-8726-02f84ee49ad9', 'da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'C', 'A Lasting Power of Attorney', false, 2),
  ('19451157-9199-5e3b-95ac-3ea11ee383a0', 'da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'D', 'The Mental Capacity Act only', false, 3),
  ('ee87f14f-e5d8-5031-bedd-599f616800b9', 'da309eb4-2a84-5e41-8642-94b2d2fd86cb', 'E', 'The Mental Health Act (feeding as treatment for anorexia nervosa)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'An 8 year old boy has severe bacterial meningitis. His parents, who are Jehovah''s Witnesses, refuse a blood transfusion that the team believes is life-saving. There is no time to obtain a court order. What is the SINGLE most appropriate action?', 'Parents cannot refuse life-saving treatment for a child when it is clearly in the child''s best interests. In an emergency where delay would be harmful, doctors can give necessary treatment. In non-emergency situations, a court order (specific issue order) should be sought. Alternatives to blood should be used where possible, and the decision documented with senior input.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('da35c4f9-741f-5816-a3fa-02f551921c07', '49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'A', 'Wait for a court order before acting', false, 0),
  ('67f2a2a6-fb5b-5ba6-a0c6-1e38a31ca1a9', '49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'B', 'Respect the parents'' refusal', false, 1),
  ('37a4944d-0fcd-55f8-9703-e61fe100d201', '49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'C', 'Ask the boy to decide', false, 2),
  ('1b53f87f-73a8-5fc5-9caf-c2f96136f8d8', '49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'D', 'Give the transfusion in an emergency, acting in the child''s best interests', true, 3),
  ('5197a969-5eb8-5ebb-a2c1-0e09a0a9d63c', '49f93254-5de4-57c5-9fc0-dbcf0c3aa97e', 'E', 'Discharge the child', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0b29371e-7752-5c2c-8077-991644799122', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 65 year old man with motor neurone disease, who has capacity, asks his doctor to help him end his life. What is the SINGLE most appropriate response?', 'Assisted suicide and euthanasia are illegal in England and Wales (Suicide Act 1961), although legislation is being debated. Doctors should explore the patient''s fears and suffering, assess for depression and optimise palliative care. Patients can refuse life-sustaining treatment, including NIV. Withdrawing treatment at a capacitous patient''s request is lawful.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7ad29058-43a4-5dbb-ac32-347c073d9531', '0b29371e-7752-5c2c-8077-991644799122', 'A', 'Refer him to a clinic abroad', false, 0),
  ('ccb3b0e3-ad92-5338-bf01-a19ad526ddae', '0b29371e-7752-5c2c-8077-991644799122', 'B', 'Ignore the request', false, 1),
  ('b4142994-9967-5fe2-98fc-ab664a7cd0e4', '0b29371e-7752-5c2c-8077-991644799122', 'C', 'Explain that assisting suicide is illegal in England and Wales, explore his concerns and offer palliative support', true, 2),
  ('e0feb15d-8c28-5e40-aea9-1713b8c8e628', '0b29371e-7752-5c2c-8077-991644799122', 'D', 'Detain him under the Mental Health Act', false, 3),
  ('515519dd-0525-5f38-b01a-c052cce9ac2c', '0b29371e-7752-5c2c-8077-991644799122', 'E', 'Prescribe a lethal dose of medication', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor notices that a colleague has been making repeated errors and seems exhausted, mentioning he is very stressed at home. Patients have not been harmed. What is the SINGLE most appropriate first action?', 'GMC guidance encourages doctors to support colleagues with health problems and to protect patients. A supportive conversation and encouraging him to seek help (GP, occupational health, Practitioner Health) is appropriate first. If patient safety is at risk or there is no improvement, concerns should be escalated to a senior colleague or clinical director.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0e8c30a2-5c9b-5ed3-8084-90048863ab98', 'bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'A', 'Ignore it', false, 0),
  ('9bb7c9fb-5c20-5404-afa3-f3073bf0968f', 'bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'B', 'Post about it on social media', false, 1),
  ('067686f2-8443-5566-aef1-7659cf3e0016', 'bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'C', 'Discuss it with patients', false, 2),
  ('c0909899-e0c6-5bcd-8953-d4aed26ffbf7', 'bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'D', 'Report him to the GMC immediately', false, 3),
  ('b833a9e0-ec44-52d5-8efa-ab61e9d4051d', 'bf939b0b-da3b-59a7-80c6-84d8515d4a28', 'E', 'Speak supportively to the colleague and encourage him to seek help (e.g. GP, occupational health), escalating if patient safety is at risk', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cb93810c-f24b-5a4b-ac89-124662438ac9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 38 year old woman is attending for a cosmetic procedure and asks about the qualifications of the person doing it. A doctor overhears a colleague telling patients he is a consultant surgeon when he is not. What is the SINGLE most appropriate action?', 'Misrepresenting qualifications is a serious probity issue that undermines patient trust and safety. GMC guidance requires doctors to raise such concerns through appropriate channels (senior colleague, clinical director, responsible officer), and GMC referral may be needed. Doctors must be honest about their qualifications and experience.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a94eb63a-f231-58e5-82e0-17dbdaafee09', 'cb93810c-f24b-5a4b-ac89-124662438ac9', 'A', 'Raise the concern with a senior/responsible officer, as honesty and probity issues may need GMC referral', true, 0),
  ('0222c1c9-c395-51e6-a388-1504d824278b', 'cb93810c-f24b-5a4b-ac89-124662438ac9', 'B', 'Tell the patients yourself and leave', false, 1),
  ('9577e0fa-e141-50b1-8cce-4d9b16e75ca3', 'cb93810c-f24b-5a4b-ac89-124662438ac9', 'C', 'Ignore it as it is not your business', false, 2),
  ('f8cf594f-1b52-5473-bc68-aa9a22e9df61', 'cb93810c-f24b-5a4b-ac89-124662438ac9', 'D', 'Post about it online', false, 3),
  ('917c2e6a-eacb-5e6b-ba11-d8a8a102be99', 'cb93810c-f24b-5a4b-ac89-124662438ac9', 'E', 'Confront the colleague in front of patients', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c26bd106-3700-5fcc-bb04-826e0083a860', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 93 year old woman is in hospital having completed treatment for a urinary tract infection. She has mild dementia. She lives alone. She is medically fit for discharge and is keen to go home but her daughter is unhappy about this course of action. Which is the most appropriate next step?', 'Under the Mental Capacity Act, capacity is decision-specific and presumed. A diagnosis of mild dementia does not mean she lacks capacity. Her capacity to decide on discharge should be formally assessed. If she has capacity, her decision stands even if her daughter disagrees. An advocate (IMCA) is only needed if she lacks capacity and has no one appropriate to consult.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7dbbc1c8-c5db-5ea9-95b3-4e6f6b08c296', 'c26bd106-3700-5fcc-bb04-826e0083a860', 'A', 'Arrange for an assessment by an independent advocate', false, 0),
  ('c0991e52-cfb0-562c-adaa-27e5bfb1d09b', 'c26bd106-3700-5fcc-bb04-826e0083a860', 'B', 'Assess patient’s mental capacity to decide about her discharge', true, 1),
  ('b7e953ca-ea66-5d5e-ada6-db1bd0c03809', 'c26bd106-3700-5fcc-bb04-826e0083a860', 'C', 'Contact local psychiatry team for assessment', false, 2),
  ('9caa17a3-41fc-5fe7-b68f-79de9be75701', 'c26bd106-3700-5fcc-bb04-826e0083a860', 'D', 'Discharge to a nursing home', false, 3),
  ('cd84ca88-3172-55a4-93a4-6bd573d47515', 'c26bd106-3700-5fcc-bb04-826e0083a860', 'E', 'Keep in hospital until daughter agrees', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 20 year old man is brought to the Emergency Department with status epilepticus and pneumonia. He has worsening respiratory failure despite mechanical ventilation. He has a chronic life limiting neurological condition and drug resistant epilepsy. He has severe global developmental delay. He has had three previous admissions to the intensive care unit this year. His family want to continue with active treatment but the intensive care team have advised that the patient should not be ventilated. Which is the most appropriate next step in management?', 'When the clinical team and the family disagree about treatment for a patient who lacks capacity, the first step is open discussion. The team should explain its concerns, explore the family''s views and seek consensus in the patient''s best interests, sometimes with a second opinion or mediation. Court involvement is a last resort.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('579d893d-8567-543a-b35a-197a8a1af5ad', 'cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'A', 'Apply for a court order to withdraw treatment', false, 0),
  ('544f542d-cd2a-53eb-8f32-17cfcdcebec0', 'cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'B', 'Complete a Do Not Resuscitate (DNR) form', false, 1),
  ('1fe54b31-76a5-5a15-9324-6f562c05d593', 'cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'C', 'Discuss the concerns of the intensive care team with the family', true, 2),
  ('dc5970f1-ca5f-5364-8a40-301b47433d8f', 'cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'D', 'Follow the advice of the intensive care team', false, 3),
  ('b1243f83-90e9-5d38-82e3-c997caf0cb64', 'cf510d64-fe2a-5b1c-8d49-41cb5f77d96e', 'E', 'Follow the family wishes for active treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('933873b1-653f-5f74-a169-c3dc2ec706e7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 75 year old man has attended the Emergency Department by his carers on two occasions over a 6 week period with bruising to his forearms and face. He has dementia. He is physically fit and takes no regular prescription medication. Investigations: Haemoglobin 146 g/L (130–175) White blood count 7.2 x 10⁹/L (4.0–11.0) Platelets 250 x 10⁹/L (150–400) INR 1.0 (1.0) Which is the most likely explanation for his bruising?', 'Recurrent unexplained bruising to the face and forearms in a dependent older adult with dementia, with a normal blood count and clotting, raises concern about abuse (non-accidental injury). An adult safeguarding referral should be made, following local procedures.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('05a26b97-7760-529e-b280-6d4fda463f20', '933873b1-653f-5f74-a169-c3dc2ec706e7', 'A', 'Bleeding disorder', false, 0),
  ('100a1f4f-ce8a-58ad-945a-745f1707e3a7', '933873b1-653f-5f74-a169-c3dc2ec706e7', 'B', 'Non-accidental injury', true, 1),
  ('5833e49f-bd50-5d7a-b8ef-aca36d917087', '933873b1-653f-5f74-a169-c3dc2ec706e7', 'C', 'Occult malignancy', false, 2),
  ('0fe1989f-5343-5d6d-a189-1c20074d1827', '933873b1-653f-5f74-a169-c3dc2ec706e7', 'D', 'Scurvy', false, 3),
  ('e43d57d0-90bb-54db-9d7e-f3af3d2b60da', '933873b1-653f-5f74-a169-c3dc2ec706e7', 'E', 'Vasculitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e678ab8c-8069-5112-966d-9b971fc3683c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A colleague who is a doctor in training has been seen taking photographs of patients’ X-rays on her personal smart phone. She explains that the images are for her personal study and have not been shared. Which is the most appropriate next step?', 'Taking photos of patient images on a personal phone breaches confidentiality and information governance, even for study. The appropriate first step is to raise it with her clinical supervisor so it can be dealt with supportively. GMC referral is not proportionate at this stage.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('89b6d4c8-2702-5a8e-b435-6a035c8d8905', 'e678ab8c-8069-5112-966d-9b971fc3683c', 'A', 'Inform her clinical supervisor', true, 0),
  ('864a6ae9-197a-5428-91f5-5bf219d80d2d', 'e678ab8c-8069-5112-966d-9b971fc3683c', 'B', 'Insist she gets written consent from the patients involved', false, 1),
  ('06455a40-ef3c-5135-a5aa-ab27504fbbd7', 'e678ab8c-8069-5112-966d-9b971fc3683c', 'C', 'Notify the police', false, 2),
  ('be610116-f857-5dd9-9a74-d3c632cd2483', 'e678ab8c-8069-5112-966d-9b971fc3683c', 'D', 'Refer to the General Medical Council', false, 3),
  ('9f980de7-7af1-5312-b246-4d569439654e', 'e678ab8c-8069-5112-966d-9b971fc3683c', 'E', 'Submit an incident report', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d7100ecf-4447-53cc-8813-7ca8807d6773', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'Dr A, a doctor in training on the psychiatric team, learns that Dr B, a team member who is also a doctor in training , is using social media to befriend a 30 year old patient who was recently discharged from the psychiatric unit. This interaction occurs outside of work. Which is the most appropriate next step for Dr A to take?', 'Doctors must keep professional boundaries and must not pursue personal relationships with current or recent patients, including on social media. The first step is to raise it directly with the colleague and remind him of GMC guidance. Escalate to his supervisor if the behaviour continues or there is a safeguarding concern.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('acfdbf65-d515-59f3-9fa2-83fc1fadf3a1', 'd7100ecf-4447-53cc-8813-7ca8807d6773', 'A', 'Contact adult safeguarding team', false, 0),
  ('d579d315-73b2-532d-9b2c-476a3c6744c1', 'd7100ecf-4447-53cc-8813-7ca8807d6773', 'B', 'Inform Dr B’s consultant and educational supervisor', false, 1),
  ('ea149494-5dee-50b4-8a2c-5fddef0b05f8', 'd7100ecf-4447-53cc-8813-7ca8807d6773', 'C', 'No further action required as Dr B has a right to privacy outside work', false, 2),
  ('0e8abea4-16b2-5d7a-9237-a83a276a8e06', 'd7100ecf-4447-53cc-8813-7ca8807d6773', 'D', 'Remind Dr B that this is not in keeping with GMC good medical practice', true, 3),
  ('106b1869-9bcf-532d-a7b2-59b7cea01e1e', 'd7100ecf-4447-53cc-8813-7ca8807d6773', 'E', 'Report Dr B to the GMC', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 45 year old woman is seen in the Emergency Department after a fall. She is in severe pain and has a Colles fracture which needs surgical fixation. She has severe learning difficulties She is distressed and tearful during a conversation about the operation and does not follow the discussion. When her carer arrives, she is unable to explain to her carer what the operation involves. Which feature best demonstrates that she lacks capacity?', 'Capacity is decision-specific. Under the Mental Capacity Act, the key finding is whether she can understand, retain, weigh up and communicate the information. Being unable to explain what the operation involves shows she cannot understand or retain the information. A learning disability, distress or pain alone does not mean she lacks capacity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5a617ef-8c13-5763-bf79-40193cd8b7cc', 'b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'A', 'Carer involved in her care', false, 0),
  ('d2a99209-7d06-5706-9658-426be167b002', 'b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'B', 'Severe learning disability', false, 1),
  ('7518f23e-b9f9-5a22-b388-c65d046e7e39', 'b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'C', 'Severe pain', false, 2),
  ('d003cce6-f20c-5006-80ee-1976db204816', 'b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'D', 'Tearful and distressed', false, 3),
  ('4d09779d-ef22-5246-891e-bd4309083409', 'b6b9d7a7-3b9d-5789-8d88-061c0fb8fe48', 'E', 'Unable to explain what the operation involves', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 76 year old woman has severe dementia and her son is concerned about her safety at home so attends with his mother at her GP surgery.. She lives alone. Her son has installed video cameras in her home to keep an eye on her as she has had several falls in the past. On one occasion she left her home and was found wandering in the street. He now locks her doors to prevent her leaving. Her GP assesses her as lacking capacity with regards to her care and treatment Which is the most appropriate course of action?', 'A person with severe dementia who wanders, falls and is under video surveillance at home may be at risk, and the cameras may also raise concerns about deprivation of liberty and privacy. Raising concerns with the local adult safeguarding team ensures a proper multi-agency assessment of her best interests.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('92b9db80-c36e-58f4-8bd5-f0c316d16b22', '5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'A', 'Advise that house key is kept with the neighbour in case of emergency', false, 0),
  ('088efd81-62d4-568e-a55b-d9eadab0af36', '5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'B', 'Arrange regular district nurse visits', false, 1),
  ('07281d55-28a0-5e0e-9b91-6975ed3deb47', '5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'C', 'Contact local care home and arrange placement in 24 hour care', false, 2),
  ('429e1750-1ae7-5b78-9e01-bed9bd581ced', '5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'D', 'Contact local safeguarding team to raise concerns', true, 3),
  ('6e9de819-65e3-5a36-ae00-c3ae89ba4bf4', '5cfd247a-6f1d-5645-83c6-2d5a9c47646d', 'E', 'No action needed as son is acting in patient''s best interest', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('779413a2-f39a-5ed4-a755-40ecda9adac5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 75 year old man has rectal bleeding for 2 weeks and is seen at home by his GP. He has dementia and prostate cancer. He lives with his wife who is his main carer. Which is the most appropriate next step?', 'For a person with dementia who may lack capacity to decide about investigation of rectal bleeding, a best interests decision is needed under the Mental Capacity Act. It involves the patient as far as possible, his wife and the clinicians, weighing up the burdens and benefits of colonoscopy given his other conditions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('405a17ec-48a1-5b17-8296-b5c58564ac3c', '779413a2-f39a-5ed4-a755-40ecda9adac5', 'A', 'Arrange immediate admission to hospital', false, 0),
  ('8a3eceee-bb34-5e5f-bbda-8ce49663eb06', '779413a2-f39a-5ed4-a755-40ecda9adac5', 'B', 'Arrange best interests meeting', true, 1),
  ('ff62b7b6-3c54-5eff-86a1-798cd0e08c57', '779413a2-f39a-5ed4-a755-40ecda9adac5', 'C', 'Arrange urgent colonoscopy', false, 2),
  ('05077ad4-fdef-5110-a4a7-0e1cfae522fa', '779413a2-f39a-5ed4-a755-40ecda9adac5', 'D', 'No investigation needed due to his pre-existing condition', false, 3),
  ('99560585-f71e-563d-8010-762c668f95bc', '779413a2-f39a-5ed4-a755-40ecda9adac5', 'E', 'Refer to palliative care team', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('074f8a23-6809-58a6-9f7c-600ef9d02230', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A doctor in training overhears a senior doctor colleague complaining to members of her team about an argument she had with an unnamed patient in the hospital canteen Which is the most appropriate action for the junior doctor to take?', 'Discussing an argument with a patient in a public place may breach professionalism and possibly confidentiality. The proportionate first step is to speak to the colleague privately and explain the concern, escalating only if it continues or is serious.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc61ff2f-9de1-5eba-8625-2a29b1a30ecc', '074f8a23-6809-58a6-9f7c-600ef9d02230', 'A', 'Inform the GMC', false, 0),
  ('8310909e-dfcc-54af-a2da-f43762a8d158', '074f8a23-6809-58a6-9f7c-600ef9d02230', 'B', 'Inform their clinical supervisor', false, 1),
  ('45b5e7e3-8818-56d5-a56f-344be7a8b7f5', '074f8a23-6809-58a6-9f7c-600ef9d02230', 'C', 'No action is required', false, 2),
  ('ff3fe46f-646d-5f44-aaba-62158a3d7dbf', '074f8a23-6809-58a6-9f7c-600ef9d02230', 'D', 'Speak to the colleague privately', true, 3),
  ('52cd9f63-5da5-507a-b62e-d267f8e633f1', '074f8a23-6809-58a6-9f7c-600ef9d02230', 'E', 'Submit a Critical Incident Report END', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4e5c5a8f-477a-5438-8fba-b0eb76063471', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 81 year old man has had three falls in 6 months. He lives alone, takes 9 medications including zopiclone and amitriptyline, and has a slow gait with poor balance on the ''timed up and go'' test. His lying and standing BP shows no postural drop. What is the SINGLE most appropriate intervention to reduce his risk of further falls?', 'NICE recommends a multifactorial falls risk assessment for older people who have fallen repeatedly. It includes gait and balance, strength, medication review (especially psychotropics such as hypnotics and tricyclics), postural hypotension, vision, continence, home hazards, cognition and bone health. Interventions include strength and balance training, stopping or reducing risky medications, and home hazard assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4b0eec6a-7908-5e17-bd1f-a10d9268445d', '4e5c5a8f-477a-5438-8fba-b0eb76063471', 'A', 'Reassure him that falls are normal at his age', false, 0),
  ('a4245d75-bd8d-5553-a910-9284fec28650', '4e5c5a8f-477a-5438-8fba-b0eb76063471', 'B', 'Multifactorial falls risk assessment with medication review and a strength and balance programme', true, 1),
  ('f6466939-7044-502a-8003-4b2a00896893', '4e5c5a8f-477a-5438-8fba-b0eb76063471', 'C', 'Prescribe a hip protector only', false, 2),
  ('d7456f0e-c6b7-5db5-b9d8-050a0dc8761f', '4e5c5a8f-477a-5438-8fba-b0eb76063471', 'D', 'Admit him to a care home', false, 3),
  ('47518674-71fa-5b63-8540-81cd08f058df', '4e5c5a8f-477a-5438-8fba-b0eb76063471', 'E', 'Start an anticoagulant', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bf7284c7-e818-5600-b24c-353c13c2bcf0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 86 year old woman with moderate Alzheimer''s disease lives in a care home. Staff report that over the last 2 days she has become more confused, has not opened her bowels for 6 days and has stopped eating. Abdominal examination shows a palpable, indentable mass in the left iliac fossa. Her bladder is not palpable. What is the SINGLE most likely precipitant of her worsening confusion?', 'Acute worsening of confusion in a person with dementia is delirium until proven otherwise. Constipation is a common, easily missed precipitant, and an indentable left-sided mass suggests faecal loading. Other common causes are infection, urinary retention, pain, medication, dehydration and electrolyte disturbance (PINCH ME). Treating constipation with laxatives or enemas often improves the confusion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('50746a6a-96f8-5d05-8358-2860f8225887', 'bf7284c7-e818-5600-b24c-353c13c2bcf0', 'A', 'Brain tumour', false, 0),
  ('bf4c1ebf-8398-52f9-afb6-a695d555c46a', 'bf7284c7-e818-5600-b24c-353c13c2bcf0', 'B', 'Constipation', true, 1),
  ('0e11c541-38ed-5b2b-9906-915b2267dd4a', 'bf7284c7-e818-5600-b24c-353c13c2bcf0', 'C', 'Progression of Alzheimer''s disease', false, 2),
  ('2aa39e34-da46-5226-a3f0-e6b756b1fffd', 'bf7284c7-e818-5600-b24c-353c13c2bcf0', 'D', 'Depression', false, 3),
  ('0b0676b8-8f16-5015-95a8-28f8b9c4e31c', 'bf7284c7-e818-5600-b24c-353c13c2bcf0', 'E', 'Normal pressure hydrocephalus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3a46d258-a2d2-5bed-a5ae-128808427765', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 79 year old man is reviewed on the ward. His medications are amlodipine, ramipril, atorvastatin, omeprazole, oxybutynin, amitriptyline, zopiclone, aspirin and paracetamol. He has new constipation, confusion and urinary retention. Which drug is MOST likely to be responsible for these new symptoms?', 'Oxybutynin is a highly anticholinergic drug, and with amitriptyline it adds to his total anticholinergic burden. In older people this causes confusion, constipation, urinary retention, dry mouth and an increased risk of falls and dementia. STOPP/START criteria and anticholinergic burden scores help with deprescribing. Mirabegron is an alternative for overactive bladder in frail older people.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f7770ace-73aa-543d-ae10-e56b8ed45d84', '3a46d258-a2d2-5bed-a5ae-128808427765', 'A', 'Ramipril', false, 0),
  ('d79ccbda-e954-5b14-abde-84fbb3109be6', '3a46d258-a2d2-5bed-a5ae-128808427765', 'B', 'Oxybutynin', true, 1),
  ('56293f8e-3cf4-5a0e-b18b-13a67d172712', '3a46d258-a2d2-5bed-a5ae-128808427765', 'C', 'Atorvastatin', false, 2),
  ('ec0bdf57-dbdb-510f-a222-496ebbcf6d57', '3a46d258-a2d2-5bed-a5ae-128808427765', 'D', 'Omeprazole', false, 3),
  ('b1415fc1-2f83-5794-990e-b3fcd92ec8c0', '3a46d258-a2d2-5bed-a5ae-128808427765', 'E', 'Paracetamol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 82 year old woman has been admitted for falls. Her medication list includes amlodipine, ramipril, indapamide, doxazosin, omeprazole, simvastatin, aspirin, alendronic acid and zopiclone. Which tool is MOST appropriate to identify potentially inappropriate medications?', 'STOPP/START criteria are validated tools for medication review in older people. STOPP identifies potentially inappropriate drugs (such as long-term benzodiazepines or Z-drugs in fallers, or alpha-blockers with orthostatic hypotension). START identifies potentially omitted drugs that are indicated. Structured medication review reduces falls and adverse drug events.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c2d00d70-d3e2-547b-88fd-7711a6ebfdc8', '66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'A', 'STOPP/START criteria', true, 0),
  ('74115ce2-05e1-5e54-8376-4b6f13784493', '66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'B', 'CURB-65', false, 1),
  ('40ef073b-6034-572a-8cc5-f437a3fc62a0', '66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'C', 'Wells score', false, 2),
  ('d15bb0dc-59d0-5e58-82d4-9c9812f18465', '66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'D', 'Glasgow Coma Scale', false, 3),
  ('89c03370-7891-5dca-9fe2-8d19c2bb91e7', '66dc94bb-7ff0-50f3-97a9-8adc9ecf15b2', 'E', 'CHA2DS2-VASc', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 84 year old man is admitted with pneumonia. He lives alone. On examination he is frail, with slow gait speed, unintentional weight loss and low grip strength. His Clinical Frailty Scale score is 6. What does this score indicate?', 'The Rockwood Clinical Frailty Scale runs from 1 (very fit) to 9 (terminally ill). A score of 6 is moderately frail, needing help with outside activities, housework and often bathing. Frailty predicts adverse outcomes and guides decisions about treatment escalation. Comprehensive geriatric assessment improves outcomes for frail older people.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('efd8355c-3488-56b0-a4fa-838069c97cea', 'bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'A', 'Managing well', false, 0),
  ('0415bcdf-a167-5fdd-920a-0ab0723f8083', 'bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'B', 'Terminally ill', false, 1),
  ('ac08025f-4c4a-551a-b0da-e41fcc625222', 'bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'C', 'Mildly frail with no assistance needed', false, 2),
  ('6930d24d-3a9a-587c-a1ce-6204b2ef7c1f', 'bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'D', 'Moderately frail — needs help with all outside activities and keeping house, and help with bathing', true, 3),
  ('07932755-a3af-52b4-922d-8a66f1198a6b', 'bc6bcbd7-3c2c-5c94-b5f7-f7ea1b8ccf70', 'E', 'Very fit', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c0276aeb-91ba-5018-be89-117ef5c651ad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 86 year old woman on a care-of-the-elderly ward has a 2 cm area of non-blanching redness over her sacrum with intact skin. She has limited mobility. What is the SINGLE most appropriate management?', 'Non-blanching redness of intact skin is a Category 1 pressure ulcer. Category 2 is partial thickness skin loss, Category 3 is full thickness skin loss, and Category 4 is full thickness tissue loss with exposed bone or tendon. NICE recommends risk assessment (such as the Waterlow score), pressure-redistributing mattresses, repositioning (at least every 6 hours, every 4 hours if high risk), nutrition and continence care.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cfba7edb-8791-521b-a8c2-42c5be205f01', 'c0276aeb-91ba-5018-be89-117ef5c651ad', 'A', 'Systemic antibiotics', false, 0),
  ('cf3468b9-c530-57ae-9c7c-69f6d036361f', 'c0276aeb-91ba-5018-be89-117ef5c651ad', 'B', 'No action as the skin is intact', false, 1),
  ('1e996fce-02eb-54fb-a2f5-373f4acda691', 'c0276aeb-91ba-5018-be89-117ef5c651ad', 'C', 'Pressure-relieving mattress, regular repositioning and skin care (Category 1 pressure ulcer)', true, 2),
  ('ed91e2e4-8e0a-5e15-8886-88feb2091507', 'c0276aeb-91ba-5018-be89-117ef5c651ad', 'D', 'Surgical debridement', false, 3),
  ('da32c6e0-cf6b-5fab-b446-c2d8d6244ca3', 'c0276aeb-91ba-5018-be89-117ef5c651ad', 'E', 'Topical steroid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 88 year old woman who lives alone has been found on the floor after an unwitnessed fall. She was on the floor for 10 hours. She is now alert. Her CK is 12,000 U/L and creatinine has risen. What is the SINGLE most likely complication?', 'A long lie after a fall can cause rhabdomyolysis (muscle breakdown with myoglobin release), leading to AKI, hyperkalaemia, pressure ulcers, hypothermia, dehydration and pneumonia. Management is aggressive IV fluids, monitoring urine output and electrolytes, and finding the cause of the fall. Older people at risk benefit from pendant alarms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7390e1ca-c140-5c2e-b92b-ce4f6cdee8b2', 'a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'A', 'Hypothermia only', false, 0),
  ('67c1b0d0-800a-5a67-9c0e-95921187ddfd', 'a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'B', 'Stroke', false, 1),
  ('5816078f-db86-5cc5-b21f-373aaebfbe5b', 'a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'C', 'Dehydration only', false, 2),
  ('ac2c2ecc-23f6-5e1c-87e2-b2fc7d59d01e', 'a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'D', 'Pulmonary embolism', false, 3),
  ('74bf53ae-a01c-5235-b2b3-5f049bd9acfe', 'a6c11165-412f-57b9-8d6e-085d3c2a2df9', 'E', 'Rhabdomyolysis with acute kidney injury', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cac01f43-88b4-509a-ba73-b7de72a47e21', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 79 year old woman has urinary incontinence. She describes a strong sudden urge to pass urine and often cannot reach the toilet in time. Urinalysis is normal. Bladder training has not worked. She has mild cognitive impairment. What is the SINGLE most appropriate drug treatment?', 'Urge incontinence or overactive bladder is managed first with bladder training for at least 6 weeks. In frail older people or those with cognitive impairment, antimuscarinics with a high anticholinergic burden (especially oxybutynin) should be avoided. Mirabegron (a beta-3 agonist) is an alternative, though it is contraindicated in severe uncontrolled hypertension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('edcbadb3-e3e2-55e2-b709-7203a20d5349', 'cac01f43-88b4-509a-ba73-b7de72a47e21', 'A', 'Tamsulosin', false, 0),
  ('7afe0f6f-6443-5075-bff7-c1abb22d42ab', 'cac01f43-88b4-509a-ba73-b7de72a47e21', 'B', 'Finasteride', false, 1),
  ('bfbe6095-c8b8-52c2-88df-45e8e1ba33fe', 'cac01f43-88b4-509a-ba73-b7de72a47e21', 'C', 'Oxybutynin immediate release', false, 2),
  ('3e9b3244-7289-5a35-86f0-531fa51b0a74', 'cac01f43-88b4-509a-ba73-b7de72a47e21', 'D', 'Desmopressin', false, 3),
  ('0b85cf63-3994-509c-8bfd-2dca610f92ea', 'cac01f43-88b4-509a-ba73-b7de72a47e21', 'E', 'Mirabegron (avoiding antimuscarinics with high cognitive burden, such as oxybutynin)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 80 year old man had a hip fracture repaired 3 days ago. On the orthogeriatric ward, a multidisciplinary review is planned. Which intervention has the MOST evidence for improving outcomes after hip fracture?', 'NICE recommends hip fracture care led by an orthogeriatric team, surgery on the day of or the day after admission, mobilisation on the day after surgery, falls and bone health assessment, nutritional support and early multidisciplinary rehabilitation. The National Hip Fracture Database audits these standards.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5b48b41-93f9-5aca-b8ba-f815d5ee12f9', '95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'A', 'Discharge directly home without rehabilitation', false, 0),
  ('db1fe733-b8b5-5248-8070-3d6be3ddf339', '95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'B', 'Delaying surgery for 1 week', false, 1),
  ('1b46a0b9-dcbf-58ad-aba6-fdaf7c6e42c5', '95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'C', 'Orthogeriatric-led comprehensive care with early mobilisation (day after surgery) and bone health assessment', true, 2),
  ('d19ff18d-65ee-59c1-9113-fede2bba552a', '95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'D', 'Bed rest for 2 weeks', false, 3),
  ('c7fcd9e9-5433-5e56-94a4-01a89c311a34', '95815c36-4d8a-5df2-9074-dc35ceb1ebd1', 'E', 'Routine urinary catheter for 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('407f505d-8f3a-5ea9-9561-bbd40114327c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 90 year old man with advanced dementia is in a nursing home. He now coughs and splutters with all meals and has lost weight. His family ask about a feeding tube (PEG). What is the SINGLE most appropriate advice?', 'In advanced dementia, PEG feeding has not been shown to prolong life, prevent aspiration or improve comfort, and it carries complications. Careful hand feeding (''risk feeding'' with texture modification), with a speech and language therapy assessment, is recommended. Decisions are made in his best interests under the Mental Capacity Act, involving the family and any advance care plan.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('57f30543-84f8-5722-9838-7bbc714547f3', '407f505d-8f3a-5ea9-9561-bbd40114327c', 'A', 'Feeding should be stopped completely', false, 0),
  ('a989f857-d37c-50c3-87e8-7b2d946b07ea', '407f505d-8f3a-5ea9-9561-bbd40114327c', 'B', 'IV fluids should be given long-term', false, 1),
  ('86b7619c-fe04-5c99-966b-91ad0e9d1bb9', '407f505d-8f3a-5ea9-9561-bbd40114327c', 'C', 'PEG feeding has not been shown to improve survival or comfort in advanced dementia; careful hand feeding is recommended', true, 2),
  ('bc26c881-43e3-59d2-9462-436c53095e8a', '407f505d-8f3a-5ea9-9561-bbd40114327c', 'D', 'PEG should always be inserted', false, 3),
  ('8a7388ee-6675-5cd1-b3d8-6d74be701098', '407f505d-8f3a-5ea9-9561-bbd40114327c', 'E', 'PEG feeding prolongs survival significantly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 78 year old man has had a gradual decline in function over months. His daughter is worried about his memory. Which tool is MOST appropriate as an initial cognitive assessment in primary care?', 'NICE recommends a brief structured cognitive instrument in non-specialist settings (such as 10-point cognitive screener, 6CIT, Mini-Cog or GPCOG), alongside blood tests to exclude reversible causes (FBC, U&E, LFT, calcium, glucose, TFTs, B12, folate). Referral to a memory service is made if dementia is suspected. Delirium and depression should be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7d103a3b-f6e2-53d5-9936-9eab0d6b4bf3', '5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'A', 'A validated brief cognitive test (e.g. 6CIT, Mini-Cog or GPCOG)', true, 0),
  ('01ef7277-2c15-5f11-a953-48d3fe0da3ce', '5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'B', 'Lumbar puncture', false, 1),
  ('9793e7e4-1eaa-5561-90b0-d78c02c4b508', '5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'C', 'MRI brain for all', false, 2),
  ('763b107b-ea93-5540-990d-995c43937ab2', '5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'D', 'EEG', false, 3),
  ('4affcb4d-5948-533a-9be4-08720617af38', '5f8d3e3b-c672-54c9-a0ce-75ef380d94ca', 'E', 'Genetic testing', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('323b6caf-15fd-5613-9690-52a73209eedd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 81 year old woman with type 2 diabetes, moderate frailty and recurrent falls has an HbA1c of 52 mmol/mol on gliclazide and metformin. She has had two hypoglycaemic episodes. What is the SINGLE most appropriate management?', 'In older, frail people, tight glycaemic control increases the risk of hypoglycaemia, falls and death without clear benefit. NICE recommends individualised, relaxed HbA1c targets. Sulfonylureas cause hypoglycaemia and should be reduced or stopped in favour of safer agents. This is part of deprescribing in frailty.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('48cec6b8-81c7-5a98-97a0-e22f9c266b10', '323b6caf-15fd-5613-9690-52a73209eedd', 'A', 'Intensify treatment to an HbA1c below 42 mmol/mol', false, 0),
  ('9c4e9de7-d9d0-5750-8353-89676d12441a', '323b6caf-15fd-5613-9690-52a73209eedd', 'B', 'Add insulin', false, 1),
  ('1d01908d-a3c5-597b-bc57-8f7f435e9767', '323b6caf-15fd-5613-9690-52a73209eedd', 'C', 'Add a second sulfonylurea', false, 2),
  ('4733c2f9-7b31-5f71-99d9-c1f82cd03928', '323b6caf-15fd-5613-9690-52a73209eedd', 'D', 'Increase gliclazide', false, 3),
  ('fbd2667f-ce37-55a2-9d0a-12e6f40d4b84', '323b6caf-15fd-5613-9690-52a73209eedd', 'E', 'Relax her glycaemic target and stop or reduce gliclazide', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 83 year old man takes simvastatin for primary prevention. He now has advanced cancer with a prognosis of a few months and finds taking many tablets burdensome. What is the SINGLE most appropriate action regarding the statin?', 'Deprescribing means reducing or stopping medications whose risks or burdens outweigh their benefits, particularly in frailty or limited life expectancy. Preventive medications such as statins take years to benefit, so they are reasonable to stop near the end of life. Decisions should be shared with the patient.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9d202057-06ae-5ec2-a547-97f693598917', 'bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'A', 'Discuss stopping the statin as part of deprescribing, because benefits take years to accrue', true, 0),
  ('7f17d906-5ab9-5746-a3e4-6e1ef2c4a2cf', 'bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'B', 'Continue all medications unchanged', false, 1),
  ('b2293fbd-2c61-53a9-8b44-69ae5c990392', 'bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'C', 'Switch to atorvastatin 80 mg', false, 2),
  ('dc05aeb4-08f7-5d19-9e90-1f8ab588b529', 'bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'D', 'Add ezetimibe', false, 3),
  ('6b2658c4-15f9-5b07-a7ff-1f0f0fe01240', 'bba615e7-c3ab-5872-b6ef-4dd88d34a698', 'E', 'Increase the statin dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 84 year old woman lives alone and has had several falls. She is at risk of a long lie. What is the SINGLE most appropriate intervention to reduce the risk of a long lie?', 'A long lie (lying on the floor for an hour or more after a fall) risks rhabdomyolysis, pressure ulcers, hypothermia, pneumonia and loss of confidence. A personal alarm, training in getting up from the floor, and multifactorial falls prevention reduce this risk. Home hazard assessment by an occupational therapist helps.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d3b3f7d9-da6a-5202-bc3a-fe2f44af8c2a', '64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'A', 'Admit to a nursing home', false, 0),
  ('6b7f053d-a3b4-5f64-a4db-a3df51d9cecc', '64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'B', 'Prescribe sedatives', false, 1),
  ('e563bdde-3e00-52a0-b310-bd902a40617b', '64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'C', 'Remove walking aids', false, 2),
  ('65b50309-866e-5bd5-90e1-603ca3edb01d', '64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'D', 'Restrict her to bed', false, 3),
  ('c4302430-7d8b-5c8b-b8dd-df80fa6b17ff', '64b36c91-c4cd-5bcd-ab65-262df834b8b7', 'E', 'Provide a personal alarm (pendant) and teach how to get up from the floor', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fb9eb879-c566-5bde-b7c4-c4528200724f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 86 year old man with mild dementia is admitted with pneumonia. Which intervention is MOST effective at reducing the risk of delirium during his admission?', 'NICE CG103 recommends multicomponent interventions to prevent delirium in at-risk patients (age 65 or over, cognitive impairment, hip fracture, severe illness). These include orientation, appropriate lighting and clocks, avoiding ward moves, ensuring glasses and hearing aids are used, hydration and nutrition, early mobilisation, sleep promotion, pain management, avoiding constipation and catheters, and medication review.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5fd5e43d-0c64-5114-aaf5-844ecba19488', 'fb9eb879-c566-5bde-b7c4-c4528200724f', 'A', 'Physical restraints', false, 0),
  ('12a43bbf-da9d-5589-a43c-44cf5d166b2e', 'fb9eb879-c566-5bde-b7c4-c4528200724f', 'B', 'Multicomponent non-pharmacological interventions (orientation, hydration, sleep, mobility, glasses/hearing aids)', true, 1),
  ('bedad649-b897-5700-8f01-15818d82fb5a', 'fb9eb879-c566-5bde-b7c4-c4528200724f', 'C', 'Routine benzodiazepines at night', false, 2),
  ('a8b4d246-bec4-5b27-84b3-95d66d384723', 'fb9eb879-c566-5bde-b7c4-c4528200724f', 'D', 'Routine prophylactic antipsychotics', false, 3),
  ('33874a38-9259-52aa-a4e9-7e2cd7963935', 'fb9eb879-c566-5bde-b7c4-c4528200724f', 'E', 'Moving wards frequently', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 79 year old woman with dementia is admitted to hospital. She may lack capacity to consent to staying on the ward, and she is under continuous supervision and not free to leave. What is the SINGLE most appropriate legal consideration?', 'When a person who lacks capacity to consent to their care arrangements is under continuous supervision and control and not free to leave (''acid test'', Cheshire West 2014), this is a deprivation of liberty that needs legal authorisation. In England, that is DoLS (to be replaced by the Liberty Protection Safeguards). The care must be in the person''s best interests and the least restrictive option.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d00c1f5c-832c-5ab2-86fe-46dd35b3f92a', '3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'A', 'No legal framework is needed', false, 0),
  ('2566710d-d9c0-5dbe-b877-f85dcf361a85', '3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'B', 'Ask the family to sign consent', false, 1),
  ('dff8712b-5e2c-57e4-82aa-56be0dc76660', '3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'C', 'Consider a Deprivation of Liberty Safeguards (DoLS) authorisation', true, 2),
  ('7c6b6100-de1e-577f-9685-4ac11f90380d', '3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'D', 'Detain under Section 136', false, 3),
  ('dedbde10-43d0-5350-b4ee-17d5f5391355', '3e044af1-306f-5ce3-95e5-18b0ed72d4a5', 'E', 'Apply for a Lasting Power of Attorney on her behalf', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('174f1e55-0878-5efa-aa26-834f092765ff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 82 year old man has been admitted after a fall. He has a history of type 2 diabetes, hypertension and AF. He is on 12 regular medications. Which assessment provides the BEST overall framework to improve his outcomes?', 'Comprehensive geriatric assessment is a multidimensional, multidisciplinary process covering medical, functional, psychological, social and environmental needs, producing a coordinated plan. It improves the likelihood of being alive and in one''s own home after an emergency admission. It includes medication review, falls assessment, cognition, nutrition, continence and social support.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('357ffee6-37eb-5643-acfa-8b688687cd23', '174f1e55-0878-5efa-aa26-834f092765ff', 'A', 'Discharge without assessment', false, 0),
  ('b49b7ab8-3046-50d0-bf7e-c20879ed3543', '174f1e55-0878-5efa-aa26-834f092765ff', 'B', 'Comprehensive geriatric assessment (CGA)', true, 1),
  ('745dcb26-b7f8-5d4b-af4c-515fadd70e62', '174f1e55-0878-5efa-aa26-834f092765ff', 'C', 'Increase all medication doses', false, 2),
  ('ea8d1a8b-147b-51bd-8135-0eefe01675fc', '174f1e55-0878-5efa-aa26-834f092765ff', 'D', 'A single specialist review', false, 3),
  ('703393f0-28ea-5ca9-83d3-4e5b43ecd03a', '174f1e55-0878-5efa-aa26-834f092765ff', 'E', 'CT head only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8246a020-c347-5b7b-b2ed-81393dad4f24', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 76 year old woman has had worsening urinary incontinence and constipation over months, with a recent fall. She is taking oxybutynin, amitriptyline and codeine. What is the SINGLE most important underlying issue?', 'Anticholinergic medications (oxybutynin, amitriptyline, antihistamines, some antipsychotics) have a cumulative burden that increases confusion, falls, constipation, urinary retention and possibly dementia in older people. Tools such as the ACB score help identify this. Deprescribing is key: for example, mirabegron instead of oxybutynin and alternatives to amitriptyline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('44b393d8-85fd-56cd-873a-7160e79d3fcd', '8246a020-c347-5b7b-b2ed-81393dad4f24', 'A', 'Parkinson''s disease', false, 0),
  ('50d909db-e6e1-59db-8cda-8f24938cf550', '8246a020-c347-5b7b-b2ed-81393dad4f24', 'B', 'Normal ageing', false, 1),
  ('eac70d95-eb07-519e-bd8b-263639973353', '8246a020-c347-5b7b-b2ed-81393dad4f24', 'C', 'Dementia', false, 2),
  ('bfbcddb3-977d-5069-8466-4b505f5bb14b', '8246a020-c347-5b7b-b2ed-81393dad4f24', 'D', 'High anticholinergic burden and polypharmacy', true, 3),
  ('30ca4586-4a48-55bd-bc92-f0efa53898c1', '8246a020-c347-5b7b-b2ed-81393dad4f24', 'E', 'Diabetes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 75 year old woman has three episodes of dizziness followed by her collapsing to the floor. She does not lose consciousness and has no preceding warning symptoms. She has hypertension and ischaemic heart disease. She takes amlodipine, aspirin, atorvastatin and indapamide. Which is the most appropriate diagnostic investigation?', 'Recurrent dizziness and collapse in an older woman taking antihypertensives and a diuretic (amlodipine, indapamide) suggests orthostatic hypotension. The diagnostic test is lying and standing blood pressure: a fall of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes of standing. Management includes medication review.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('06b109a4-e20d-5cae-8cf6-9a4e8b734151', '6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'A', '24 hour blood pressure monitoring', false, 0),
  ('19e7d24b-2239-5fb8-ad53-38cab42635f5', '6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'B', '24 hour ECG monitoring', false, 1),
  ('f02ee702-420c-560d-88ef-c2bdc94c9624', '6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'C', 'ECG', false, 2),
  ('891273b3-9fe5-5c84-8c37-c33b0de42d54', '6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'D', 'Echocardiogram', false, 3),
  ('89abf691-b57f-5fb1-a5f0-b37de00f17eb', '6d739d8f-9cac-5aff-bef9-dc6ab935c3fe', 'E', 'Postural blood pressure measurement', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3d866f99-ffc0-512b-ac95-466b44a89175', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 81 year old man has increasing confusion, agitation, and worsening urinary incontinence. He is a resident in a nursing home. He has dementia, asthma and prostate cancer. He takes beclomethasone and salbutamol inhalers, and rivastigmine. His temperature is 37.9°C, pulse rate 88 bpm, BP 142/92 mmHg and respiratory rate 20 breaths per minute. Heart sounds are normal and chest is clear. Which investigation is most likely to confirm his diagnosis?', 'Acute confusion, agitation and worsening urinary incontinence with a low-grade fever in a nursing home resident suggest delirium from a urinary tract infection. Urine culture is the most useful investigation. In people over 65, dipstick testing is unreliable, so culture is needed to guide antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b68a93ac-8f47-59de-9e5c-559aa2c13fed', '3d866f99-ffc0-512b-ac95-466b44a89175', 'A', 'Blood culture', false, 0),
  ('a16e9796-b1cc-5454-8b90-0c1b15162deb', '3d866f99-ffc0-512b-ac95-466b44a89175', 'B', 'Chest X-ray', false, 1),
  ('5d48fa97-b244-5c46-927f-e02e3891532e', '3d866f99-ffc0-512b-ac95-466b44a89175', 'C', 'CT of head', false, 2),
  ('6d662565-28b9-5eee-9246-e286d843ff65', '3d866f99-ffc0-512b-ac95-466b44a89175', 'D', 'Full blood count', false, 3),
  ('c7f95b87-f8f9-5151-a9e6-bec9d19c91ba', '3d866f99-ffc0-512b-ac95-466b44a89175', 'E', 'Urine culture & sensitivity', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68079b2a-0518-5297-b63f-e2541c7cb4c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old man was started on haloperidol 4 days ago during an admission for acute psychosis. He is now confused, sweating profusely and has a temperature of 39.6°C. He has generalised ''lead-pipe'' muscle rigidity, heart rate 124 beats/minute and fluctuating blood pressure. Creatine kinase is 18,000 U/L. What is the SINGLE most likely diagnosis?', 'Neuroleptic malignant syndrome usually starts within days of starting or increasing an antipsychotic. It causes hyperthermia, lead-pipe rigidity, autonomic instability, altered consciousness and a markedly raised CK, with a risk of rhabdomyolysis and AKI. Management is to stop the antipsychotic, give supportive care with cooling and IV fluids, and consider dantrolene or bromocriptine. Serotonin syndrome develops over hours and causes clonus and hyperreflexia rather than lead-pipe rigidity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('32a98edd-02a6-5165-82bf-6d942722491e', '68079b2a-0518-5297-b63f-e2541c7cb4c2', 'A', 'Malignant hyperthermia', false, 0),
  ('3034c177-dbec-5738-887e-35ab49b2b075', '68079b2a-0518-5297-b63f-e2541c7cb4c2', 'B', 'Serotonin syndrome', false, 1),
  ('6b483a41-7994-5aef-8540-1a43eb67368c', '68079b2a-0518-5297-b63f-e2541c7cb4c2', 'C', 'Neuroleptic malignant syndrome', true, 2),
  ('1115fe21-9698-5640-bb3a-ef3f10103152', '68079b2a-0518-5297-b63f-e2541c7cb4c2', 'D', 'Encephalitis', false, 3),
  ('59b90dd4-ac6b-591b-8c70-6dea745c4d82', '68079b2a-0518-5297-b63f-e2541c7cb4c2', 'E', 'Acute dystonic reaction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04be05e0-ff8e-59dc-b521-cb591330bd09', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 52 year old man with long-standing alcohol dependence is admitted with confusion. On examination he has nystagmus, bilateral lateral rectus palsies and a broad-based, unsteady gait. His capillary glucose is 5.8 mmol/L and he is not withdrawing. What is the SINGLE most appropriate immediate management?', 'Confusion, ophthalmoplegia and ataxia in a heavy drinker is Wernicke''s encephalopathy, caused by thiamine (B1) deficiency. It is a medical emergency, treated with parenteral high-dose thiamine (Pabrinex IV) for several days. Oral thiamine is too poorly absorbed in the acute setting. Glucose should not be given before thiamine in at-risk patients because it can make Wernicke''s worse. Untreated, it can progress to Korsakoff''s syndrome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f90fbf55-2bab-5047-80c9-5547525ff204', '04be05e0-ff8e-59dc-b521-cb591330bd09', 'A', 'Oral thiamine 100 mg daily', false, 0),
  ('4dfba668-220e-50c6-9bc2-9b9baf2a3e70', '04be05e0-ff8e-59dc-b521-cb591330bd09', 'B', 'IV 50% glucose', false, 1),
  ('4b91ba5a-93bf-5933-8926-5d92e4e1ed18', '04be05e0-ff8e-59dc-b521-cb591330bd09', 'C', 'Oral chlordiazepoxide', false, 2),
  ('fd158666-5a0f-53ee-8f22-5eb907002f35', '04be05e0-ff8e-59dc-b521-cb591330bd09', 'D', 'IV high-potency B vitamins (Pabrinex)', true, 3),
  ('d1124dac-6d59-5b45-9ff0-501dac31b137', '04be05e0-ff8e-59dc-b521-cb591330bd09', 'E', 'IV haloperidol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dedaf124-66c4-5241-bf82-d65af392d029', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 34 year old woman has had low mood, poor sleep, low energy and loss of interest in activities for 2 months. Her PHQ-9 score indicates moderate depression. She has no suicidal thoughts and no history of mania. She has tried guided self-help and wants to try medication alongside talking therapy. What is the SINGLE most appropriate antidepressant?', 'NICE recommends an SSRI such as sertraline (or citalopram or fluoxetine) as the first-line antidepressant, combined with psychological therapy for moderate to severe depression. SSRIs are safer in overdose than tricyclics such as amitriptyline. Patients should be reviewed after 2 weeks (after 1 week if aged under 25, because of the increased suicide risk early on). MAOIs and lithium are not first-line.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('32ac37c5-d468-59e6-9e83-ffa8ecc5e1f9', 'dedaf124-66c4-5241-bf82-d65af392d029', 'A', 'Sertraline', true, 0),
  ('e7277723-a991-5692-b4a8-ed5448e47c0e', 'dedaf124-66c4-5241-bf82-d65af392d029', 'B', 'Lithium', false, 1),
  ('40358c8d-d122-592b-9331-77027234ca25', 'dedaf124-66c4-5241-bf82-d65af392d029', 'C', 'Amitriptyline', false, 2),
  ('a1bd5300-70c4-5ce4-8c46-147fdc44b47a', 'dedaf124-66c4-5241-bf82-d65af392d029', 'D', 'Phenelzine', false, 3),
  ('c234423c-8b0b-5446-971f-dd57aa9489a2', 'dedaf124-66c4-5241-bf82-d65af392d029', 'E', 'Venlafaxine as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 23 year old man is brought to his GP by his parents. For 6 months he has become withdrawn, stopped going to college and spends hours in his room. He believes the neighbours are putting thoughts into his head and hears voices commenting on his actions. He does not use drugs. His physical examination and blood tests are normal. What is the SINGLE most likely diagnosis?', 'Thought insertion and third-person auditory hallucinations giving a running commentary are first-rank symptoms of schizophrenia. Together with negative symptoms (social withdrawal) for more than 1 month, they support the diagnosis. NICE recommends urgent referral to an early intervention in psychosis service, an oral antipsychotic and CBT for psychosis. Bipolar disorder needs a history of mood episodes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('66dddb11-308d-5f9f-8f65-903d9c7b3e81', '5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'A', 'Schizophrenia', true, 0),
  ('d0761674-61df-5045-bc60-64c0faddf1f8', '5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'B', 'Psychotic depression', false, 1),
  ('43640d12-3cbf-5371-afc8-45a7cf6ee172', '5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'C', 'Bipolar affective disorder', false, 2),
  ('e64c6f7e-0f5c-53cb-8e69-80a6fac735f1', '5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'D', 'Delusional disorder', false, 3),
  ('e59ed1d0-9585-55b8-8e71-1d1facb6d784', '5ceb1ac1-ceda-549f-8a0e-657e7e69439a', 'E', 'Schizotypal personality disorder', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8c399b8d-1cba-5b65-a172-a161af63b288', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 17 year old girl is brought to her GP by her mother because of weight loss. She has restricted her food intake for 6 months, exercises excessively and believes she is overweight. Her BMI is 14.8 kg/m2, heart rate 42 beats/minute, blood pressure 84/50 mmHg and temperature 35.4°C. She has had no periods for 4 months. What is the SINGLE most appropriate next step?', 'This is anorexia nervosa with high-risk features: very low BMI, bradycardia below 50, hypotension and hypothermia (MEED guidance). She needs urgent medical assessment and likely admission for monitored re-feeding, which must be gradual to avoid re-feeding syndrome (hypophosphataemia, hypokalaemia, hypomagnesaemia). She should also be referred to a specialist eating disorder service. Family therapy is first-line for children and young people with anorexia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b0ddd68a-82c6-5e37-99fe-5b61623b2767', '8c399b8d-1cba-5b65-a172-a161af63b288', 'A', 'Prescribe fluoxetine and review in 4 weeks', false, 0),
  ('a8a68933-8e3c-5193-baa8-9b46c0f3250a', '8c399b8d-1cba-5b65-a172-a161af63b288', 'B', 'Give a meal plan and review in 1 month', false, 1),
  ('be950494-7ca9-5129-b06d-5c0b72747d98', '8c399b8d-1cba-5b65-a172-a161af63b288', 'C', 'Urgent same-day referral for medical assessment and possible admission', true, 2),
  ('5b532361-b325-5a2a-972c-eecf0d1cfa1d', '8c399b8d-1cba-5b65-a172-a161af63b288', 'D', 'Routine referral to the community eating disorder service', false, 3),
  ('776c6390-f931-5155-b70f-742b62c9873a', '8c399b8d-1cba-5b65-a172-a161af63b288', 'E', 'Refer for CBT only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0ac17825-95ad-5398-83e0-96dcad9de3b0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 48 year old woman is a voluntary inpatient on a medical ward after an overdose. She is now medically fit, but tells the nurse she is leaving to ''finish what she started''. She has a clear plan. The psychiatry team will take 2 hours to arrive. The doctor in charge of her care is present. What is the SINGLE most appropriate legal power to stop her leaving?', 'Section 5(2) is a ''doctor''s holding power'' that lets the doctor or approved clinician in charge of a voluntary inpatient detain them for up to 72 hours while a full Mental Health Act assessment is arranged. Section 5(4) is the nurse''s holding power, which lasts 6 hours. Section 2 (assessment, up to 28 days) needs two doctors and an AMHP. Sections 135 and 136 are police powers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e1667e0-30b7-5486-b7e1-2f9e7a33dcc5', '0ac17825-95ad-5398-83e0-96dcad9de3b0', 'A', 'Section 5(4) of the Mental Health Act', false, 0),
  ('3b09923d-e546-561b-a0d0-7fd745f932ed', '0ac17825-95ad-5398-83e0-96dcad9de3b0', 'B', 'Section 135 of the Mental Health Act', false, 1),
  ('18f9d07d-8e59-5bec-88f3-2c945134275e', '0ac17825-95ad-5398-83e0-96dcad9de3b0', 'C', 'Section 5(2) of the Mental Health Act', true, 2),
  ('93652ea8-c827-5b19-8cdc-b4d6ab29cdb6', '0ac17825-95ad-5398-83e0-96dcad9de3b0', 'D', 'Section 2 of the Mental Health Act', false, 3),
  ('9379a8eb-2fa4-5d26-99ea-e09e0f967bb4', '0ac17825-95ad-5398-83e0-96dcad9de3b0', 'E', 'Section 136 of the Mental Health Act', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'An 84 year old woman is admitted with a urinary tract infection. On the second night she becomes acutely agitated, disorientated and believes the nurses are trying to poison her. During the day she is drowsy, and her attention fluctuates. Her family say that before admission she was managing independently with normal memory. What is the SINGLE most likely diagnosis?', 'An acute onset, fluctuating course, inattention and disorganised thinking with a precipitating illness are typical of delirium. The 4AT tool is used for screening. Management is to treat the cause (here the UTI), review medications, keep good sleep hygiene, reorient her and avoid constipation, dehydration and moving her between wards. Antipsychotics (such as low-dose haloperidol) are only used short-term for severe distress or risk. Dementia has a gradual onset.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('52695438-3b17-51d8-9965-d94140f7ee35', '4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'A', 'Lewy body dementia', false, 0),
  ('32500471-b6ca-5ea9-be3f-c33c6bd8848b', '4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'B', 'Delirium', true, 1),
  ('d59fc8b6-2ea9-5894-bc76-07e8351263dd', '4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'C', 'Late-onset schizophrenia', false, 2),
  ('7bfc60b9-0d88-570c-98f2-50570c9d4726', '4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'D', 'Alzheimer''s disease', false, 3),
  ('228514fa-e031-50bc-ae5c-a6c2fc92c8f4', '4204c89a-1fd7-5650-a0fa-a8f995a8deda', 'E', 'Depression', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('deea8970-fdb2-5795-865b-490b063bca8d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 49 year old man who drinks about 120 units of alcohol a week is admitted for an elective hernia repair. Twenty-four hours after his last drink he becomes tremulous, sweaty, anxious and tachycardic. He is orientated and has no hallucinations. What is the SINGLE most appropriate treatment?', 'These are early alcohol withdrawal symptoms, typically 6-24 hours after the last drink. Seizures usually occur at 12-48 hours and delirium tremens at 48-72 hours. NICE recommends a long-acting benzodiazepine (chlordiazepoxide, or lorazepam in liver failure) on a fixed or symptom-triggered reducing regimen, plus thiamine (Pabrinex IV if Wernicke''s is suspected or high risk). Disulfiram and acamprosate are for maintaining abstinence after withdrawal.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3488ee2a-82a5-5613-bb5c-610132b23fb7', 'deea8970-fdb2-5795-865b-490b063bca8d', 'A', 'Oral acamprosate', false, 0),
  ('69523f65-32ac-5beb-809b-278cd691f7a1', 'deea8970-fdb2-5795-865b-490b063bca8d', 'B', 'Oral disulfiram', false, 1),
  ('7ce401f4-6730-5d25-849b-4cefe43a3903', 'deea8970-fdb2-5795-865b-490b063bca8d', 'C', 'Oral chlordiazepoxide on a reducing regimen and IV Pabrinex', true, 2),
  ('838fe458-4f8f-5783-af88-57e5a7099f62', 'deea8970-fdb2-5795-865b-490b063bca8d', 'D', 'IV phenytoin', false, 3),
  ('e82fac9a-6052-5fda-b0ee-756c66a6916f', 'deea8970-fdb2-5795-865b-490b063bca8d', 'E', 'Oral haloperidol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('09587a77-1598-5795-b382-de85af9f7b75', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 27 year old woman has had recurrent unexpected episodes of intense fear for 6 months. During them she has palpitations, sweating, shaking, breathlessness and a feeling she is going to die, peaking within 10 minutes. She now avoids supermarkets in case it happens again. Thyroid function, ECG and glucose are normal. What is the SINGLE most appropriate first-line treatment?', 'Recurrent unexpected panic attacks with worry about future attacks and avoidance are panic disorder. NICE recommends CBT as first-line, and an SSRI if medication is needed. Benzodiazepines are not recommended because of a worse long-term outcome and dependence. Physical causes such as thyrotoxicosis and arrhythmia should be excluded first.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c549f97c-9e4a-5649-8c76-96d88ed40fa6', '09587a77-1598-5795-b382-de85af9f7b75', 'A', 'Long-term diazepam', false, 0),
  ('89a5d7bc-066c-5d18-9e93-0b89963370c3', '09587a77-1598-5795-b382-de85af9f7b75', 'B', 'Olanzapine', false, 1),
  ('b0a87639-a91b-598b-be49-8177bbdcbbf3', '09587a77-1598-5795-b382-de85af9f7b75', 'C', 'Propranolol as sole treatment', false, 2),
  ('8d9876cc-735d-5955-972e-9de3e2dbd41d', '09587a77-1598-5795-b382-de85af9f7b75', 'D', 'Cognitive behavioural therapy', true, 3),
  ('d430039d-dd15-51aa-a76a-2beb07541e45', '09587a77-1598-5795-b382-de85af9f7b75', 'E', 'Lithium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dfd17481-7524-5a68-94c2-c667f02a666b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 30 year old man with depression has been taking sertraline for 6 weeks. His GP has added tramadol for back pain. Two days later he presents with agitation, sweating, diarrhoea, a temperature of 38.3°C, tremor, hyperreflexia and inducible clonus in both ankles. What is the SINGLE most likely diagnosis?', 'Serotonin syndrome develops within hours to days of adding a serotonergic drug (here tramadol with an SSRI). It causes autonomic instability, altered mental state and neuromuscular excitability, with clonus and hyperreflexia especially in the legs. Management is to stop the serotonergic drugs, give supportive care and benzodiazepines, and consider cyproheptadine in moderate to severe cases. NMS develops more slowly, with lead-pipe rigidity and bradyreflexia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bfc1f2ea-7467-51af-854b-e8764219c9dc', 'dfd17481-7524-5a68-94c2-c667f02a666b', 'A', 'Alcohol withdrawal', false, 0),
  ('a6b6ca9b-8499-5c56-aceb-d4632b78a94f', 'dfd17481-7524-5a68-94c2-c667f02a666b', 'B', 'Neuroleptic malignant syndrome', false, 1),
  ('85e96f59-66cc-5db8-94f7-510df4a203fb', 'dfd17481-7524-5a68-94c2-c667f02a666b', 'C', 'Serotonin syndrome', true, 2),
  ('053b8f2b-45e4-5be6-ba71-888890e3d5df', 'dfd17481-7524-5a68-94c2-c667f02a666b', 'D', 'Malignant hyperthermia', false, 3),
  ('d897c883-73e9-5851-a8de-145d55beaac5', 'dfd17481-7524-5a68-94c2-c667f02a666b', 'E', 'Thyroid storm', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a4476eb1-75cc-5ff2-9158-870a455b253d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 28 year old woman has had excessive worry about many everyday things (work, finances, family health) on most days for 8 months. She has restlessness, muscle tension, poor concentration and disturbed sleep. She has no panic attacks. Self-help has not worked. What is the SINGLE most appropriate next step?', 'Generalised anxiety disorder is excessive, uncontrollable worry for at least 6 months with physical symptoms. NICE uses a stepped approach: education and active monitoring, then low-intensity interventions (guided self-help), then high-intensity CBT or applied relaxation, or drug treatment with sertraline first-line. Benzodiazepines should only be used short-term in a crisis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3cbaf3f3-fb81-5f0d-a57d-25c5f59482e3', 'a4476eb1-75cc-5ff2-9158-870a455b253d', 'A', 'Antipsychotic', false, 0),
  ('4194de10-8f3f-5f11-8ddf-5c1e5cf95dae', 'a4476eb1-75cc-5ff2-9158-870a455b253d', 'B', 'High-intensity psychological intervention (CBT or applied relaxation) or an SSRI (sertraline)', true, 1),
  ('e3f39c10-d0be-5c50-bcba-aae48446c510', 'a4476eb1-75cc-5ff2-9158-870a455b253d', 'C', 'Long-term diazepam', false, 2),
  ('8a12ddd2-d0ec-54fe-a38c-6ea210b27e6c', 'a4476eb1-75cc-5ff2-9158-870a455b253d', 'D', 'Propranolol alone', false, 3),
  ('021b45ac-1e83-57ba-9667-d8642b287e2e', 'a4476eb1-75cc-5ff2-9158-870a455b253d', 'E', 'No treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 30 year old man repeatedly checks that the door is locked and the gas is off, spending 2 hours each day doing this. He knows it is excessive and the thoughts are his own, but he feels intense anxiety if he does not check. What is the SINGLE most appropriate first-line treatment?', 'OCD involves obsessions (intrusive, unwanted thoughts recognised as the person''s own) and compulsions (repetitive behaviours that reduce anxiety). NICE recommends CBT with ERP. With moderate or severe impairment, an SSRI is added (or clomipramine). SSRIs for OCD often need higher doses and at least 12 weeks to work.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ade32b3f-ca0f-5bb3-8905-ebc7113eadfb', 'a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'A', 'Electroconvulsive therapy', false, 0),
  ('7304c783-2f38-57ad-9f0a-42695063fa75', 'a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'B', 'Haloperidol', false, 1),
  ('c661d012-54b6-5ad1-9b64-66da8b958189', 'a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'C', 'CBT including exposure and response prevention (ERP)', true, 2),
  ('1329dcef-609d-5bb6-b1ec-7f263a66a5fa', 'a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'D', 'Lithium', false, 3),
  ('0abcf2d2-b964-5c0e-8e55-19ed9faf9c1f', 'a5224bf4-7daa-5c22-8d5e-ca5f5e415536', 'E', 'Benzodiazepines', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('736ea542-5628-5890-824c-63fb4047662d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 34 year old soldier has had nightmares, flashbacks, hypervigilance and avoidance of reminders for 5 months since an explosion in which his friend died. He startles easily and has stopped socialising. What is the SINGLE most appropriate first-line treatment?', 'PTSD develops after a traumatic event and involves re-experiencing (flashbacks, nightmares), avoidance, hyperarousal and negative changes in mood and thinking lasting over 1 month. NICE recommends trauma-focused CBT or EMDR (for symptoms over 3 months after non-combat trauma). Venlafaxine or an SSRI is offered if psychological treatment is not effective or not wanted. Single-session debriefing is not recommended.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f3cc906c-712a-5deb-a6ec-c530fcbda5bb', '736ea542-5628-5890-824c-63fb4047662d', 'A', 'Debriefing within 72 hours', false, 0),
  ('9bf3d1f8-bb86-565d-827e-687fc9cace49', '736ea542-5628-5890-824c-63fb4047662d', 'B', 'Trauma-focused CBT or EMDR', true, 1),
  ('bc4b7a05-898e-5838-860c-95b0eef0fcf2', '736ea542-5628-5890-824c-63fb4047662d', 'C', 'Long-term diazepam', false, 2),
  ('af685087-2163-55bd-9766-0be042cf3f5f', '736ea542-5628-5890-824c-63fb4047662d', 'D', 'Antipsychotics', false, 3),
  ('eba010ec-df24-5c3c-82b3-e0d41c40b06e', '736ea542-5628-5890-824c-63fb4047662d', 'E', 'Zopiclone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c256387c-e6be-5843-bd83-3fd57aa5900c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 42 year old woman''s father died 3 weeks ago. She has been tearful, has poor sleep and appetite, and sometimes hears her father''s voice calling her name as she falls asleep. She is functioning at work. What is the SINGLE most likely diagnosis?', 'Normal bereavement includes sadness, tearfulness, disturbed sleep and appetite, and sometimes brief pseudohallucinations of the deceased (especially at sleep onset). These are not pathological. Prolonged grief disorder is considered when intense grief causes significant impairment for more than 6-12 months. Support and active monitoring are appropriate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2fde55a1-6b82-575c-8120-721afddcfe66', 'c256387c-e6be-5843-bd83-3fd57aa5900c', 'A', 'Prolonged grief disorder', false, 0),
  ('3e3d316a-03e2-5d0b-9766-da7e925cdb06', 'c256387c-e6be-5843-bd83-3fd57aa5900c', 'B', 'Psychotic depression', false, 1),
  ('3f5331b5-0c49-5169-a35a-73bd602dfafc', 'c256387c-e6be-5843-bd83-3fd57aa5900c', 'C', 'Schizophrenia', false, 2),
  ('f8afe0e8-df76-5931-b8a0-c40ded92598c', 'c256387c-e6be-5843-bd83-3fd57aa5900c', 'D', 'Major depressive disorder', false, 3),
  ('e800a9df-5420-5a3f-afa4-05e92a1511ba', 'c256387c-e6be-5843-bd83-3fd57aa5900c', 'E', 'Normal grief reaction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2cf55eb5-394b-5b79-8edf-6f7720fae141', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 26 year old man has had 2 weeks of elevated mood, sleeping 2 hours a night, pressure of speech, flight of ideas, spending thousands of pounds and believing he is a famous musician. He has no previous psychiatric history and no drug use. What is the SINGLE most appropriate first-line drug treatment?', 'Acute mania with psychotic features (grandiose delusions) is first treated with an antipsychotic (haloperidol, olanzapine, quetiapine or risperidone). Any antidepressant should be stopped. Lithium is the gold standard for long-term prophylaxis in bipolar disorder. Short-term benzodiazepines can help agitation. A Mental Health Act assessment may be needed if he lacks insight and is at risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ac6e7c6c-0a5f-5a9c-ae3f-ae13c5a05903', '2cf55eb5-394b-5b79-8edf-6f7720fae141', 'A', 'Diazepam alone long-term', false, 0),
  ('ea9c6da7-039d-5a7c-a026-facf014121e7', '2cf55eb5-394b-5b79-8edf-6f7720fae141', 'B', 'Sertraline', false, 1),
  ('cd8cad71-52ce-5920-9beb-1b5cee9a2ed4', '2cf55eb5-394b-5b79-8edf-6f7720fae141', 'C', 'An antipsychotic (e.g. olanzapine, quetiapine, risperidone or haloperidol)', true, 2),
  ('9650cfc7-6743-5b7a-a486-1b0d8eab76d7', '2cf55eb5-394b-5b79-8edf-6f7720fae141', 'D', 'Lithium alone if acutely psychotic', false, 3),
  ('0e5ccbb9-3d3e-5672-9553-d3362857569c', '2cf55eb5-394b-5b79-8edf-6f7720fae141', 'E', 'Lamotrigine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 38 year old woman with bipolar disorder takes lithium. Which set of monitoring tests is MOST appropriate?', 'Lithium has a narrow therapeutic range (usually 0.4-1.0 mmol/L). Levels are checked 12 hours after the dose, weekly after starting or changing dose, then every 3 months for the first year. Renal function (eGFR), thyroid function, calcium, weight and BMI are checked every 6 months. Lithium can cause hypothyroidism, nephrogenic diabetes insipidus, CKD and hyperparathyroidism, and is teratogenic (Ebstein''s anomaly).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b7a951cd-02c6-5fbc-bbc6-46b55fb97e6a', '3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'A', 'Full blood count only', false, 0),
  ('efd80239-dd05-5b19-89d6-17bf7b97a9aa', '3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'B', 'Liver function tests weekly', false, 1),
  ('bb561329-af3f-55ae-a46a-9f543b188f49', '3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'C', 'No monitoring needed once stable', false, 2),
  ('5c83fd58-0a0e-55bf-8c96-ddb99315d748', '3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'D', 'Lithium levels (12 hours post-dose) every 3 months initially, plus thyroid and renal function every 6 months', true, 3),
  ('c374e38a-4a7d-5fb9-87ee-421e42112d94', '3bc09b22-e19c-55e1-96a6-5d281ec363ce', 'E', 'Lithium levels only once a year', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 32 year old woman was started on clozapine for treatment-resistant schizophrenia 3 weeks ago. She now has a sore throat and fever of 38.5°C. What is the SINGLE most appropriate immediate investigation?', 'Clozapine can cause life-threatening agranulocytosis, most often in the first 18 weeks. Mandatory FBC monitoring is weekly for 18 weeks, then fortnightly, then monthly. Any sign of infection needs an urgent FBC. Other side effects include myocarditis, constipation (which can be fatal), hypersalivation, seizures and weight gain. Clozapine is used after failure of two antipsychotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('42157155-bad7-5595-9799-6858c1daf34a', 'c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'A', 'Clozapine level', false, 0),
  ('c96e5aa2-e2f6-5134-9641-526c180060ff', 'c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'B', 'Chest X-ray', false, 1),
  ('3a4d711d-a40b-5628-925c-6b8e6f49467d', 'c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'C', 'Throat swab only', false, 2),
  ('2db665d9-f1b3-570b-9115-47d2717c17cb', 'c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'D', 'ECG only', false, 3),
  ('85c5a997-0afb-5ad4-b3ab-e0f88b72d1a9', 'c7e6bb5f-9927-5316-a68c-4b7f0e2e874a', 'E', 'Urgent full blood count (neutrophil count)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('319eec87-b783-5f12-9b58-e7c061a484fb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old man was started on haloperidol 2 days ago. He has sudden painful sustained contraction of his neck muscles twisting his head to one side, and his eyes are rolled upwards. What is the SINGLE most appropriate immediate treatment?', 'Acute dystonic reactions (torticollis, oculogyric crisis) happen within hours to days of starting antipsychotics or antiemetics such as metoclopramide, especially in young men. Treatment is an anticholinergic such as procyclidine. Other extrapyramidal side effects are akathisia (treated with propranolol), parkinsonism and, later, tardive dyskinesia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('66629327-b2e8-5141-9dda-0a82e8f9d6ab', '319eec87-b783-5f12-9b58-e7c061a484fb', 'A', 'IM or IV procyclidine (an anticholinergic)', true, 0),
  ('7a9edea7-b9ca-5452-ac2a-2f14bcad782e', '319eec87-b783-5f12-9b58-e7c061a484fb', 'B', 'Propranolol', false, 1),
  ('84a652f4-5b35-5ad1-92a1-a8df9679736f', '319eec87-b783-5f12-9b58-e7c061a484fb', 'C', 'IV dantrolene', false, 2),
  ('08c47474-5ede-57f1-b817-6811ac31ab61', '319eec87-b783-5f12-9b58-e7c061a484fb', 'D', 'IV lorazepam alone', false, 3),
  ('9de962dc-c62f-5e69-9603-c8960eceb90b', '319eec87-b783-5f12-9b58-e7c061a484fb', 'E', 'Increase haloperidol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 58 year old woman has been on antipsychotics for 15 years. She has developed involuntary repetitive chewing and lip-smacking movements and tongue protrusion. What is the SINGLE most likely diagnosis?', 'Tardive dyskinesia is a late, often irreversible extrapyramidal side effect of long-term dopamine antagonists. It causes involuntary orofacial movements. Management includes reducing or switching to an antipsychotic with lower risk (such as clozapine) and specialist review. Tetrabenazine may help. Anticholinergics make it worse.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('99b42d99-cf50-52dc-85a3-6c0f84c39289', '3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'A', 'Tardive dyskinesia', true, 0),
  ('69db6e18-1898-5e97-a1fd-821b810850b1', '3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'B', 'Parkinson''s disease', false, 1),
  ('63b1b8b8-474b-56f8-9de3-a55001963472', '3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'C', 'Huntington''s disease', false, 2),
  ('751e7ea0-18ff-56a9-9401-f3a1bf5b215d', '3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'D', 'Akathisia', false, 3),
  ('04f06a94-8164-5dd4-ba57-8c964a6a6725', '3fcb383a-ef10-526f-99ac-8b5654d1fbf2', 'E', 'Acute dystonia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2bd349b3-c03e-54d8-992f-689da0ffd64e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 40 year old man taking olanzapine for schizophrenia has gained 12 kg over a year. Which monitoring is MOST important for the metabolic side effects of his medication?', 'Second-generation antipsychotics (especially olanzapine and clozapine) cause weight gain, insulin resistance, diabetes and dyslipidaemia. NICE recommends baseline and regular monitoring of weight, waist circumference, BP, glucose or HbA1c, lipids and an ECG where indicated (QT prolongation). Lifestyle interventions or switching drugs may be needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d69c3dad-40b7-55fc-a3a5-7fc2be0208b4', '2bd349b3-c03e-54d8-992f-689da0ffd64e', 'A', 'No monitoring needed', false, 0),
  ('53cb5e12-b4e7-5c0c-8c53-1f6476e95de2', '2bd349b3-c03e-54d8-992f-689da0ffd64e', 'B', 'Monthly LFTs only', false, 1),
  ('2d399f7f-c0be-5a3c-b747-4a96e45ad833', '2bd349b3-c03e-54d8-992f-689da0ffd64e', 'C', 'Thyroid function only', false, 2),
  ('c8c454e9-5026-5c70-a5d1-7534924869de', '2bd349b3-c03e-54d8-992f-689da0ffd64e', 'D', 'Annual weight/BMI, waist circumference, BP, HbA1c (or fasting glucose) and lipids', true, 3),
  ('94359be2-d394-5340-a9f9-314fd3a95782', '2bd349b3-c03e-54d8-992f-689da0ffd64e', 'E', 'Annual chest X-ray', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('32e1f90f-c762-5d61-a209-b117f70923d3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 20 year old woman has recurrent episodes of eating large amounts of food in a short time with a sense of loss of control, followed by self-induced vomiting and laxative misuse. Her BMI is 22 kg/m2. Bloods show potassium 2.9 mmol/L. What is the SINGLE most likely diagnosis?', 'Bulimia nervosa involves recurrent binges with compensatory behaviours (vomiting, laxatives, excessive exercise) and overvaluation of shape and weight, with a normal or high BMI. Signs include Russell''s sign (calluses on the knuckles), parotid enlargement, dental erosion and hypokalaemic metabolic alkalosis. NICE recommends bulimia-focused guided self-help, then individual eating disorder-focused CBT.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1f0e2c46-7527-58e6-97ef-b8a54cb4e186', '32e1f90f-c762-5d61-a209-b117f70923d3', 'A', 'Hyperthyroidism', false, 0),
  ('396bb2fe-c57d-5b81-953d-10145cb7e380', '32e1f90f-c762-5d61-a209-b117f70923d3', 'B', 'Major depressive disorder', false, 1),
  ('c91475fa-d005-5493-a487-bae04bf08221', '32e1f90f-c762-5d61-a209-b117f70923d3', 'C', 'Binge eating disorder', false, 2),
  ('6d11842d-0687-5475-a109-2ed84bc4ae8e', '32e1f90f-c762-5d61-a209-b117f70923d3', 'D', 'Anorexia nervosa', false, 3),
  ('01baaebf-bc0c-5268-b0d7-f6c48198d926', '32e1f90f-c762-5d61-a209-b117f70923d3', 'E', 'Bulimia nervosa', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4896068-8c22-5ed9-b009-01e2b58211ea', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 23 year old woman has a long history of unstable relationships, intense fear of abandonment, impulsivity, chronic feelings of emptiness and repeated self-harm by cutting. She has rapid shifts in mood within hours. What is the SINGLE most likely diagnosis?', 'Emotionally unstable (borderline) personality disorder involves unstable relationships, self-image and affect, marked impulsivity, fear of abandonment, chronic emptiness and recurrent self-harm. Treatment is psychological (dialectical behaviour therapy, mentalisation-based therapy). Medication is not recommended for the core disorder but may be used short-term in a crisis or for comorbidities.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
