  ('3816beda-3aaf-5899-9849-a6f836f39426', 'e4896068-8c22-5ed9-b009-01e2b58211ea', 'A', 'Bipolar affective disorder', false, 0),
  ('54032ea9-b051-5a2e-9c1f-ee73f5e53fad', 'e4896068-8c22-5ed9-b009-01e2b58211ea', 'B', 'Schizophrenia', false, 1),
  ('39a5d83b-fc6e-56d2-871a-0425edee5ca3', 'e4896068-8c22-5ed9-b009-01e2b58211ea', 'C', 'Antisocial personality disorder', false, 2),
  ('2af840a1-56a0-55fb-8c60-8d187716904d', 'e4896068-8c22-5ed9-b009-01e2b58211ea', 'D', 'Histrionic personality disorder', false, 3),
  ('9fe5e0ef-ef9f-5ec3-8a70-a24fbcbddd52', 'e4896068-8c22-5ed9-b009-01e2b58211ea', 'E', 'Emotionally unstable (borderline) personality disorder', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('617ff5bd-95e7-516e-8b29-5bec9c34971c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 72 year old man whose wife died 6 months ago is seen after an overdose. Which factor in his history is MOST strongly associated with an increased risk of completed suicide?', 'Risk factors for suicide include male sex, older age, living alone, recent bereavement or separation, unemployment, chronic illness or pain, previous self-harm, mental illness, substance misuse, access to means and a family history of suicide. NICE advises against using risk prediction tools to decide treatment. Each patient should have a psychosocial assessment and a safety plan.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
