  ('ce965374-fe93-55a2-ad0c-f76161ead1ca', '617ff5bd-95e7-516e-8b29-5bec9c34971c', 'A', 'Having a supportive family', false, 0),
  ('3ae11a30-8ba9-5880-a1da-7bf494196b0a', '617ff5bd-95e7-516e-8b29-5bec9c34971c', 'B', 'Younger age with no history', false, 1),
  ('f5db8234-d8be-5383-b07d-7f6c0280887d', '617ff5bd-95e7-516e-8b29-5bec9c34971c', 'C', 'Female sex', false, 2),
  ('635a35de-3c02-55da-b3d1-e872a2c7caa7', '617ff5bd-95e7-516e-8b29-5bec9c34971c', 'D', 'Older age, male sex, living alone and recent bereavement', true, 3),
  ('7aab07f8-4727-50c1-bb05-1c0b8ee82efa', '617ff5bd-95e7-516e-8b29-5bec9c34971c', 'E', 'Being married', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1143c3e-3733-543f-8aca-8b47fdca6df6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 30 year old woman is seen after cutting her forearm superficially. She has done this several times before to relieve tension. She has no suicidal intent. According to NICE, what is the SINGLE most appropriate management?', 'NICE (NG225) recommends a psychosocial assessment (needs and risks), treatment of physical injuries and a collaborative safety plan for anyone who self-harms. Drug treatment is not recommended specifically to reduce self-harm. Risk tools should not be used to predict future suicide or to decide on treatment or discharge. Patients should be treated with compassion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
