  ('34f52803-c830-5873-ad4a-39f9a817a8ab', 'c1143c3e-3733-543f-8aca-8b47fdca6df6', 'A', 'Prescribe an antidepressant for self-harm', false, 0),
  ('bc40f8bc-7c24-596b-8636-5f48d9f33af6', 'c1143c3e-3733-543f-8aca-8b47fdca6df6', 'B', 'Discharge with no follow-up', false, 1),
  ('e1bd2949-e312-58b9-911c-1a7b9ad94fff', 'c1143c3e-3733-543f-8aca-8b47fdca6df6', 'C', 'Psychosocial assessment, wound care and a collaborative safety plan', true, 2),
  ('aacd1200-b937-5617-b9e8-4fb5ed56035b', 'c1143c3e-3733-543f-8aca-8b47fdca6df6', 'D', 'Detain under the Mental Health Act', false, 3),
  ('b46fe541-e071-5b7c-a0b4-f954e47563a5', 'c1143c3e-3733-543f-8aca-8b47fdca6df6', 'E', 'Use a risk scale to decide discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1246c79d-94f5-5c4b-9d42-476e87325258', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 52 year old man with chronic pain has been taking increasing doses of codeine bought online. He now takes 20 tablets a day, has tried to cut down but cannot, and has withdrawal symptoms when he misses doses. What is the SINGLE most likely diagnosis?', 'Dependence is shown by tolerance, withdrawal, a strong desire to use, difficulty controlling use, neglect of other interests and continued use despite harm. Management involves psychosocial support and opioid substitution therapy (methadone or buprenorphine) through drug services, with naloxone provision. Detoxification can be considered when the person is ready.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
