  ('3e1ec66c-c925-5ccf-8849-f01ca15efabf', '1246c79d-94f5-5c4b-9d42-476e87325258', 'A', 'Somatic symptom disorder', false, 0),
  ('0f4f627c-9985-5c64-a85d-446e06fb95ac', '1246c79d-94f5-5c4b-9d42-476e87325258', 'B', 'Malingering', false, 1),
  ('e93dc845-5df2-56a8-8d2d-c5f3c681e3ce', '1246c79d-94f5-5c4b-9d42-476e87325258', 'C', 'Opioid dependence', true, 2),
  ('0eb35799-92da-54d2-97b7-d19069ce0f01', '1246c79d-94f5-5c4b-9d42-476e87325258', 'D', 'Opioid toxicity', false, 3),
  ('ead993cb-8157-5123-9e8b-03c8b32fe5dc', '1246c79d-94f5-5c4b-9d42-476e87325258', 'E', 'Factitious disorder', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 35 year old man who injects heroin attends the GP wanting help to stop. He has no other medical problems. What is the SINGLE most appropriate pharmacological management to reduce harm and illicit use?', 'NICE recommends methadone or buprenorphine as first-line opioid substitution therapy, with supervised consumption at first, alongside psychosocial support. This reduces illicit use, overdose and blood-borne virus transmission. Take-home naloxone should be given. Naltrexone is used to prevent relapse after detoxification. Lofexidine helps withdrawal symptoms during detox.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('536bb22f-345e-5cc7-81a9-c0defa570be3', 'a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'A', 'No treatment', false, 0),
  ('2e26098a-b845-5c1a-9755-236d31a8938f', 'a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'B', 'Diazepam', false, 1),
  ('67027330-7e8c-5aeb-8a0c-c902aecf5c55', 'a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'C', 'Opioid substitution therapy with methadone or buprenorphine through drug services', true, 2),
  ('7be1e430-49e3-5f42-83d3-46f9241647ad', 'a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'D', 'Naltrexone immediately while still using heroin', false, 3),
  ('c7757152-dbd8-5248-9bb4-3f46e7c990f9', 'a992bdb6-8087-50b8-abca-e72cb8edc7e3', 'E', 'Clonidine only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 62 year old man with severe depression has stopped eating and drinking, is mute and believes his insides are rotting. Antidepressants have not worked. His life is at risk from dehydration. What is the SINGLE most appropriate treatment?', 'ECT is indicated for severe, life-threatening depression (refusal of food or fluids, psychotic features such as nihilistic delusions, catatonia) or when a rapid response is needed, or after other treatments fail. It is given under general anaesthesia. Side effects include short-term memory loss and headache. Consent is needed, or authorisation under the Mental Health Act if he lacks capacity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c3e8b13c-0552-50ca-89b0-b9be8d01a456', 'f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'A', 'Discharge with family support', false, 0),
  ('7ce5c1ae-9370-54b8-bec1-5fce768950dc', 'f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'B', 'Increase the SSRI dose', false, 1),
  ('f0373786-890b-5e9e-90ac-91cb870ca45d', 'f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'C', 'Add lithium and wait 6 weeks', false, 2),
  ('e003498e-f68d-556b-8d3d-7674648cb2b3', 'f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'D', 'CBT', false, 3),
  ('a7f7e643-b29b-5065-a915-16a547a259bb', 'f5350b5f-5d95-5edd-b676-27e2cbf90fff', 'E', 'Electroconvulsive therapy (ECT)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 34 year old woman has a history of multiple unexplained physical complaints over 5 years (abdominal pain, headaches, back pain, palpitations) with many normal investigations. She is very distressed and seeks repeated reassurance. What is the SINGLE most appropriate management approach?', 'Somatic symptom disorder involves distressing physical symptoms with excessive thoughts, feelings or behaviours about them. Management includes continuity of care with one clinician, regular scheduled reviews, acknowledging the symptoms, explaining that investigations are normal, limiting unnecessary tests and offering CBT. Factitious disorder (deliberately producing symptoms for a sick role) and malingering (for external gain) are different.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15fd5104-08cb-5ed2-bf1d-19445ae31e40', '002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'A', 'Discharge from the practice', false, 0),
  ('724bb1ec-9907-5709-8520-81173b7d1f18', '002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'B', 'Prescribe opioids', false, 1),
  ('d5c4cf38-41c5-5a61-8386-fd980d3fdbaf', '002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'C', 'Tell her the symptoms are imaginary', false, 2),
  ('2bb72d6e-5220-5ec9-a7a5-be000b998f8d', '002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'D', 'Arrange more specialist referrals', false, 3),
  ('2366f1c9-99a4-5fee-997e-a1e90dbbfe12', '002bea32-f8a9-53d3-a4f6-d79d9b05ce4e', 'E', 'Regular scheduled appointments with one clinician, acknowledging symptoms and avoiding unnecessary tests', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('737781e8-78b2-5665-837a-638ae121da41', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 29 year old man is brought to the Emergency Department by police after behaving bizarrely in a public place. He believes his thoughts are being broadcast. Under which section of the Mental Health Act can the police take a person found in a public place to a place of safety?', 'Section 136 lets police remove a person who appears to have a mental disorder and be in immediate need of care, from a public place (or anywhere except a private home) to a place of safety, for up to 24 hours (extendable by 12) for assessment. Section 135 needs a warrant to enter a private home. Section 2 is assessment for up to 28 days, and Section 3 treatment for up to 6 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1f1697a3-1cc8-5754-b3e1-c4eaf73bcf15', '737781e8-78b2-5665-837a-638ae121da41', 'A', 'Section 2', false, 0),
  ('65aee4b5-2a9e-5c56-9392-267012f4f355', '737781e8-78b2-5665-837a-638ae121da41', 'B', 'Section 5(4)', false, 1),
  ('f0be8413-ccec-5242-8ccd-6a7b0974e315', '737781e8-78b2-5665-837a-638ae121da41', 'C', 'Section 3', false, 2),
  ('d06aadab-a174-5b0b-b56b-3d68cdcb2a09', '737781e8-78b2-5665-837a-638ae121da41', 'D', 'Section 136', true, 3),
  ('d7b62670-f837-5226-94b6-61fc015bc95f', '737781e8-78b2-5665-837a-638ae121da41', 'E', 'Section 135', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old man with schizophrenia is known to stop his medication and relapse. He has been assessed and needs admission for treatment. He is well known to the team and refuses admission. Which section of the Mental Health Act is MOST appropriate?', 'Section 3 is admission for treatment for up to 6 months (renewable), when the diagnosis is known and appropriate treatment is available. It needs two medical recommendations (one from a Section 12-approved doctor) and an AMHP application. Section 2 is for assessment (28 days) when the diagnosis or response is unclear. Section 4 is an emergency (72-hour) order on one doctor''s recommendation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4f0b55b5-0bd9-55c5-be39-7e846359eafb', '61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'A', 'Section 136', false, 0),
  ('0ad3de77-8c37-5433-aa4f-80f1ff51de7f', '61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'B', 'Section 4', false, 1),
  ('9d439d91-6988-59e8-a6a2-06ff0455e222', '61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'C', 'Section 2', false, 2),
  ('ec7ee069-81bd-5b43-9874-f4004c773fed', '61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'D', 'Section 5(2)', false, 3),
  ('b3768db9-1423-5632-8789-c4c8a6239ede', '61c35ee5-6c7b-5152-afa0-0d6bcdb2b7b6', 'E', 'Section 3', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6e54fdfa-077f-53ee-bf85-7d42539d3999', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 17 year old girl has been low in mood for 3 months, with withdrawal from friends, poor sleep and self-critical thoughts. She has no suicidal plan. What is the SINGLE most appropriate first-line treatment for moderate-severe depression in a young person?', 'NICE recommends psychological therapy first-line for depression in children and young people. Fluoxetine is the only antidepressant with good evidence in under-18s, used alongside therapy and only after specialist (CAMHS) assessment. TCAs and venlafaxine should not be used. Close monitoring for suicidal thoughts is needed when starting antidepressants.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9b1f8541-aef3-5531-995b-19d3752c6e45', '6e54fdfa-077f-53ee-bf85-7d42539d3999', 'A', 'Venlafaxine', false, 0),
  ('4afbca2b-080e-5b2d-a32d-2ddf7d352b84', '6e54fdfa-077f-53ee-bf85-7d42539d3999', 'B', 'Psychological therapy (e.g. CBT), with fluoxetine only if needed and under specialist (CAMHS) supervision', true, 1),
  ('7fbf066d-bd33-537e-86d9-e1dd718de274', '6e54fdfa-077f-53ee-bf85-7d42539d3999', 'C', 'Amitriptyline', false, 2),
  ('8e9a3d27-2cd4-570b-b5ce-8973365e87f7', '6e54fdfa-077f-53ee-bf85-7d42539d3999', 'D', 'Sertraline from the GP alone', false, 3),
  ('1d150b2c-c122-525f-8c6d-75ab541140d5', '6e54fdfa-077f-53ee-bf85-7d42539d3999', 'E', 'Lithium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('48ff9f80-3280-5489-8540-4ee5e406f5fc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 45 year old woman wants to stop paroxetine, which she has taken for 2 years for depression. She has been well for 1 year. What is the SINGLE most appropriate advice?', 'Antidepressants should be continued for at least 6 months after remission (2 years if at risk of relapse). They should be stopped gradually to avoid discontinuation symptoms (dizziness, ''electric shock'' sensations, anxiety, irritability, flu-like symptoms). This is especially important for short half-life drugs such as paroxetine and venlafaxine. Fluoxetine has a long half-life and rarely causes this.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9073c2e7-28a0-597a-a217-d6ba3dd526f5', '48ff9f80-3280-5489-8540-4ee5e406f5fc', 'A', 'Continue lifelong', false, 0),
  ('fffc4a9b-22fe-5a92-bbda-4a9d2ef6bf2d', '48ff9f80-3280-5489-8540-4ee5e406f5fc', 'B', 'Reduce the dose gradually over at least 4 weeks (longer if needed) to avoid discontinuation symptoms', true, 1),
  ('2167ad5f-0df2-5ff3-91d3-65e4dd3ddae5', '48ff9f80-3280-5489-8540-4ee5e406f5fc', 'C', 'Halve the dose for 1 day then stop', false, 2),
  ('1263cb18-ecab-5441-b31d-3ded1fabff44', '48ff9f80-3280-5489-8540-4ee5e406f5fc', 'D', 'Switch to diazepam', false, 3),
  ('0913dc27-7e65-5936-85a2-367bd47fcc3e', '48ff9f80-3280-5489-8540-4ee5e406f5fc', 'E', 'Stop immediately', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e511abbc-ddbe-57ed-b876-c38d400b244b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 68 year old woman on citalopram for depression has new confusion and lethargy. Her serum sodium is 121 mmol/L. She takes no diuretics. What is the SINGLE most likely cause?', 'SSRIs can cause hyponatraemia through SIADH, especially in older people, those on diuretics and in the first weeks of treatment. Sodium should be checked if there is drowsiness, confusion or seizures. Management depends on severity: stop the SSRI, restrict fluids and consider an alternative such as mirtazapine. Citalopram also prolongs the QT interval in a dose-related way.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b5ac6963-39e6-5cbc-a755-5ab2b2d65feb', 'e511abbc-ddbe-57ed-b876-c38d400b244b', 'A', 'Heart failure', false, 0),
  ('003f827d-9fe4-5ede-8109-533a2ab09405', 'e511abbc-ddbe-57ed-b876-c38d400b244b', 'B', 'Lithium toxicity', false, 1),
  ('daf9102d-1343-5e2a-b98e-c2630ba6b45c', 'e511abbc-ddbe-57ed-b876-c38d400b244b', 'C', 'Dehydration', false, 2),
  ('915c36a1-762b-5caa-b7f1-118c6e5f5676', 'e511abbc-ddbe-57ed-b876-c38d400b244b', 'D', 'Addison''s disease', false, 3),
  ('0e8f1954-3771-5f41-a80d-aa23f0ea5bca', 'e511abbc-ddbe-57ed-b876-c38d400b244b', 'E', 'SSRI-induced SIADH', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('21d799ae-5da0-5487-8491-ea2389b89e45', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 35 year old man has had severe insomnia for 2 weeks after starting a new stressful job. He asks for sleeping tablets. What is the SINGLE most appropriate initial management?', 'Short-term insomnia is first managed with sleep hygiene (a regular routine, avoiding caffeine, alcohol and screens, keeping the bedroom dark). A hypnotic (such as zopiclone) can be used for the shortest time, at most 1-2 weeks, for severe distress, because of dependence and next-day impairment. CBT for insomnia (CBT-I) is first-line for chronic insomnia. Melatonin is licensed for people aged 55 and over.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7ba0a9fb-a4e0-58d5-b92f-7f764ccd170e', '21d799ae-5da0-5487-8491-ea2389b89e45', 'A', 'Antipsychotic', false, 0),
  ('f48c7c7a-34d3-5cf5-9ad4-f12760f5ead0', '21d799ae-5da0-5487-8491-ea2389b89e45', 'B', 'Long-term zopiclone', false, 1),
  ('8661f885-5130-5549-91b5-86912330b930', '21d799ae-5da0-5487-8491-ea2389b89e45', 'C', 'Melatonin for all adults over 18', false, 2),
  ('a42e52c8-ffd0-5f2f-b5da-9f719ce11bfc', '21d799ae-5da0-5487-8491-ea2389b89e45', 'D', 'Sleep hygiene advice and, if severe, a short course (up to 1-2 weeks) of a hypnotic', true, 3),
  ('1ddd4410-c8d1-57d7-afb3-3ce0807698ca', '21d799ae-5da0-5487-8491-ea2389b89e45', 'E', 'Diazepam for 3 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 48 year old man drinks a bottle of vodka a day. He is admitted for an unrelated reason and 2 days later becomes agitated, confused, tremulous, sweaty and tachycardic, and sees insects crawling on the walls. What is the SINGLE most likely diagnosis?', 'Delirium tremens occurs about 48-72 hours after stopping heavy drinking and causes confusion, visual (often tactile or Lilliputian) hallucinations, tremor and autonomic instability. It is a medical emergency with significant mortality. Treatment is oral lorazepam (or parenteral benzodiazepines), Pabrinex, fluids, electrolyte correction and close monitoring. A low-dose antipsychotic is used if there is no response.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1de380ed-4978-5f69-886d-9d7dd2d8ad63', '155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'A', 'Hepatic encephalopathy', false, 0),
  ('9131f849-de96-5509-a747-82e2d2e78d45', '155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'B', 'Wernicke''s encephalopathy', false, 1),
  ('3ea0eee0-907a-558e-acc5-1db7bce24d1b', '155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'C', 'Schizophrenia', false, 2),
  ('fb9bb1f2-6cad-595d-9255-0ecbdd2bf89b', '155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'D', 'Delirium tremens', true, 3),
  ('deb4982f-52ca-5fdd-be26-c009fc31fb54', '155d90a5-7ec4-596a-8ebc-170a87ec6f1d', 'E', 'Korsakoff syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ed304589-16b7-5433-b959-0af20439d518', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 55 year old man with long-term alcohol dependence has profound anterograde amnesia and makes up stories to fill memory gaps. His attention and consciousness are normal. What is the SINGLE most likely diagnosis?', 'Korsakoff syndrome is a chronic amnestic disorder from thiamine deficiency, often after untreated Wernicke''s encephalopathy. It causes severe anterograde (and some retrograde) amnesia and confabulation, with relatively preserved other cognitive function. It is largely irreversible, which is why prompt thiamine is given to at-risk patients.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f76f72ab-bd66-54aa-93fa-aae794305839', 'ed304589-16b7-5433-b959-0af20439d518', 'A', 'Delirium tremens', false, 0),
  ('0ce2bb69-7e86-53e4-8ed0-01a1ec9f48e3', 'ed304589-16b7-5433-b959-0af20439d518', 'B', 'Alzheimer''s disease', false, 1),
  ('d464e6bb-757a-5888-8373-15bf8920f7bb', 'ed304589-16b7-5433-b959-0af20439d518', 'C', 'Frontotemporal dementia', false, 2),
  ('dc7fc22b-9e4f-598b-90e8-f0ad6361e9f1', 'ed304589-16b7-5433-b959-0af20439d518', 'D', 'Korsakoff syndrome', true, 3),
  ('4a064169-8845-50b7-961c-d6626698b296', 'ed304589-16b7-5433-b959-0af20439d518', 'E', 'Wernicke''s encephalopathy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c617b4d4-000f-5666-9831-46aceb75d083', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 68 year old woman has had a 6-month history of low mood, poor concentration and memory complaints. She says ''I don''t know'' to many test questions but is distressed about her memory. Her symptoms began after her husband died. What is the SINGLE most likely diagnosis?', 'Depression in older people can look like dementia (pseudodementia). Features suggesting depression include a relatively rapid onset, a clear precipitant, the patient complaining about their memory, ''don''t know'' answers and mood symptoms. In dementia, people tend to confabulate or minimise deficits. Treating depression improves cognition, but these patients have a higher risk of later dementia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('348f8268-8efa-55d5-83b3-34b858fc5368', 'c617b4d4-000f-5666-9831-46aceb75d083', 'A', 'Lewy body dementia', false, 0),
  ('33b30194-c8f2-56ac-b9cc-aae4d55bf724', 'c617b4d4-000f-5666-9831-46aceb75d083', 'B', 'Vascular dementia', false, 1),
  ('75eec856-5a4c-5e1c-9383-405176e0398d', 'c617b4d4-000f-5666-9831-46aceb75d083', 'C', 'Alzheimer''s disease', false, 2),
  ('60743a1d-414a-5841-86e2-0a198125994b', 'c617b4d4-000f-5666-9831-46aceb75d083', 'D', 'Depressive pseudodementia', true, 3),
  ('95c99432-d75c-5c2d-85f2-590f4d3ef48c', 'c617b4d4-000f-5666-9831-46aceb75d083', 'E', 'Delirium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('73f87d74-35df-5e1e-99e4-6bab126cdb08', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 34 year old woman has had low mood every winter for 4 years, with oversleeping, carbohydrate craving and weight gain. She feels well each summer. What is the SINGLE most likely diagnosis?', 'Seasonal affective disorder is a pattern of recurrent depression with seasonal onset (usually autumn or winter) and remission (spring or summer). Atypical features such as hypersomnia, hyperphagia and weight gain are common. It is treated like other depression (CBT, SSRIs). Light therapy may help, though NICE notes the evidence is uncertain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bfa93831-6bb9-5c49-a212-bb2103e3fed2', '73f87d74-35df-5e1e-99e4-6bab126cdb08', 'A', 'Seasonal affective disorder', true, 0),
  ('8e389bc4-2ef1-5bf1-b7cb-76b7911cf721', '73f87d74-35df-5e1e-99e4-6bab126cdb08', 'B', 'Dysthymia', false, 1),
  ('8b95ac98-4202-5bfb-bd7c-3364b468d049', '73f87d74-35df-5e1e-99e4-6bab126cdb08', 'C', 'Premenstrual dysphoric disorder', false, 2),
  ('04e7ae9e-fbae-5f95-965f-3d7a466ace99', '73f87d74-35df-5e1e-99e4-6bab126cdb08', 'D', 'Bipolar disorder', false, 3),
  ('d5fa8d76-f5f7-5c21-8fd4-0d693a6731b8', '73f87d74-35df-5e1e-99e4-6bab126cdb08', 'E', 'Hypothyroidism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b8aa04c4-606d-5e24-bb2d-b23367402450', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 38 year old woman feels intense fear of being judged in social situations. She avoids eating in public and presentations at work, and blushes and trembles. What is the SINGLE most appropriate first-line treatment?', 'Social anxiety disorder is a persistent fear of social or performance situations because of fear of scrutiny or embarrassment, leading to avoidance. NICE recommends individual CBT specifically for social anxiety. An SSRI (escitalopram or sertraline) is offered if CBT is declined or ineffective. Beta-blockers and benzodiazepines are not routinely recommended.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97abbdbb-020d-5f26-a7a7-2eab0648c03f', 'b8aa04c4-606d-5e24-bb2d-b23367402450', 'A', 'Individual CBT designed for social anxiety disorder', true, 0),
  ('c0d23265-82da-5127-8a4b-0e80133c2bed', 'b8aa04c4-606d-5e24-bb2d-b23367402450', 'B', 'Benzodiazepines', false, 1),
  ('7238854b-ad9c-5f1c-8d20-9cac60fcbaf8', 'b8aa04c4-606d-5e24-bb2d-b23367402450', 'C', 'Antipsychotics', false, 2),
  ('cd8ee083-810b-5bbc-aec1-e13b5cc096ee', 'b8aa04c4-606d-5e24-bb2d-b23367402450', 'D', 'Psychodynamic therapy as first-line', false, 3),
  ('f5c83155-f5c7-577b-8140-b973788dc3b8', 'b8aa04c4-606d-5e24-bb2d-b23367402450', 'E', 'Beta-blockers routinely', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('685aa529-b206-5afe-9fe2-936b0010d091', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 8 year old boy has repeated, sudden, rapid, non-rhythmic movements (eye blinking, shoulder shrugging) and vocal sounds (sniffing, throat clearing) for over a year. They are worse when he is stressed and he can briefly suppress them. What is the SINGLE most likely diagnosis?', 'Tourette syndrome is multiple motor tics plus at least one vocal tic for over 1 year, starting before age 18. It is often associated with ADHD and OCD. Tics are often preceded by an urge and can be briefly suppressed. Management is education and behavioural therapy (habit reversal, CBIT), with medication (aripiprazole, clonidine) for severe tics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c55a84f-e8a4-5ee6-9a37-c3cbf8cf2cf2', '685aa529-b206-5afe-9fe2-936b0010d091', 'A', 'Sydenham''s chorea', false, 0),
  ('f9125119-8742-57ce-99b4-b6f8a3d7da79', '685aa529-b206-5afe-9fe2-936b0010d091', 'B', 'Tourette syndrome', true, 1),
  ('82ed2a41-b992-5364-9bb1-da830f994018', '685aa529-b206-5afe-9fe2-936b0010d091', 'C', 'OCD', false, 2),
  ('d56a6830-4d2d-5d9e-af11-bddb8b141797', '685aa529-b206-5afe-9fe2-936b0010d091', 'D', 'Childhood absence epilepsy', false, 3),
  ('0f8861ef-f99e-5a30-9874-4914ebd427d9', '685aa529-b206-5afe-9fe2-936b0010d091', 'E', 'ADHD', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('290978f3-e934-5864-9275-620db5a5769d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 6 year old boy has not developed spoken words beyond a few phrases. He has very limited interest in other children, lines up toys repetitively and gets very distressed at changes in routine. He flaps his hands when excited. What is the SINGLE most likely diagnosis?', 'Autism spectrum disorder involves persistent difficulties with social communication and interaction plus restricted, repetitive patterns of behaviour, interests or activities (including sensory sensitivities), from early childhood. Diagnosis is by a multidisciplinary specialist assessment. A hearing test is part of the workup. Management is support for communication, education and behaviour. There is no drug treatment for core symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('05126abf-62e6-5cc0-b059-3b320ed63936', '290978f3-e934-5864-9275-620db5a5769d', 'A', 'Hearing impairment alone', false, 0),
  ('ccd059b1-770e-51d6-8364-ba72be747786', '290978f3-e934-5864-9275-620db5a5769d', 'B', 'Global developmental delay', false, 1),
  ('2ed903d0-d5aa-53f3-977a-69b4e29ed186', '290978f3-e934-5864-9275-620db5a5769d', 'C', 'Autism spectrum disorder', true, 2),
  ('1b71552d-af1c-52f8-b090-faa08fc026ea', '290978f3-e934-5864-9275-620db5a5769d', 'D', 'ADHD', false, 3),
  ('b02dacb1-8c58-5902-9aad-532fcf4d897a', '290978f3-e934-5864-9275-620db5a5769d', 'E', 'Selective mutism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 23 year old woman says she has ''lost all feeling for her family'' and feels as if she is watching herself from outside her body, like in a dream. These episodes have recurred over months. She knows they are not real. Reality testing is intact. What is the SINGLE most likely diagnosis?', 'Depersonalisation (feeling detached from oneself) and derealisation (the surroundings feel unreal) with intact reality testing are dissociative experiences. They are often linked to anxiety, trauma or stress. When persistent and distressing, the diagnosis is depersonalisation-derealisation disorder. Psychotic disorders involve loss of reality testing. Psychological therapy is the main treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('66f3a969-8aa4-5d35-b1f2-9294b4bb8881', '99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'A', 'Schizophrenia', false, 0),
  ('8c203468-c4f6-59a4-8e38-c1b2ea5de854', '99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'B', 'Depersonalisation-derealisation disorder', true, 1),
  ('4a9cc03e-1bfe-5ad1-9027-3fd8eab8a0ed', '99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'C', 'Psychotic depression', false, 2),
  ('11de955c-5772-5269-bdc7-bae60553bd93', '99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'D', 'Temporal lobe epilepsy', false, 3),
  ('a9ca9bf1-e551-546e-9ca3-3ca3aa00f06f', '99d2f7d8-997e-5041-9036-4daf64c6ed3b', 'E', 'Delirium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 50 year old man is admitted after an overdose. He has long-standing depression. On assessment he says he still wants to die and has a plan. He refuses to stay. He is assessed by two doctors and an AMHP. The diagnosis is clear but he needs a period of assessment and treatment. Which section is MOST appropriate for initial detention when assessment is needed?', 'Section 2 allows detention for assessment (and treatment) for up to 28 days. It needs two medical recommendations (one Section 12-approved) and an application by an AMHP or the nearest relative. It is used when the person needs assessment, as in an acute crisis. Section 3 (6 months, treatment) is used when the diagnosis and treatment plan are established.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b590c317-684f-52f9-af2f-7c3757f0b9cb', 'beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'A', 'Section 136', false, 0),
  ('a0255544-8397-5bd1-b04f-bb4984df31b3', 'beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'B', 'Section 7 (guardianship)', false, 1),
  ('f61489cd-8da3-5500-9e12-3b88e9873d8f', 'beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'C', 'Section 135', false, 2),
  ('69792fd1-1e50-52db-b157-4bebc3291b50', 'beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'D', 'Section 2', true, 3),
  ('4f3815b0-4972-5e32-ba06-2e58e569aacb', 'beceb517-e2a8-57b5-bed0-0f6d87334d5f', 'E', 'Section 5(2)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('49a336c6-946a-5c80-9ff0-242fc02eddde', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old woman has taken an overdose and refuses treatment for the physical effects of her overdose. She is drowsy and confused from the overdose and is assessed as lacking capacity regarding this decision. What is the SINGLE most appropriate legal framework for giving treatment for the physical effects of her overdose?', 'The Mental Health Act allows treatment of the mental disorder (and its direct consequences in some cases) but not unrelated physical conditions. Physical treatment for someone who lacks capacity is given under the Mental Capacity Act in their best interests. Had she retained capacity, her refusal would need to be respected; capacity assessment here must be thorough and documented, with senior input.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('39008631-2508-5865-bef3-fe3de848b97b', '49a336c6-946a-5c80-9ff0-242fc02eddde', 'A', 'The Mental Capacity Act, treating her in her best interests', true, 0),
  ('195de33d-0afd-50a4-bb11-e81331cda569', '49a336c6-946a-5c80-9ff0-242fc02eddde', 'B', 'Seek a court order before any assessment', false, 1),
  ('b31300bc-a33d-57b3-8a6c-76f34513d693', '49a336c6-946a-5c80-9ff0-242fc02eddde', 'C', 'The Mental Health Act authorises any physical treatment', false, 2),
  ('df83d6f5-0236-511d-879a-34a82da1b11a', '49a336c6-946a-5c80-9ff0-242fc02eddde', 'D', 'Her family can consent for her', false, 3),
  ('15b2aed1-daa7-5806-bb77-90d93427a925', '49a336c6-946a-5c80-9ff0-242fc02eddde', 'E', 'Treat her under common law regardless of capacity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 30 year old woman with schizophrenia stable on her depot antipsychotic plans pregnancy. What is the SINGLE most appropriate advice?', 'Stopping antipsychotics abruptly risks relapse, which itself poses risks in pregnancy. Decisions should be shared and individualised with specialist perinatal mental health input. Many antipsychotics can be continued, with monitoring for gestational diabetes and weight gain. Valproate is contraindicated in women of childbearing potential.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e4ff3f57-edb3-5834-abf4-4044dd17f0f9', 'd57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'A', 'Switch to valproate', false, 0),
  ('d520491f-b2d5-5269-b8d0-290ccb1e4a69', 'd57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'B', 'Stop all antipsychotics immediately', false, 1),
  ('44725d11-b7f7-5df2-a484-0b6f1429b37c', 'd57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'C', 'Discuss risks and benefits with her psychiatrist; do not stop antipsychotics abruptly, and plan care with perinatal mental health services', true, 2),
  ('f3f42ffe-f056-59c9-8fa0-2d7b5ceb8216', 'd57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'D', 'Pregnancy is contraindicated in schizophrenia', false, 3),
  ('e19b6103-10ab-5ccb-8f9b-6e617ecbdf82', 'd57f9c47-d6ef-5f4c-a96d-bc8426e9aacc', 'E', 'Terminate any pregnancy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('189a0be1-8000-530e-b063-aa51de6e2fdc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 26 year old woman requests strong pain relief for abdominal pain and is seen in the Emergency Department. She has no significant past medical history. She looks malnourished. She is restless and irritable. Her temperature is 37.1°C. Which non-prescribed substance is the most important to enquire about in this presentation?', 'A malnourished, restless, irritable patient asking for strong analgesia, with a normal temperature, raises the possibility of opioid withdrawal or drug-seeking behaviour. Heroin is the most important substance to ask about. Opioid withdrawal causes restlessness, irritability, abdominal cramps, yawning, rhinorrhoea and dilated pupils.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('576e4b66-bb5c-51da-b7ae-0d0773f35645', '189a0be1-8000-530e-b063-aa51de6e2fdc', 'A', 'Alcohol', false, 0),
  ('2ef8deed-39a3-5478-90dd-5638284ad0ef', '189a0be1-8000-530e-b063-aa51de6e2fdc', 'B', 'Amphetamines', false, 1),
  ('4e90710d-2c54-5450-a154-8868595bf363', '189a0be1-8000-530e-b063-aa51de6e2fdc', 'C', 'Cannabis', false, 2),
  ('2019cf8e-1c71-5ed8-a9fb-a40738bab599', '189a0be1-8000-530e-b063-aa51de6e2fdc', 'D', 'Cocaine', false, 3),
  ('8901e831-6f08-5e6f-afa1-c7d005808f2b', '189a0be1-8000-530e-b063-aa51de6e2fdc', 'E', 'Heroin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08196708-2733-5f9b-8352-4f17cd84d010', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 26 year old woman has taken an overdose of paracetamol and is seen in the Emergency Department. She says the overdose was impulsive and now regrets taking the tablets. Investigations: Paracetamol level below treatment line for N-acetylcysteine. Which is the most appropriate course of action?', 'Every patient presenting after self-harm should have a psychosocial assessment by a mental health professional (liaison psychiatry) before discharge, even if the overdose was impulsive and the paracetamol level is below the treatment line (NICE NG225). This assesses risk, needs and safeguarding. Discharging without assessment, or admitting automatically, is not appropriate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('50c4a1fe-40f4-5061-9ce5-9b8c6e8ba7ab', '08196708-2733-5f9b-8352-4f17cd84d010', 'A', 'Admit to psychiatric ward', false, 0),
  ('b18f467e-78ad-5c8c-8246-0ba528e7c118', '08196708-2733-5f9b-8352-4f17cd84d010', 'B', 'Assessment by liaison psychiatry in Emergency Department', true, 1),
  ('6e640d07-8a1f-5652-91e6-94b15693e6f8', '08196708-2733-5f9b-8352-4f17cd84d010', 'C', 'Discharge home with GP follow-up', false, 2),
  ('a04cbcaa-72bc-579e-967e-127a011ed70c', '08196708-2733-5f9b-8352-4f17cd84d010', 'D', 'Prescribe antidepressant medication', false, 3),
  ('e3114a54-4ca4-5b1f-9b44-3f2adf97022c', '08196708-2733-5f9b-8352-4f17cd84d010', 'E', 'Refer for cognitive behavioural therapy (CBT)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('364ee6bd-8844-5c6d-862f-e4b6540ff290', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 50 year old man wants to stop drinking alcohol and has been admitted to the inpatient ward for detoxification. He is alcohol dependant and his average alcohol intake is 84 units a week for 3 months. He has no other relevant medical history. Which is the most appropriate initial drug to prescribe?', 'For inpatient alcohol detoxification, NICE recommends a long-acting benzodiazepine such as chlordiazepoxide on a reducing regimen, plus thiamine. Clomethiazole is not recommended because of the risk of respiratory depression. Disulfiram is used later to support abstinence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('48538ae4-5607-529e-90e3-9015d9d8e506', '364ee6bd-8844-5c6d-862f-e4b6540ff290', 'A', 'Chlordiazepoxide', true, 0),
  ('fd03fb50-4d15-5f05-907e-74074ac0a1d2', '364ee6bd-8844-5c6d-862f-e4b6540ff290', 'B', 'Clomethiazole', false, 1),
  ('cafa35e6-0355-55ab-b8c7-df68d188e20b', '364ee6bd-8844-5c6d-862f-e4b6540ff290', 'C', 'Disulfiram', false, 2),
  ('f2843442-0a5c-5c08-92e9-520aaf581cb8', '364ee6bd-8844-5c6d-862f-e4b6540ff290', 'D', 'Fluoxetine', false, 3),
  ('14441445-44c9-526d-96b2-18b097f45ec3', '364ee6bd-8844-5c6d-862f-e4b6540ff290', 'E', 'Propranolol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 65 year old woman has low mood, hopelessness, anhedonia, poor concentration, low energy, insomnia, lack of appetite and suicidal ideation for 8 weeks. She takes long-term anticoagulant therapy with warfarin for atrial fibrillation. Which is the most appropriate management?', 'This is severe depression with suicidal ideation, so an antidepressant is needed alongside psychological therapy. Sertraline is preferred in older people and those with cardiac disease. Because SSRIs increase bleeding risk with anticoagulants, monitoring and gastroprotection are advised. TCAs such as amitriptyline are toxic in overdose and cause postural hypotension, which is a particular concern with suicidal ideation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15177d18-a8d0-5ac1-b5a6-47064c1ff06f', '654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'A', 'Amitriptyline', false, 0),
  ('1a1b954a-9653-5ca9-9942-4005b77feb48', '654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'B', 'Cognitive behavioural therapy', false, 1),
  ('f0a20f5e-ef12-57a9-857e-c5e9066d59fb', '654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'C', 'Psychodynamic therapy', false, 2),
  ('6201e9fd-0c78-5d32-b018-ee19c8f592c8', '654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'D', 'Sertraline', true, 3),
  ('5c3b8f8f-e5e9-5b3b-b20c-cc934539042f', '654ec3b7-4c61-5e23-939b-7b259e3f8fd6', 'E', 'Zopiclone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a4e5e522-3e57-567a-878b-2ede47d4c17f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 36 year old woman gave birth to her first child 3 weeks ago. She feels tired and is worried about her lack of feelings for her baby. She had episodes of anxiety and depression in past and was treated with anxiolytics. She had been well for the last 3 years and takes no medication now. She has lost her appetite, her sleep is disturbed and occasionally she is aware of intrusive thoughts of harming the baby. Which is the most likely diagnosis?', 'Low mood, anhedonia, lack of feelings for the baby, poor sleep and appetite, and intrusive thoughts of harm (without intent or psychotic features) 3 weeks after birth fit postnatal depression. A past history of depression increases the risk. Puerperal psychosis presents earlier, often within 2 weeks, with mania, delusions or hallucinations. The Edinburgh Postnatal Depression Scale is a screening tool.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0adb1824-a4b7-5f96-a408-66061c4757a3', 'a4e5e522-3e57-567a-878b-2ede47d4c17f', 'A', 'Generalised anxiety disorder', false, 0),
  ('c3c9bcb8-5951-5f24-944e-73ad79fc372b', 'a4e5e522-3e57-567a-878b-2ede47d4c17f', 'B', 'Normal postnatal symptoms', false, 1),
  ('91a8ef59-5176-5380-b72e-0e8390a03b0f', 'a4e5e522-3e57-567a-878b-2ede47d4c17f', 'C', 'Obsessive compulsive disorder', false, 2),
  ('a12581f8-3b00-56ce-a121-06abb199df56', 'a4e5e522-3e57-567a-878b-2ede47d4c17f', 'D', 'Postnatal depression', true, 3),
  ('1cbac9a8-889a-57f7-8c20-2b7761504c79', 'a4e5e522-3e57-567a-878b-2ede47d4c17f', 'E', 'Puerperal psychosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 32 year old woman has intermittent palpitations, paraesthesia, breathlessness and dizziness for 6 months. She is unable to tolerate crowded places and avoids trains and supermarkets. Which is the most appropriate long-term treatment?', 'Palpitations, paraesthesia, breathlessness and dizziness with avoidance of crowded places, trains and supermarkets suggest panic disorder with agoraphobia. NICE recommends CBT and, for drug treatment, an SSRI such as sertraline as first-line. Benzodiazepines are not recommended long-term.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
