  ('533ca1c0-df8c-517f-9393-2c28f8ad1a3c', '4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'A', 'Amitriptyline', false, 0),
  ('42db4467-f98e-5e78-8226-6e70bdea6315', '4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'B', 'Diazepam', false, 1),
  ('04328825-4118-534f-9f9b-5960c9b8d477', '4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'C', 'Moclobemide', false, 2),
  ('d896adf8-4c0a-5115-adf9-cf7e8bb8cf47', '4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'D', 'Propranolol', false, 3),
  ('2c9a2fec-0f0d-5f39-ba2f-e0b35ac356b6', '4045b7c1-25a6-5fed-ae5f-c86f9c1a2cc0', 'E', 'Sertraline', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('57522549-c6dc-5c49-b564-91828c81237d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 44 year old man has a superficial cut on his arm after a fall, whilst intoxicated with alcohol, 24 hours ago and seen in the Emergency Department. He has been drinking 40 units of alcohol a week for 10 years. He has no signs of acute alcohol withdrawal or current intoxication. Which would be the most appropriate next step?', 'He is drinking above recommended limits (40 units a week) and has had an alcohol-related injury, but has no withdrawal or acute risk. This is an opportunity for a brief intervention and referral to alcohol support services. Admission or urgent psychiatric referral is not needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2798d85f-2cd1-5468-9033-c76bbda4203c', '57522549-c6dc-5c49-b564-91828c81237d', 'A', 'Admit to medical unit for observation', false, 0),
  ('b7b418b5-1332-5dbd-9b51-33b441ebe754', '57522549-c6dc-5c49-b564-91828c81237d', 'B', 'No further action required', false, 1),
  ('76f949b1-1328-5243-b93f-23d7118e09c2', '57522549-c6dc-5c49-b564-91828c81237d', 'C', 'Refer back to GP for review in 48 hours', false, 2),
  ('1d7059ef-640d-5e53-b1b4-6cb8296b4471', '57522549-c6dc-5c49-b564-91828c81237d', 'D', 'Refer to alcohol support services', true, 3),
  ('6b2eae72-6ae1-5889-aff3-9c0fbbc17e33', '57522549-c6dc-5c49-b564-91828c81237d', 'E', 'Urgent referral to liaison psychiatry', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('473e13c9-e157-5ddf-9032-c607adc069ff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 28 year old man has persecutory auditory hallucinations. He says he is the King of Spain and has a number of other fixed abnormal beliefs. He is seen in the psychiatric unit and is diagnosed with schizophrenia. He is prescribed antipsychotic medication. He is keen to understand the underlying changes in his brain biochemistry. Which neurotransmitter is primarily implicated in the pathophysiology of schizophrenia?', 'The dopamine hypothesis links positive symptoms of schizophrenia to excess dopamine activity in the mesolimbic pathway. Antipsychotics work mainly by blocking D2 receptors. Blocking other pathways explains side effects: extrapyramidal effects (nigrostriatal) and hyperprolactinaemia (tuberoinfundibular).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e79637f3-df00-518a-9fae-1d8758f07c94', '473e13c9-e157-5ddf-9032-c607adc069ff', 'A', 'Acetylcholine', false, 0),
  ('48420c14-8b6d-507e-8dbf-b07b887e81da', '473e13c9-e157-5ddf-9032-c607adc069ff', 'B', 'Adenosine triphosphate', false, 1),
  ('f60c4e9f-bf28-50c6-a1f5-191b1a3d1022', '473e13c9-e157-5ddf-9032-c607adc069ff', 'C', 'Dopamine', true, 2),
  ('b07cc801-8918-5244-8765-58c2d192a0c7', '473e13c9-e157-5ddf-9032-c607adc069ff', 'D', 'Histamine', false, 3),
  ('9ec5a012-4c44-52b6-b95d-91f40f1d81b0', '473e13c9-e157-5ddf-9032-c607adc069ff', 'E', 'Substance P', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 55 year old woman has been sleeping for only a couple of hours a night for 2 weeks. She is feeling overactive and feels little need to sleep due to all the activities she is involved in. She was diagnosed with depression and started on antidepressant medication 3 months ago. Which is the most appropriate next step in her management?', 'Elevated mood, overactivity and a reduced need for sleep after starting an antidepressant suggest an antidepressant-induced hypomanic or manic switch, which may reveal bipolar disorder. The first step is to stop the antidepressant, then assess her, possibly starting an antipsychotic or mood stabiliser.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e52259a3-e6da-583a-8ecc-ee8164ea8549', '8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'A', 'Increase her antidepressant dose', false, 0),
  ('7eb89c0c-1497-5f7c-88c3-ecb371bbf855', '8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'B', 'Start lithium', false, 1),
  ('425acb5f-824b-5622-a6d7-bf640b4a9816', '8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'C', 'Start olanzapine', false, 2),
  ('6e485e64-4615-511f-acba-8e4e2d8df0a3', '8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'D', 'Stop her antidepressant', true, 3),
  ('029e2caa-a2ac-5a64-a905-b3c3d56160fd', '8df3b4ed-9a7d-5c88-b57a-a3860a4ab5fd', 'E', 'Switch to a different antidepressant', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('39504e6a-39a0-5ece-a891-6f173d3d0934', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 40 year old woman is increasingly anxious about her cravings to drink alcohol and is seen in her GP surgery Alcohol addiction was diagnosed following an admission with alcoholic hepatitis and she recently completed a community alcohol detoxification. She attends Alcoholics Anonymous meetings regularly. She is worried that she might start drinking again. Which medication will be the most helpful to her to remain abstinent?', 'After successful detoxification, NICE recommends acamprosate or naltrexone, with psychosocial support, to prevent relapse in alcohol dependence. Acamprosate reduces cravings. Chlordiazepoxide and diazepam are for withdrawal, and lofexidine is for opioid withdrawal.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a808dc51-81b3-558e-9d2a-cc144ee9a9a2', '39504e6a-39a0-5ece-a891-6f173d3d0934', 'A', 'Acamprosate', true, 0),
  ('30883b16-b44b-5a87-bb14-f02d34a2a64b', '39504e6a-39a0-5ece-a891-6f173d3d0934', 'B', 'Carbamazepine', false, 1),
  ('8859e004-13d9-58dc-9d69-5b18295cafc1', '39504e6a-39a0-5ece-a891-6f173d3d0934', 'C', 'Chlordiazepoxide', false, 2),
  ('ef862ff1-37e3-5bf5-beba-6c3070e4ea8c', '39504e6a-39a0-5ece-a891-6f173d3d0934', 'D', 'Diazepam', false, 3),
  ('cb79e0f5-a5d3-5c29-b4a5-684ab3ac8cfc', '39504e6a-39a0-5ece-a891-6f173d3d0934', 'E', 'Lofexidine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 26 year old woman has taken a significant overdose of antidepressant and antipsychotic medication and is treated in the intensive care unit. She was transferred to the psychiatric ward 2 days ago. Before taking the overdose, she had written a suicide note. Two days before her overdose she permanently lost custody of her only child. She lives alone and has no social support. She now wants to leave the ward stating that she finds it too noisy to relax. Which is the most appropriate next step?', 'A serious overdose with a suicide note and a recent major loss indicates high ongoing suicide risk. If she wants to leave and will not stay voluntarily, detention under the Mental Health Act (such as Section 2) for assessment is appropriate to keep her safe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('964458ab-c84b-50b6-87d0-2050e61df0d7', '434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'A', 'Arrange for home leave for a 6 hours of respite', false, 0),
  ('9b81826d-c8a4-5014-83ae-2a148c06162e', '434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'B', 'Allow her to be leave against medical advice', false, 1),
  ('ed01352a-025f-5ba7-904a-496db8922b88', '434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'C', 'Compulsorily detain for further assessment', true, 2),
  ('ea718d58-a6dc-5880-8faf-f5e46a5bd092', '434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'D', 'Refer her to crisis and home treatment team', false, 3),
  ('1e6cb0f9-0f92-5cea-9b6d-e3c85ba49a5f', '434a04de-8a4b-5ea0-ac30-fde4948d3ea0', 'E', 'Prescribe sedating medication', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ae2ed89-c771-5b9b-86a4-48f397e64664', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'An 84 year old woman falls at her care home. She cannot bear weight and her right leg is shortened and externally rotated. An X-ray confirms a displaced intracapsular fracture of the right femoral neck. Before the fall she walked independently outdoors with a stick and has no cognitive impairment. What is the SINGLE most appropriate surgical management?', 'Displaced intracapsular fractures disrupt the blood supply to the femoral head, so they need joint replacement. NICE recommends total hip replacement for patients who walked independently outdoors with no more than a stick, without cognitive impairment, and who are medically fit. Otherwise a hemiarthroplasty is done. Extracapsular (intertrochanteric) fractures are treated with a dynamic hip screw. Surgery should be done on the day of admission or the next day.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb08042b-453b-587d-953a-cd3a568a745b', '4ae2ed89-c771-5b9b-86a4-48f397e64664', 'A', 'Conservative management with bed rest', false, 0),
  ('818b4e55-c29a-5986-b405-f9131d02d8ab', '4ae2ed89-c771-5b9b-86a4-48f397e64664', 'B', 'Total hip replacement', true, 1),
  ('8ee74c03-2c79-5a62-9a58-fda71289bb7d', '4ae2ed89-c771-5b9b-86a4-48f397e64664', 'C', 'Intramedullary nail', false, 2),
  ('6f5efd7a-3ae9-5117-a58e-a3d0e58090c6', '4ae2ed89-c771-5b9b-86a4-48f397e64664', 'D', 'Dynamic hip screw', false, 3),
  ('aa9b3d54-f38d-531a-8b1b-84ab0f3cbf14', '4ae2ed89-c771-5b9b-86a4-48f397e64664', 'E', 'Cannulated screws', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 25 year old man has a tibial shaft fracture treated with a plaster cast. Six hours later he has severe pain in his lower leg that is not relieved by morphine and is much worse when his toes are passively stretched. His foot pulses are present. What is the SINGLE most appropriate immediate management?', 'Pain out of proportion to the injury and pain on passive stretch are the earliest signs of acute compartment syndrome. Pulses are usually present until late, so a palpable pulse does not exclude it. Management is to remove all dressings and split the cast down to skin, keep the limb at heart level (not elevated) and arrange urgent fasciotomy. Delay causes muscle necrosis and permanent disability.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d39d5a1c-516d-55c5-88c1-a944b6a78a24', '220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'A', 'Arrange Doppler studies in the morning', false, 0),
  ('4b492303-9e6e-5881-882e-6576da3c31e4', '220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'B', 'Reassure; the pulses are present', false, 1),
  ('0ce0dea4-26c0-566f-84d1-a6059f3da58b', '220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'C', 'Elevate the leg high above the heart and give more morphine', false, 2),
  ('983a0e35-5c67-5dd4-b140-b06ba1c7a760', '220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'D', 'Split the cast to skin and arrange urgent fasciotomy', true, 3),
  ('14d4222f-f45f-56c2-9cbd-739ca5d7ce77', '220b7ea3-5aee-5509-817b-6dfe031f9d8a', 'E', 'Apply a tighter cast', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 44 year old man felt a sudden ''kick'' to the back of his left heel while playing squash, and now has difficulty walking. There is a palpable gap 4 cm above the heel. When his left calf is squeezed while he lies prone, the foot does not plantarflex. What is the SINGLE most likely diagnosis?', 'A sudden pop or kick sensation at the back of the heel during sport, a palpable gap and a positive Simmonds'' (calf squeeze) test indicate Achilles tendon rupture. Risk factors include fluoroquinolones such as ciprofloxacin and steroid use. Ultrasound confirms it. Management is urgent orthopaedic referral, with immobilisation in equinus (operative or non-operative treatment).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2b7c0d96-0ff4-5e05-920f-243c99c19a95', '02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'A', 'Ankle fracture', false, 0),
  ('830e8154-e182-5bfc-a5ae-6dc63bfb41ef', '02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'B', 'Deep vein thrombosis', false, 1),
  ('09be431d-3daa-5c66-a66a-4ba4f3406759', '02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'C', 'Plantar fasciitis', false, 2),
  ('4548e517-5f06-5e28-bec7-43e21b9e1236', '02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'D', 'Achilles tendon rupture', true, 3),
  ('37067a15-229f-5ef4-90ce-135d76e385ec', '02357580-82a6-5d82-9fbc-5e1e25d9bb01', 'E', 'Calf muscle strain', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d77ff444-11ba-5c27-b216-403e308ed360', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 30 year old man fell onto his outstretched hand. He has pain and tenderness in the anatomical snuffbox. Initial scaphoid X-rays are normal. While waiting for further imaging, what is the SINGLE most appropriate management?', 'Scaphoid fractures are often missed on initial X-ray. The blood supply enters distally, so proximal pole fractures risk avascular necrosis and non-union. The wrist should be immobilised and an MRI arranged (NICE first-line after a normal X-ray). Displaced or proximal fractures may need surgical fixation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a994aad7-831c-515e-99b0-c85383846d08', 'd77ff444-11ba-5c27-b216-403e308ed360', 'A', 'Physiotherapy immediately', false, 0),
  ('04eae3a1-0f2e-5a64-8788-abc47ae8178e', 'd77ff444-11ba-5c27-b216-403e308ed360', 'B', 'Repeat X-ray in 6 months', false, 1),
  ('b620c05d-a7a3-577e-ae70-0d846e8d30e6', 'd77ff444-11ba-5c27-b216-403e308ed360', 'C', 'Discharge with analgesia only', false, 2),
  ('030cb8f6-e13b-532f-8b1f-945f129d6055', 'd77ff444-11ba-5c27-b216-403e308ed360', 'D', 'Immobilise in a splint or cast and arrange MRI', true, 3),
  ('6d20d8d5-7dd4-5bd0-9fc6-461e101d45a4', 'd77ff444-11ba-5c27-b216-403e308ed360', 'E', 'Steroid injection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dfbd5610-6edf-5a76-8640-60da6f2c0235', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 75 year old woman fell onto her outstretched hand. She has a ''dinner fork'' deformity of her wrist. X-ray shows a distal radius fracture with dorsal angulation and displacement. What is the SINGLE most likely fracture type?', 'A Colles'' fracture is a distal radius fracture with dorsal displacement and angulation (dinner fork deformity), from a fall on an outstretched hand, common in older women with osteoporosis. A Smith''s fracture has volar displacement (fall on a flexed wrist). Management is closed reduction and casting, or ORIF if unstable. A fragility fracture should prompt a bone health assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3f628356-4b80-5af9-a235-843c8640da20', 'dfbd5610-6edf-5a76-8640-60da6f2c0235', 'A', 'Galeazzi fracture', false, 0),
  ('75d0d5aa-ad45-5a31-9d72-3e0fc404d589', 'dfbd5610-6edf-5a76-8640-60da6f2c0235', 'B', 'Barton''s fracture', false, 1),
  ('75ad590d-4f77-5c0e-b482-711eb8ae3b3a', 'dfbd5610-6edf-5a76-8640-60da6f2c0235', 'C', 'Smith''s fracture', false, 2),
  ('eb4835f0-1c73-5dc4-a4e7-2c18b00c5084', 'dfbd5610-6edf-5a76-8640-60da6f2c0235', 'D', 'Scaphoid fracture', false, 3),
  ('43c4692b-7fa5-53eb-8f42-fbdd2e992f5b', 'dfbd5610-6edf-5a76-8640-60da6f2c0235', 'E', 'Colles'' fracture', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('91173ee6-cc75-5faf-8db9-0f262524ae5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 25 year old man has had a painful knee after a football injury when his foot was planted and he twisted. He heard a pop and the knee swelled within 1 hour. Anterior drawer and Lachman''s tests are positive. What is the SINGLE most likely diagnosis?', 'ACL rupture typically follows a twisting injury with a pop and rapid haemarthrosis (within hours). Lachman''s test is the most sensitive. MRI confirms it. Management is physiotherapy, with ACL reconstruction for young active people or those with instability. A meniscal tear causes delayed swelling, locking and joint line tenderness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8219e3ba-47d8-572c-95b1-4c9ef2c045ad', '91173ee6-cc75-5faf-8db9-0f262524ae5b', 'A', 'Medial meniscal tear', false, 0),
  ('33059756-8d8e-5aa0-8125-622bd30dcae8', '91173ee6-cc75-5faf-8db9-0f262524ae5b', 'B', 'Posterior cruciate ligament rupture', false, 1),
  ('85a20c53-78ff-5317-adb0-1ce297d77f25', '91173ee6-cc75-5faf-8db9-0f262524ae5b', 'C', 'Anterior cruciate ligament rupture', true, 2),
  ('fd29814a-400f-5bd1-9bdb-8983916235d7', '91173ee6-cc75-5faf-8db9-0f262524ae5b', 'D', 'Medial collateral ligament sprain', false, 3),
  ('950078bf-299e-5011-bc55-1ac9b8d8a7b5', '91173ee6-cc75-5faf-8db9-0f262524ae5b', 'E', 'Patellar dislocation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('18a390a3-424a-5f74-be47-271d3a9c033a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 40 year old man twisted his knee while squatting. The knee swelled the next day. He now has episodes of the knee ''locking'' and tenderness along the medial joint line. McMurray''s test is positive. What is the SINGLE most likely diagnosis?', 'Meniscal tears cause delayed swelling (over 24 hours, because menisci are poorly vascularised), joint line tenderness, locking or giving way, and a positive McMurray''s or Thessaly test. MRI confirms it. A locked knee needs urgent arthroscopy. Degenerative tears in older people are usually managed conservatively.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('70f1e508-9f97-58c6-a36b-85dc9bb4b49d', '18a390a3-424a-5f74-be47-271d3a9c033a', 'A', 'Patellar tendinopathy', false, 0),
  ('4fa9372b-20bc-5f0b-8da8-75991593f70d', '18a390a3-424a-5f74-be47-271d3a9c033a', 'B', 'Septic arthritis', false, 1),
  ('7d4b6a06-907e-5d9a-840c-898bafc0797f', '18a390a3-424a-5f74-be47-271d3a9c033a', 'C', 'Medial meniscal tear', true, 2),
  ('7e44409f-4220-5d99-a7db-f18c8cd6ba40', '18a390a3-424a-5f74-be47-271d3a9c033a', 'D', 'Osteoarthritis', false, 3),
  ('a305acf8-f906-527c-8cde-0c1f6339927c', '18a390a3-424a-5f74-be47-271d3a9c033a', 'E', 'ACL rupture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3bce2081-a404-5792-ad73-8de65692a821', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 55 year old woman has had pain and stiffness in her right shoulder for 4 months. External rotation is severely restricted, both actively and passively. She has diabetes. X-ray is normal. What is the SINGLE most likely diagnosis?', 'Frozen shoulder causes global restriction of both active and passive movement, especially external rotation, with a normal X-ray. It goes through painful, stiff and thawing phases over 1-3 years. It is associated with diabetes. Management is analgesia, physiotherapy and intra-articular steroid injection, with hydrodilatation or release if it is severe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('872b6035-95bf-5a96-a7d8-99c9b6cb010a', '3bce2081-a404-5792-ad73-8de65692a821', 'A', 'Rotator cuff tear', false, 0),
  ('96162adf-1a7a-50a1-af48-ea7df4ae4353', '3bce2081-a404-5792-ad73-8de65692a821', 'B', 'Glenohumeral osteoarthritis', false, 1),
  ('14132d94-f05c-53df-9332-75b97a26cba7', '3bce2081-a404-5792-ad73-8de65692a821', 'C', 'Adhesive capsulitis (frozen shoulder)', true, 2),
  ('da6f26fa-b669-53e8-98f5-88a8c45f15b9', '3bce2081-a404-5792-ad73-8de65692a821', 'D', 'Subacromial impingement', false, 3),
  ('4a33fd24-b742-5f52-a129-3be82988ffe2', '3bce2081-a404-5792-ad73-8de65692a821', 'E', 'Acromioclavicular joint arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3a539136-e08a-5426-a935-a9bbf9881181', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 50 year old painter has had pain in his right shoulder for 2 months, worse when reaching overhead and lying on it at night. He has a painful arc between 60 and 120 degrees of abduction. Passive movement is full. What is the SINGLE most likely diagnosis?', 'A painful arc of 60-120 degrees of abduction with full passive movement suggests subacromial pain (supraspinatus tendinopathy or impingement). Management is analgesia, activity modification, physiotherapy, and a subacromial steroid injection for persistent pain. Weakness may indicate a rotator cuff tear, which needs ultrasound or MRI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b9bd7842-c117-5385-8927-18d8cb26c34b', '3a539136-e08a-5426-a935-a9bbf9881181', 'A', 'Shoulder dislocation', false, 0),
  ('aad52566-353a-5bb8-badd-f5747f8fd480', '3a539136-e08a-5426-a935-a9bbf9881181', 'B', 'Frozen shoulder', false, 1),
  ('2b443d37-5a78-5897-a069-2e4968c35500', '3a539136-e08a-5426-a935-a9bbf9881181', 'C', 'Cervical radiculopathy', false, 2),
  ('3e16f587-03d1-5f23-bd91-3d0a79ab9007', '3a539136-e08a-5426-a935-a9bbf9881181', 'D', 'Subacromial impingement / rotator cuff tendinopathy', true, 3),
  ('96ee78d7-bcff-5811-a1c5-d6ed16880dad', '3a539136-e08a-5426-a935-a9bbf9881181', 'E', 'Osteoarthritis of the glenohumeral joint', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 22 year old man fell onto his shoulder. He holds his arm against his side, externally rotated, and the shoulder looks ''squared off''. He has reduced sensation over the lateral upper arm. What is the SINGLE most appropriate next step?', 'Anterior shoulder dislocation (over 95% of dislocations) causes a squared-off shoulder with the arm held in external rotation. An X-ray before reduction excludes an associated fracture, and neurovascular status (especially axillary nerve sensation over the ''regimental badge'' area) is documented before and after reduction. Recurrence is common in young people. Posterior dislocations are linked to seizures and electric shocks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7d9994f3-5147-5759-bcaf-97772bc8b9ef', 'dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'A', 'Sling and discharge', false, 0),
  ('377cc39a-bd6a-58e2-8771-c589ea0caba7', 'dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'B', 'MRI before reduction', false, 1),
  ('ab068165-df7d-5b36-8e66-06216d3666de', 'dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'C', 'X-ray before reduction, documenting axillary nerve function', true, 2),
  ('6d814848-453b-5ca2-98bb-11136eb30a7d', 'dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'D', 'Immediate reduction without X-ray', false, 3),
  ('cf3ba6ab-b447-5acd-a138-6bf9b20fb3c7', 'dceeb849-4c5a-51d1-be0b-d650511ea6c0', 'E', 'Physiotherapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 6 year old girl fell onto her outstretched hand and has a swollen, painful elbow. X-ray shows a supracondylar fracture. Her radial pulse is weak and her hand is pale. What is the SINGLE most appropriate management?', 'Supracondylar fractures are common in children and risk brachial artery and nerve injury (median nerve, especially the anterior interosseous branch). A pulseless, pale hand needs urgent reduction and fixation. Complications include Volkmann''s ischaemic contracture from compartment syndrome and cubitus varus deformity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e3e3337e-6855-5877-a0d8-c4b0ae4ee610', 'ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'A', 'Collar and cuff and review in 2 weeks', false, 0),
  ('cfecacd4-d095-5bf1-801f-f54f8ee1eaf6', 'ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'B', 'Urgent closed reduction and fixation (orthopaedic emergency)', true, 1),
  ('c756a7c6-6d26-5dcb-a1c2-010d1f2dd364', 'ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'C', 'Physiotherapy', false, 2),
  ('414a3f70-6620-50c0-8fd7-52b5e43f352e', 'ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'D', 'Above-elbow cast without reduction', false, 3),
  ('924113e5-f6e2-57a0-8ee1-5857ca208f8d', 'ef8d94e3-23bf-5647-9dc5-5330d2ad6ccd', 'E', 'MRI first', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 25 year old man punched a wall. He has pain and swelling over the dorsum of his hand near his little finger knuckle, which is depressed. X-ray shows a fracture of the neck of the fifth metacarpal with mild angulation and no rotational deformity. What is the SINGLE most appropriate management?', 'A boxer''s fracture (fifth metacarpal neck) with moderate angulation and no rotation is usually managed conservatively with buddy strapping or a splint and early mobilisation. Any rotational deformity (scissoring) needs reduction. A wound over the knuckle from a punch to the mouth may be a ''fight bite'', which needs antibiotics and exploration.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('44954523-d8b4-5d91-a959-e3cd357919fd', 'b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'A', 'Above-elbow cast for 6 weeks', false, 0),
  ('d28e5879-9d58-54f1-b801-d766326ccab9', 'b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'B', 'Amputation', false, 1),
  ('a607c4e2-f0f3-5f38-94af-59f9a62d523c', 'b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'C', 'No treatment and no follow-up', false, 2),
  ('fe27330f-b15b-5a8a-89c3-30a9da7caf44', 'b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'D', 'Buddy strapping and early mobilisation', true, 3),
  ('8aaaf09c-1dbe-5887-8938-ce27eb0e2897', 'b925f9a2-c9a5-58f4-a74d-c0e383d59706', 'E', 'Open reduction and internal fixation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 3 year old girl was swung by her arms by her father and has suddenly stopped using her right arm, holding it slightly flexed and pronated. There is no swelling or bruising. What is the SINGLE most likely diagnosis?', 'Pulled elbow happens in children aged 1-4 after a sudden pull on the arm, as the annular ligament slips over the radial head. The child stops using the arm, holding it slightly flexed and pronated, with no swelling. Treatment is manipulation (supination and flexion, or hyperpronation), and an X-ray is not needed if the history is typical.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('06d836e7-7c52-500a-b764-0804142c945d', '9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'A', 'Shoulder dislocation', false, 0),
  ('dcfb5bd4-c59e-5908-9572-266408688435', '9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'B', 'Clavicle fracture', false, 1),
  ('2fc90ebb-0091-56bb-9f02-3caee22ceb8f', '9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'C', 'Pulled elbow (radial head subluxation)', true, 2),
  ('f0acb488-efa8-5863-a147-ab1a40769330', '9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'D', 'Septic arthritis', false, 3),
  ('e174cf0d-5989-50c3-8407-c6b701e4237c', '9c7f279c-1479-56eb-9a23-d8ce1ce95e8f', 'E', 'Supracondylar fracture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('00e756d6-b9fb-5304-81b8-695dfd9e7243', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 60 year old woman has had pain at the base of her thumb on the radial side of her wrist, worse when gripping and lifting her grandchild, for 6 weeks. Finkelstein''s test is positive. What is the SINGLE most likely diagnosis?', 'De Quervain''s tenosynovitis is inflammation of the abductor pollicis longus and extensor pollicis brevis tendons in the first extensor compartment. It is common in new mothers and with repetitive use. Pain is reproduced by ulnar deviation with the thumb flexed (Finkelstein''s test). Management is rest, splinting, NSAIDs and a steroid injection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9b404bcc-0045-5066-a2f9-208d02fafb03', '00e756d6-b9fb-5304-81b8-695dfd9e7243', 'A', 'Osteoarthritis of the first CMC joint', false, 0),
  ('244ad83d-6bfc-56a9-8789-b26fa2cc1ce3', '00e756d6-b9fb-5304-81b8-695dfd9e7243', 'B', 'Scaphoid fracture', false, 1),
  ('ef4c411d-2cd1-53fb-b337-d4cf9baef439', '00e756d6-b9fb-5304-81b8-695dfd9e7243', 'C', 'De Quervain''s tenosynovitis', true, 2),
  ('6112f327-141c-5461-9052-19c2830d077c', '00e756d6-b9fb-5304-81b8-695dfd9e7243', 'D', 'Carpal tunnel syndrome', false, 3),
  ('d51f3160-c7a9-556d-81b0-cf2676b20b37', '00e756d6-b9fb-5304-81b8-695dfd9e7243', 'E', 'Trigger thumb', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c85b0685-debd-5227-9c03-32dd4e828663', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 62 year old man has had progressive flexion of his ring and little fingers for 2 years, and cannot place his hand flat on the table. There are palpable cords and nodules in his palm. What is the SINGLE most likely diagnosis?', 'Dupuytren''s contracture is thickening and shortening of the palmar fascia, causing flexion contractures, usually of the ring and little fingers. Risk factors include family history, male sex, alcohol, diabetes, epilepsy drugs and smoking. Surgery (fasciectomy) or needle fasciotomy is considered when the hand cannot be placed flat on a table (positive Hueston''s tabletop test).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('92012e41-83a7-5394-8200-cf65ffc130aa', 'c85b0685-debd-5227-9c03-32dd4e828663', 'A', 'Rheumatoid arthritis', false, 0),
  ('99653950-a83e-53a8-8e10-3ba2c3404b68', 'c85b0685-debd-5227-9c03-32dd4e828663', 'B', 'Dupuytren''s contracture', true, 1),
  ('891ce456-cb2d-5b18-905a-932af82394c3', 'c85b0685-debd-5227-9c03-32dd4e828663', 'C', 'Ulnar nerve palsy', false, 2),
  ('053e1687-47a3-5fd6-ba52-ea4005061520', 'c85b0685-debd-5227-9c03-32dd4e828663', 'D', 'Ganglion', false, 3),
  ('90d18fe6-fcee-5d4f-9598-a18b61afe415', 'c85b0685-debd-5227-9c03-32dd4e828663', 'E', 'Trigger finger', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 55 year old woman''s finger clicks and gets stuck when she bends it, needing the other hand to straighten it. There is a tender nodule at the base of the finger on the palm. What is the SINGLE most appropriate first-line treatment?', 'Trigger finger (stenosing tenosynovitis) happens when a flexor tendon nodule catches at the A1 pulley. It is more common in diabetes and rheumatoid arthritis. A corticosteroid injection is effective first-line, and surgical release of the A1 pulley is used if it persists.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9b7facc4-5ae9-5657-8e0b-1166bd70c570', '035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'A', 'Surgery as first-line', false, 0),
  ('71552749-ed69-5c65-b53f-735f7feb8569', '035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'B', 'Oral antibiotics', false, 1),
  ('a457f27d-2f04-52db-a127-4455f66caa02', '035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'C', 'Physiotherapy only', false, 2),
  ('baea1651-5d61-5cbe-8b53-f8e670fdcc6a', '035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'D', 'Splint for 1 year', false, 3),
  ('ea255ca0-72fb-5840-a914-42ce36d26f27', '035c7f9f-9c4e-5b8b-8e56-1e32ca701ab9', 'E', 'Steroid injection into the tendon sheath', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('afe0ab1b-2eaf-5637-b543-fadce10e553e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 72 year old woman has had pain in the lateral hip, worse when lying on that side and climbing stairs, for 3 months. There is tenderness over the greater trochanter. Hip movements are full. What is the SINGLE most likely diagnosis?', 'Greater trochanteric pain syndrome (formerly trochanteric bursitis) is mostly gluteal tendinopathy, with lateral hip pain worse when lying on that side and point tenderness over the greater trochanter. Management is education, load management, physiotherapy (strengthening), analgesia and sometimes a steroid injection. Hip OA causes groin pain and restricted internal rotation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8b25aedb-c2fd-53c7-9b8c-795f98204610', 'afe0ab1b-2eaf-5637-b543-fadce10e553e', 'A', 'Avascular necrosis', false, 0),
  ('24adb7ae-4831-5087-9d40-fe9524bdd6f1', 'afe0ab1b-2eaf-5637-b543-fadce10e553e', 'B', 'Lumbar radiculopathy', false, 1),
  ('15184891-4ec1-5fa7-8c17-558490c86ffb', 'afe0ab1b-2eaf-5637-b543-fadce10e553e', 'C', 'Femoral neck fracture', false, 2),
  ('a818d145-d830-5a62-81ab-5a67d618852e', 'afe0ab1b-2eaf-5637-b543-fadce10e553e', 'D', 'Greater trochanteric pain syndrome', true, 3),
  ('d30ea2cf-c633-5dc8-b2a2-5bcaa7fe7a69', 'afe0ab1b-2eaf-5637-b543-fadce10e553e', 'E', 'Hip osteoarthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 32 year old long-term steroid user has had increasing groin pain and a limp for 3 months. Hip X-ray is normal. Hip internal rotation is painful. What is the SINGLE most appropriate investigation?', 'Avascular necrosis of the femoral head can be caused by steroids, alcohol, sickle cell disease, SLE, radiation, decompression sickness and trauma. Early X-rays may be normal, so MRI is the most sensitive investigation. Early management includes protected weight-bearing and core decompression, while advanced disease needs a hip replacement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04ecb832-b7df-57bf-9de4-18b9d0411f86', 'e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'A', 'MRI of the hips', true, 0),
  ('68977ea5-cd84-5dcd-9938-4f03cbd52d7b', 'e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'B', 'CT abdomen', false, 1),
  ('69fa13b8-a6d9-5163-b110-fef9fb317a20', 'e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'C', 'Repeat X-ray in 1 year', false, 2),
  ('bcdfd5eb-ca34-5912-844b-0163308c83de', 'e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'D', 'Bone scan only', false, 3),
  ('43d558d3-0ef7-5cd4-a4e1-2149267c1324', 'e8d5e336-53e1-52e9-bccf-0ce3277f8df0', 'E', 'Ultrasound of the groin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('727c5686-29e8-5e62-b3c6-20e3567da83b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 45 year old man has had heel pain for 3 months, worst with the first steps in the morning and after rest. There is tenderness at the medial calcaneal tubercle. What is the SINGLE most appropriate initial management?', 'Plantar fasciitis is the commonest cause of heel pain, worse with the first steps in the morning. Risk factors include obesity, prolonged standing and running. Most cases resolve within a year with conservative management (rest, stretching, insoles, footwear and analgesia). Steroid injection or shockwave therapy is considered for persistent pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4b841413-05e3-5bbc-b75e-3fce66782a57', '727c5686-29e8-5e62-b3c6-20e3567da83b', 'A', 'Steroid injection as first-line in all', false, 0),
  ('b0512921-2002-57d9-994f-db54f88e9f03', '727c5686-29e8-5e62-b3c6-20e3567da83b', 'B', 'Surgery', false, 1),
  ('192e51da-ebe6-5847-9dd6-56d182093b68', '727c5686-29e8-5e62-b3c6-20e3567da83b', 'C', 'Oral antibiotics', false, 2),
  ('0ac3e8d8-fd4f-53fd-80ed-a52199647b76', '727c5686-29e8-5e62-b3c6-20e3567da83b', 'D', 'Immobilisation in a cast for 3 months', false, 3),
  ('ed0d5615-08b2-5eed-a5ba-21dcbe35425e', '727c5686-29e8-5e62-b3c6-20e3567da83b', 'E', 'Stretching exercises (calf and plantar fascia), supportive footwear and analgesia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 38 year old runner has had pain in the front of her shin for 6 weeks, now even at rest, with point tenderness over the mid tibia. X-ray is normal. What is the SINGLE most appropriate investigation?', 'Stress fractures from repetitive loading (runners, military recruits) cause localised bony tenderness and pain that worsens with activity, and then at rest. X-rays are often normal early, so MRI is the investigation of choice. Management is rest and modified weight-bearing. The female athlete triad (low energy availability, menstrual dysfunction, low bone density) should be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('adf3f81a-ad1c-5072-ad50-f206177e02b6', 'f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'A', 'CT angiogram', false, 0),
  ('0cdc8a9f-5607-56c7-a8c9-380d85bf2af5', 'f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'B', 'MRI (to identify a stress fracture)', true, 1),
  ('1ee7f667-7025-53d9-ac84-83b3a295ded2', 'f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'C', 'Ultrasound of the calf', false, 2),
  ('565d8704-dd3e-5d91-ae88-39fcf3c20e8e', 'f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'D', 'Blood tests only', false, 3),
  ('d50a5719-74ef-5aff-81a1-753679eaa0d8', 'f6d1cd04-d887-5a11-87b5-2b42a023f2c8', 'E', 'Nerve conduction studies', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 72 year old man has had back pain radiating into both buttocks and thighs on walking, relieved by sitting or bending forward (such as leaning on a shopping trolley). Foot pulses are normal. What is the SINGLE most likely diagnosis?', 'Neurogenic claudication from lumbar spinal stenosis causes leg pain on walking or standing, relieved by flexion (sitting, bending forward). Vascular claudication is relieved by standing still, with weak pulses. MRI confirms stenosis. Management is analgesia and physiotherapy, with surgical decompression for severe or progressive symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bfcf1eb0-f868-509d-8ea8-90c91b6965f8', 'cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'A', 'Peripheral arterial disease', false, 0),
  ('dc743c51-0fb7-5322-a04a-5c4b79d078ed', 'cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'B', 'Ankylosing spondylitis', false, 1),
  ('689879fa-fc23-5d32-91db-444f8f121b61', 'cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'C', 'Hip osteoarthritis', false, 2),
  ('ed975e39-9d48-518a-a29b-8fc6ea8d908b', 'cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'D', 'Cauda equina syndrome', false, 3),
  ('09586c48-fce6-57b5-8f21-3fc49cb0868e', 'cb89f232-3ba1-5f4a-9622-3ec756bb9c43', 'E', 'Lumbar spinal stenosis (neurogenic claudication)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a21d7b98-c469-5097-965f-b51a8a92fa47', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 68 year old woman has had acute thoracic back pain after lifting a box. She had a wrist fracture 2 years ago. X-ray shows a wedge fracture of T12 with no neurological signs. What is the SINGLE most appropriate long-term management?', 'A vertebral fragility fracture suggests osteoporosis, and bisphosphonates may be started without DEXA in some cases (such as women 75 and over). Secondary causes should be investigated (vitamin D, calcium, TFTs, myeloma screen, testosterone in men). Analgesia, early mobilisation and falls prevention are also important. Red flags for malignancy or infection need further investigation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c84be2e-4e57-5bfc-8287-f513bcc2ec13', 'a21d7b98-c469-5097-965f-b51a8a92fa47', 'A', 'No further investigation', false, 0),
  ('87558e6b-00b4-5525-9bae-8fe01207051e', 'a21d7b98-c469-5097-965f-b51a8a92fa47', 'B', 'Long-term opioids alone', false, 1),
  ('255f7e3b-3b84-5236-84bb-7fef8ccb64a1', 'a21d7b98-c469-5097-965f-b51a8a92fa47', 'C', 'Spinal fusion surgery', false, 2),
  ('da9a3059-64bd-59cf-9638-bc3aef68213f', 'a21d7b98-c469-5097-965f-b51a8a92fa47', 'D', 'Investigate and treat osteoporosis (DEXA, bone profile) and start bone protection', true, 3),
  ('15732488-5810-54e8-98b1-550ea17638ea', 'a21d7b98-c469-5097-965f-b51a8a92fa47', 'E', 'Bed rest for 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('12a3c521-8283-52e2-9df9-f9bf9f50798b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 10 year old boy has had a painful thigh for 3 months, now waking him at night. There is swelling above his knee. X-ray of the distal femur shows a lytic lesion with a ''sunburst'' periosteal reaction and Codman''s triangle. What is the SINGLE most likely diagnosis?', 'Osteosarcoma is the commonest primary bone tumour in adolescents. It affects the metaphysis of long bones (distal femur, proximal tibia) and causes pain, often at night, and swelling. X-ray shows a sunburst pattern and Codman''s triangle. Unexplained bone swelling or pain in a young person needs a very urgent X-ray (within 48 hours). Treatment is neoadjuvant chemotherapy and surgery. Ewing''s sarcoma shows an ''onion skin'' periosteal reaction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('864cf87e-c594-5e75-af76-a82b9da7593d', '12a3c521-8283-52e2-9df9-f9bf9f50798b', 'A', 'Osteosarcoma', true, 0),
  ('3fc5652f-4673-5e26-b056-aaf1de817558', '12a3c521-8283-52e2-9df9-f9bf9f50798b', 'B', 'Growing pains', false, 1),
  ('c451e243-ffac-5bb2-a63f-e4a3ea771d8b', '12a3c521-8283-52e2-9df9-f9bf9f50798b', 'C', 'Osteomyelitis', false, 2),
  ('c2583174-de57-56b1-a7b5-32e697279342', '12a3c521-8283-52e2-9df9-f9bf9f50798b', 'D', 'Osteoid osteoma', false, 3),
  ('528b746e-81b6-5e26-ac08-cadedca4dabf', '12a3c521-8283-52e2-9df9-f9bf9f50798b', 'E', 'Ewing''s sarcoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e878f6d3-cdc1-569b-a051-018f450580d8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 60 year old diabetic man has had a fever and a painful, red, swollen foot for 1 week with an ulcer over a metatarsal head. X-ray shows bone destruction under the ulcer. What is the SINGLE most likely diagnosis?', 'Osteomyelitis in diabetic feet usually spreads from an ulcer. A probe-to-bone test, raised inflammatory markers, X-ray (which may show changes late) and MRI support the diagnosis. Bone biopsy guides antibiotics. Staphylococcus aureus is the commonest organism. Treatment is prolonged antibiotics (often 6 weeks) and surgical debridement or amputation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
