  ('dc289424-70b5-56c9-a56f-05240894cfc8', 'e878f6d3-cdc1-569b-a051-018f450580d8', 'A', 'Stress fracture', false, 0),
  ('33fcca87-b116-58c8-9bb4-5dd469cabd4b', 'e878f6d3-cdc1-569b-a051-018f450580d8', 'B', 'Gout', false, 1),
  ('3f46a073-34cf-5726-a4d7-1148f54cff72', 'e878f6d3-cdc1-569b-a051-018f450580d8', 'C', 'Osteomyelitis', true, 2),
  ('a643b256-b51a-54c1-b6c3-8755e0dc3e08', 'e878f6d3-cdc1-569b-a051-018f450580d8', 'D', 'Charcot arthropathy', false, 3),
  ('08b8195e-e13a-5e12-a5b9-190acb08b444', 'e878f6d3-cdc1-569b-a051-018f450580d8', 'E', 'Cellulitis only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d19e80a4-219f-5f65-b735-189e26983187', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 70 year old woman has had low back pain for 2 months. She had a mastectomy for breast cancer 5 years ago. The pain is constant, worse at night and when lying flat. What is the SINGLE most appropriate investigation?', 'Red flags for spinal metastases include a history of cancer, thoracic pain, pain worse at night or lying flat, unexplained weight loss and age over 50. NICE recommends MRI within 1 week for suspected spinal metastases without neurological symptoms, and within 24 hours if there are neurological signs of cord compression. Breast, lung, prostate, kidney and thyroid cancers commonly spread to bone.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b0c111f8-8140-5cac-ac3e-d1bed7f614ab', 'd19e80a4-219f-5f65-b735-189e26983187', 'A', 'NSAIDs and review in 3 months', false, 0),
  ('e89b775b-90a9-5d86-81e1-74caeb8f8eea', 'd19e80a4-219f-5f65-b735-189e26983187', 'B', 'Plain lumbar X-ray only', false, 1),
  ('2768bd79-52aa-5c4f-bcfa-27b8f50b0659', 'd19e80a4-219f-5f65-b735-189e26983187', 'C', 'Physiotherapy referral', false, 2),
  ('1fb45c4e-d705-5372-a768-b4929efaf836', 'd19e80a4-219f-5f65-b735-189e26983187', 'D', 'Urgent MRI of the whole spine', true, 3),
  ('0ff82db3-d54a-5309-bb1d-9a5cf0565489', 'd19e80a4-219f-5f65-b735-189e26983187', 'E', 'Bone density scan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 28 year old man has had pain on the outside of his knee during long-distance running, worse going downhill. There is tenderness over the lateral femoral epicondyle with a positive Ober''s test. What is the SINGLE most likely diagnosis?', 'Iliotibial band syndrome is an overuse injury in runners and cyclists, causing lateral knee pain from friction over the lateral femoral epicondyle. Management is rest, activity modification, stretching and strengthening of the hip abductors, and physiotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7052d039-9ec2-5e37-b406-0e85781670c9', '2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'A', 'Iliotibial band syndrome', true, 0),
  ('a5954958-5442-5710-934f-c9cefbecd302', '2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'B', 'Lateral meniscal tear', false, 1),
  ('acdc7f97-e629-5a4a-8bfa-cdb7326458cf', '2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'C', 'Patellofemoral pain syndrome', false, 2),
  ('79501026-1055-58d3-a869-519a47fd054a', '2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'D', 'Osgood-Schlatter disease', false, 3),
  ('82f5d9db-2a0d-511c-a085-d7ee99ed5ffb', '2e8f8a7b-4980-52a6-8a19-375df4177bcc', 'E', 'Lateral collateral ligament rupture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0956e246-4e50-5efd-b7c7-48f517ccad69', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'An 80 year old woman has a painful right wrist and is seen in the Emergeny Department. She is frail and lives alone. She has frequent n accidental falls at home He right wrist is swollen and tender. Investigations: X-ray: Fracture of right distal radius with minimal displacement Which is the most appropriate treatment?', 'A minimally displaced distal radius fracture in a frail older woman can be managed non-operatively. Initially a below-elbow backslab is used to allow for swelling, then it is completed or changed to a full cast or splint. Low-energy wrist fractures should prompt a bone health and falls assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b3302dae-0c29-5722-8c79-2377dd0b5a8f', '0956e246-4e50-5efd-b7c7-48f517ccad69', 'A', 'Below elbow backslab plaster of Paris', true, 0),
  ('f934d243-48a0-55f9-9476-fbd822037af2', '0956e246-4e50-5efd-b7c7-48f517ccad69', 'B', 'Below elbow full plaster of Paris', false, 1),
  ('7a6795f2-62b2-5559-aaa0-01373b9f0d57', '0956e246-4e50-5efd-b7c7-48f517ccad69', 'C', 'Closed reduction of fracture', false, 2),
  ('c6004bfa-dcbc-5c8c-941b-5110bb19f0d6', '0956e246-4e50-5efd-b7c7-48f517ccad69', 'D', 'Open reduction and internal fixation', false, 3),
  ('4405d78c-25a8-5bf7-9208-216f070333bf', '0956e246-4e50-5efd-b7c7-48f517ccad69', 'E', 'Wrist splint', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old woman presents to the Emergency Department with a sudden-onset, severe occipital headache that began 14 hours ago while she was gardening. She describes it as the worst headache of her life and vomited twice. She is alert, with no focal neurological deficit and no neck stiffness. A non-contrast CT scan of the head is reported as normal. What is the SINGLE most appropriate next step?', 'A thunderclap headache must be treated as subarachnoid haemorrhage (SAH) until proven otherwise. CT sensitivity for SAH falls the longer it is done after onset, so a normal CT more than 6 hours after onset does not exclude it. A lumbar puncture done at least 12 hours after onset looks for xanthochromia (bilirubin from broken-down red cells), which confirms SAH. Discharging or treating as migraine risks missing a bleed that could re-rupture.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('756214c0-d431-5a8d-a786-c6531f05fc00', '88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'A', 'Lumbar puncture', true, 0),
  ('08b8406c-29d6-5b6d-98d7-04a48f794e79', '88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'B', 'MRI scan of the brain', false, 1),
  ('5dabc539-fc26-5410-9fec-47d1d826cca2', '88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'C', 'Discharge with oral analgesia', false, 2),
  ('9bd992b0-8c2f-5f17-b3ba-27edb007ed36', '88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'D', 'Electroencephalogram (EEG)', false, 3),
  ('a5786191-5573-5bac-a6a9-5a9177990872', '88031e42-31fc-5b87-aefe-fe5949ccf6a6', 'E', 'Oral sumatriptan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 24 year old woman attends her GP with recurrent episodes of throbbing, right-sided headache lasting up to a day. Each attack is preceded by flashing zigzag lines in her vision for about 20 minutes. During attacks she feels nauseated and prefers to lie in a dark room. Paracetamol alone has not helped. She has about two attacks a month. What is the SINGLE most appropriate treatment for her acute attacks?', 'This is migraine with aura. NICE recommends an oral triptan combined with an NSAID or paracetamol for acute attacks when simple analgesia alone fails. Opioids such as codeine are not recommended for migraine. Propranolol and topiramate are prophylactic drugs, used when attacks are frequent or disabling, not for treating an attack. Topiramate is also teratogenic and must be avoided in women who could become pregnant unless strict conditions are met.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('37f914ba-9f1d-576d-ad88-f99dd3915679', 'c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'A', 'Topiramate', false, 0),
  ('99e5fb75-0800-594c-a0d3-d7c85d0c9130', 'c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'B', 'Gabapentin', false, 1),
  ('09fb2b5c-7882-5840-a7ba-4358c8a18897', 'c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'C', 'Oral sumatriptan with ibuprofen', true, 2),
  ('d8e5e8b5-ae26-5198-9422-ac64039f0cc1', 'c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'D', 'Propranolol', false, 3),
  ('6ed9419b-e1c6-533e-a521-9fd8ba68eafc', 'c729f6d3-dfdf-50d5-b5df-fd524fe1fd29', 'E', 'Oral codeine phosphate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3922e524-06bf-588e-b58f-4ceba30a4440', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 30 year old man with known epilepsy is brought to the Emergency Department by ambulance with a generalised tonic-clonic seizure. The paramedics report it has been continuous for 6 minutes. No medication has been given before arrival. IV access has been established and he is receiving high-flow oxygen. His capillary glucose is 6.2 mmol/L. What is the SINGLE most appropriate immediate management?', 'A seizure lasting 5 minutes or more is treated as status epilepticus. First-line treatment is a benzodiazepine: IV lorazepam (4 mg in adults) when IV access is available, or buccal midazolam or rectal diazepam if there is no IV access. Levetiracetam, phenytoin or sodium valproate are second-line if seizures continue after two doses of benzodiazepine. Intubation is for refractory status epilepticus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('51e95294-1c26-5c8b-b2c2-d96a2a296856', '3922e524-06bf-588e-b58f-4ceba30a4440', 'A', 'IV lorazepam', true, 0),
  ('648a92e6-9700-5022-89b1-ffa5c7c0360b', '3922e524-06bf-588e-b58f-4ceba30a4440', 'B', 'Rectal diazepam', false, 1),
  ('6b8cd8fc-6815-512c-8646-b9b9ece6fd15', '3922e524-06bf-588e-b58f-4ceba30a4440', 'C', 'IV levetiracetam', false, 2),
  ('b25d15f8-9177-5eeb-be7f-ad350d78c420', '3922e524-06bf-588e-b58f-4ceba30a4440', 'D', 'Immediate rapid sequence intubation', false, 3),
  ('eb2ac9e5-ae43-5696-8ff3-d3a7cce78fbb', '3922e524-06bf-588e-b58f-4ceba30a4440', 'E', 'IV phenytoin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fa5cdcd4-d964-522b-aab7-782e9a581674', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 67 year old woman is brought to the Emergency Department with sudden weakness of her right arm and leg and difficulty speaking. Her symptoms began 2 hours ago. Her capillary glucose is 6.1 mmol/L and blood pressure 168/94 mmHg. A non-contrast CT head shows no haemorrhage. She takes no anticoagulants. What is the SINGLE most appropriate treatment?', 'This is an acute ischaemic stroke within 4.5 hours of onset, with haemorrhage excluded on CT. She should be offered IV thrombolysis (alteplase or tenecteplase) if there are no contraindications. For thrombolysis, BP must be below 185/110 mmHg. Thrombectomy is offered (up to 6 hours, and later in selected cases) for a confirmed proximal anterior circulation occlusion on CT angiography. Aspirin 300 mg is started 24 hours after thrombolysis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('59508e49-1552-5c1c-a389-019128085a1a', 'fa5cdcd4-d964-522b-aab7-782e9a581674', 'A', 'IV labetalol to lower BP below 120/80 mmHg', false, 0),
  ('67f3dad9-03f4-5fa2-aaa2-958faf1c9cd6', 'fa5cdcd4-d964-522b-aab7-782e9a581674', 'B', 'Clopidogrel and atorvastatin only', false, 1),
  ('91300a76-1e5f-5b3d-ad78-9c1ad25f9859', 'fa5cdcd4-d964-522b-aab7-782e9a581674', 'C', 'IV heparin infusion', false, 2),
  ('c029e2a5-e101-5427-9a87-419271a00f04', 'fa5cdcd4-d964-522b-aab7-782e9a581674', 'D', 'IV thrombolysis with alteplase', true, 3),
  ('e0a2de9f-0669-5cbb-90c5-689b34169b51', 'fa5cdcd4-d964-522b-aab7-782e9a581674', 'E', 'Aspirin 300 mg only, then review in the morning', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2bb14260-85c8-5906-9d90-12571a92390c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 71 year old man attends his GP after 20 minutes of weakness in his left hand and slurred speech this morning, which has completely resolved. His examination is now normal. He is not on anticoagulants and has no bleeding disorder. What is the SINGLE most appropriate management?', 'This is a transient ischaemic attack. NICE (NG128) recommends aspirin 300 mg immediately (unless contraindicated) and referral for specialist assessment within 24 hours of symptom onset. ABCD2 scores are no longer recommended for triage. Investigations include carotid imaging and an MRI brain where appropriate. Secondary prevention is clopidogrel, a statin and BP control, and patients must not drive for 1 month.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('695ecfe2-881c-5cdd-9fac-8f97ad7adef4', '2bb14260-85c8-5906-9d90-12571a92390c', 'A', 'Reassure as symptoms have resolved', false, 0),
  ('bf6e862a-420c-55c1-96a8-f7207eb0977a', '2bb14260-85c8-5906-9d90-12571a92390c', 'B', 'Arrange carotid Doppler before any treatment', false, 1),
  ('152b6fb3-4ed6-5be3-bae3-356ff79ccbc8', '2bb14260-85c8-5906-9d90-12571a92390c', 'C', 'Refer to a routine neurology clinic', false, 2),
  ('e21b00de-e177-5212-97ed-319b3d44a554', '2bb14260-85c8-5906-9d90-12571a92390c', 'D', 'Aspirin 300 mg immediately and refer for specialist assessment within 24 hours', true, 3),
  ('28ceb86e-fc73-58ff-8400-b7b83a194888', '2bb14260-85c8-5906-9d90-12571a92390c', 'E', 'Start warfarin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 38 year old man presents with 5 days of weakness that started in his feet and has climbed to his thighs, with tingling in his hands and feet. Two weeks ago he had diarrhoea. On examination there is symmetrical weakness of the legs with absent knee and ankle reflexes. What is the SINGLE most important monitoring to arrange?', 'Ascending symmetrical weakness with areflexia after a GI infection (often Campylobacter jejuni) is Guillain-Barré syndrome. Respiratory muscles can fail silently, so serial FVC is essential. An FVC below 20 mL/kg, or falling, warrants ICU review for ventilation. Oxygen saturations fall late. Treatment is IV immunoglobulin or plasma exchange. CSF shows raised protein with a normal cell count.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6bf41c88-1f56-5204-a522-be79729615c3', 'a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'A', 'Oxygen saturation alone', false, 0),
  ('2e5afb7a-8902-5acc-b043-cd60864a8a5d', 'a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'B', 'Peak expiratory flow rate', false, 1),
  ('25939c6e-89b5-504e-8603-6399a3210d48', 'a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'C', 'Serial forced vital capacity (FVC)', true, 2),
  ('b692f591-c5a7-5aa4-bc83-a895cc03a8de', 'a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'D', 'Serial CT head', false, 3),
  ('8ed78f8c-9f39-54af-b9ae-01a133d33842', 'a3d9d77b-a6c1-56f7-bbc6-a3f51a5121ad', 'E', 'Daily serum creatine kinase', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8b9ebae1-2686-5037-aeef-12aec315df6f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 28 year old woman presents with blurred vision in her right eye, pain on eye movement and reduced colour vision for 4 days. A year ago she had numbness in both legs for 3 weeks that resolved on its own. She has a relative afferent pupillary defect on the right. What is the SINGLE most appropriate investigation to support the most likely diagnosis?', 'Optic neuritis with a previous episode of sensory symptoms, separated in time and in different places, strongly suggests multiple sclerosis. MRI shows demyelinating plaques (periventricular, juxtacortical, infratentorial and spinal) and is the key investigation for the McDonald criteria. CSF oligoclonal bands support the diagnosis. Acute relapses are treated with high-dose methylprednisolone, which speeds recovery but does not change the long-term outcome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('aa4b1385-aa0d-5ddc-a3b8-da36967b0ab5', '8b9ebae1-2686-5037-aeef-12aec315df6f', 'A', 'Temporal artery biopsy', false, 0),
  ('63438c72-1937-5d93-8b50-38a27d968d41', '8b9ebae1-2686-5037-aeef-12aec315df6f', 'B', 'CT head', false, 1),
  ('b43fd283-1bc9-5581-a7b1-a4171035279a', '8b9ebae1-2686-5037-aeef-12aec315df6f', 'C', 'Lumbar puncture as first-line', false, 2),
  ('9634c695-82dd-5193-9448-bb38680febc5', '8b9ebae1-2686-5037-aeef-12aec315df6f', 'D', 'Visual evoked potentials only', false, 3),
  ('fd754edb-fae1-5313-868e-d2f37dc8a5fb', '8b9ebae1-2686-5037-aeef-12aec315df6f', 'E', 'MRI of the brain and spinal cord with contrast', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 69 year old man has 1 year of a resting tremor in his right hand that improves when he reaches for objects. His wife says he has become slower and his handwriting has become smaller. On examination there is cogwheel rigidity in the right arm, bradykinesia and a shuffling gait with reduced arm swing on the right. What is the SINGLE most likely diagnosis?', 'Asymmetrical resting tremor, bradykinesia and rigidity point to idiopathic Parkinson''s disease, caused by loss of dopaminergic neurons in the substantia nigra. Diagnosis is clinical, and NICE recommends referral to a specialist before treatment. Levodopa (with a decarboxylase inhibitor) is first-line when motor symptoms affect quality of life. Essential tremor is postural or action tremor, symmetrical, and improves with alcohol.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3c0bf55b-bd8b-58bf-8113-2869153b479b', 'b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'A', 'Drug-induced parkinsonism from metoclopramide', false, 0),
  ('3379ed9a-72ca-5632-8a90-60f929474fce', 'b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'B', 'Parkinson''s disease', true, 1),
  ('e800302d-dea3-541d-a6ba-c41df65b4ddc', 'b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'C', 'Normal pressure hydrocephalus', false, 2),
  ('8090582d-4031-5c54-927d-09df9ae3d876', 'b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'D', 'Cerebellar disease', false, 3),
  ('c16b7d0d-359c-55fa-9b0a-3f422758a62e', 'b1474bd9-8d85-550a-bb03-4e8eb14b480b', 'E', 'Essential tremor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 19 year old university student presents with 12 hours of fever, severe headache, neck stiffness and photophobia. She has a positive Kernig''s sign and no rash. GCS is 15/15 with no focal neurology and no papilloedema. Blood cultures have been taken. What is the SINGLE most appropriate next step?', 'Suspected bacterial meningitis needs IV antibiotics (ceftriaxone or cefotaxime) within 1 hour. NICE (NG240) advises an LP within 1 hour of arrival if safe, but antibiotics must not be delayed if the LP cannot be done quickly. CT before LP is only needed for focal signs, papilloedema, seizures or reduced GCS. IV dexamethasone is given with or shortly before the first antibiotic dose in suspected bacterial meningitis. Close contacts need prophylaxis with ciprofloxacin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2215d535-12b9-528c-b6c6-43e2c46b4837', '03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'A', 'IV ceftriaxone without delay, followed by lumbar puncture', true, 0),
  ('ccb7c1b3-f7a1-553d-b86f-8667153646b2', '03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'B', 'Oral amoxicillin', false, 1),
  ('fc9a2065-11a7-5ef7-bc9f-909ea4d51560', '03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'C', 'IV aciclovir alone', false, 2),
  ('f8f77d09-c581-5029-98e1-8fb80d0ad9f3', '03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'D', 'CT head before any antibiotics', false, 3),
  ('04f45336-206f-5799-85d6-60b0f7fa8aaa', '03ee28a7-defe-59ca-a62b-03cf3001a4b2', 'E', 'Lumbar puncture, then wait for CSF results before giving antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 36 year old woman wakes with weakness on the left side of her face. She cannot raise her left eyebrow, close her left eye fully or smile on the left. Her forehead is affected. She has no other neurological deficit, no rash in the ear and no limb weakness. Symptoms started 24 hours ago. What is the SINGLE most appropriate management?', 'A lower motor neurone facial palsy that involves the forehead, with no other deficits, is Bell''s palsy. NICE recommends prednisolone within 72 hours of onset, and eye protection to prevent corneal damage. Antivirals alone are not recommended. A stroke causes an upper motor neurone palsy that spares the forehead. Vesicles in the ear canal suggest Ramsay Hunt syndrome (VZV), which is treated with steroids and antivirals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('40b79873-ac10-5f73-8574-2a062b843d30', '84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'A', 'Urgent CT head for stroke', false, 0),
  ('f89a8177-bdb3-5756-938a-a0794fd8a05e', '84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'B', 'IV thrombolysis', false, 1),
  ('bbe0346c-65b5-50b2-9b6d-c1b11508c2a2', '84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'C', 'Oral prednisolone and eye care with lubricating drops and taping at night', true, 2),
  ('3010b234-ca48-5cc0-903a-919818b8d1a9', '84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'D', 'Oral aciclovir alone', false, 3),
  ('80da2265-56b9-5894-8f1b-41422f43c17f', '84456fba-a1c9-5a1d-ac64-96f9c6faa1a6', 'E', 'No treatment; it always resolves', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('aa224b23-ac10-567f-8f76-26eb2695b2b0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old man with chronic lower back pain presents with 1 day of worsening bilateral sciatica, numbness around his anus and perineum, and difficulty passing urine. On examination there is reduced perianal sensation and reduced anal tone. What is the SINGLE most appropriate investigation?', 'Saddle anaesthesia, bladder or bowel dysfunction, bilateral sciatica and reduced anal tone are red flags for cauda equina syndrome, usually from a large central lumbar disc prolapse. He needs an emergency MRI and urgent surgical decompression to preserve bladder, bowel and sexual function. Delay leads to permanent deficits. Patients with sciatica should be given clear safety-netting advice about these symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b7e5faa0-16d0-50bb-be0e-1d206a81822f', 'aa224b23-ac10-567f-8f76-26eb2695b2b0', 'A', 'CT abdomen', false, 0),
  ('0e7b205e-5e92-5389-9ded-cb2ad88481d4', 'aa224b23-ac10-567f-8f76-26eb2695b2b0', 'B', 'Outpatient MRI in 6 weeks', false, 1),
  ('06a70319-898e-5bb5-9612-ca4d5339b9ad', 'aa224b23-ac10-567f-8f76-26eb2695b2b0', 'C', 'Emergency MRI of the lumbosacral spine', true, 2),
  ('ef9d7c24-ef01-50f8-a8f8-f68ca49cf7fb', 'aa224b23-ac10-567f-8f76-26eb2695b2b0', 'D', 'Nerve conduction studies', false, 3),
  ('27b58f7e-9add-593d-97eb-06fc8861ddc9', 'aa224b23-ac10-567f-8f76-26eb2695b2b0', 'E', 'Plain lumbar spine X-ray', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 32 year old woman has 3 months of double vision and drooping eyelids that get worse towards the evening, and difficulty chewing at the end of meals. Her symptoms improve after rest. Sustained upward gaze makes the ptosis worse. Reflexes and sensation are normal. What is the SINGLE most appropriate investigation?', 'Fatigable weakness affecting the eyes and bulbar muscles, which improves with rest, suggests myasthenia gravis, an autoimmune disease with antibodies against the acetylcholine receptor. AChR antibodies are positive in about 85% of generalised cases (MuSK antibodies in some of the rest). A CT of the chest is needed to look for a thymoma. Treatment is pyridostigmine, immunosuppression and sometimes thymectomy. Myasthenic crisis needs FVC monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2df1fbbe-7a36-5428-9174-1c6dd8c5617e', '1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'A', 'Serum acetylcholine receptor antibodies', true, 0),
  ('7cb908ec-b463-5783-aaf0-5742555297f0', '1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'B', 'MRI brain', false, 1),
  ('cf5d0153-528f-5d52-a78e-9fba2b1a1554', '1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'C', 'Lumbar puncture', false, 2),
  ('20933ce7-09f2-5f24-b539-bcf654f947aa', '1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'D', 'Serum creatine kinase', false, 3),
  ('23aba75d-3526-54d2-a656-30953315c963', '1edcfee9-c20c-5a27-9339-dcdf97ff7490', 'E', 'Muscle biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c89f5923-eac2-575c-a085-f7580b11434a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 66 year old man has a tremor in both hands for 5 years. It is present when he holds a cup and writes, is absent at rest and improves after a glass of wine. His father had a similar tremor. Neurological examination is otherwise normal. What is the SINGLE most appropriate first-line treatment if he wants medication?', 'A bilateral action or postural tremor that improves with alcohol, with a family history (autosomal dominant), is essential tremor. First-line medication is propranolol, with primidone as an alternative. Other neurological signs are absent. Deep brain stimulation is considered for severe, drug-resistant tremor.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0ec5c771-0332-537e-81ef-ef0edd5a02dc', 'c89f5923-eac2-575c-a085-f7580b11434a', 'A', 'Ropinirole', false, 0),
  ('cf34ea38-f87e-58f8-b050-01a9c85f5e6f', 'c89f5923-eac2-575c-a085-f7580b11434a', 'B', 'Levodopa', false, 1),
  ('eb3d01ca-89a6-5e46-af0f-dc5e9c35e405', 'c89f5923-eac2-575c-a085-f7580b11434a', 'C', 'Haloperidol', false, 2),
  ('b660ca41-7132-59f5-97c0-b1213e3b9431', 'c89f5923-eac2-575c-a085-f7580b11434a', 'D', 'Benzhexol', false, 3),
  ('e744e7e6-c2fe-5475-8ab2-1f35d66de62c', 'c89f5923-eac2-575c-a085-f7580b11434a', 'E', 'Propranolol', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 25 year old woman has had a daily headache for 3 months, worse in the morning and on bending, with transient visual blurring. Her BMI is 36 kg/m2. Fundoscopy shows bilateral papilloedema and an MRI brain with venography is normal. What is the SINGLE most likely diagnosis?', 'Idiopathic intracranial hypertension typically affects young obese women. It causes headache, visual obscurations, papilloedema and sometimes sixth nerve palsy, with normal imaging. A lumbar puncture shows a raised opening pressure. Management is weight loss, acetazolamide and visual field monitoring, with surgery if vision is threatened. Causative drugs include tetracyclines and isotretinoin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('85212c3f-e561-5076-a19a-669592bf3899', '0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'A', 'Tension-type headache', false, 0),
  ('85245319-0dcf-5e85-806a-266152286bb1', '0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'B', 'Idiopathic intracranial hypertension', true, 1),
  ('1005a323-0f83-50db-b9ed-138e8a204c7c', '0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'C', 'Cerebral venous sinus thrombosis', false, 2),
  ('faf1899b-2ced-5498-81fa-0d365fe1dd4e', '0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'D', 'Migraine', false, 3),
  ('3cc56552-682b-5716-8cbc-f0dad6aab2e5', '0fb531d2-3c8c-57b6-8c8a-34b78e39d23f', 'E', 'Brain tumour', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4498c97f-ee21-5d06-99f9-dae150014458', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 35 year old man has had severe headaches around his right eye for 2 weeks, lasting 45 minutes and occurring at the same time every night. During attacks the right eye waters and is red, his right nostril is blocked and he is restless and pacing. What is the SINGLE most appropriate acute treatment?', 'Cluster headache causes severe unilateral orbital pain lasting 15-180 minutes with autonomic features (lacrimation, red eye, rhinorrhoea, ptosis), occurring in clusters, often at night, with restlessness. It is more common in men who smoke. Acute treatment is 100% oxygen and SC or nasal sumatriptan. Verapamil is used for prevention. Opioids are ineffective.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7518545e-9bcb-5783-8f02-860cf20d7ab8', '4498c97f-ee21-5d06-99f9-dae150014458', 'A', 'Oral paracetamol', false, 0),
  ('19685764-036d-5b72-951a-774f0d9f1b4c', '4498c97f-ee21-5d06-99f9-dae150014458', 'B', 'Oral prednisolone alone', false, 1),
  ('371312a4-4050-59b5-a154-4eb8413dd102', '4498c97f-ee21-5d06-99f9-dae150014458', 'C', 'High-flow 100% oxygen and subcutaneous sumatriptan', true, 2),
  ('3ccc5d25-361a-5f29-8b21-16a9a8e22b72', '4498c97f-ee21-5d06-99f9-dae150014458', 'D', 'Oral codeine', false, 3),
  ('115c26c7-64fe-51fe-8caa-cdd374abecee', '4498c97f-ee21-5d06-99f9-dae150014458', 'E', 'Oral propranolol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 64 year old woman has sudden attacks of severe, stabbing, electric shock-like pain in her right cheek and jaw lasting seconds. They are triggered by chewing, brushing her teeth and cold wind. Neurological examination is normal. What is the SINGLE most appropriate first-line treatment?', 'Trigeminal neuralgia causes paroxysmal unilateral stabbing pain in the trigeminal distribution, triggered by light touch, chewing or wind. NICE recommends carbamazepine first-line. Atypical features (sensory loss, age under 40, bilateral symptoms, other neurological signs) need specialist referral and MRI to exclude MS or a tumour. Surgical options include microvascular decompression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b48472b8-3a9a-50cd-8d65-3445531d0afa', '9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'A', 'Oral morphine', false, 0),
  ('f6151117-5cbc-5e14-9cf3-5139b9676685', '9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'B', 'Amitriptyline', false, 1),
  ('da79ccd4-3dfa-5af0-83ef-3c47d6f2e4fc', '9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'C', 'Carbamazepine', true, 2),
  ('31ef0fba-46ae-5fe0-bda9-c1ce5b5a9768', '9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'D', 'Gabapentin as first-line', false, 3),
  ('220580c9-5457-5dc9-b51d-0e7d03d00606', '9de6b5e6-4d5d-5d99-b5f2-fe382725db11', 'E', 'Oral prednisolone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ccb5c21b-3dad-521e-9975-3690f3a757e1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 72 year old man has had a progressive gait disturbance, urinary incontinence and memory decline over 6 months. His gait is broad-based and ''magnetic'', as if his feet are stuck to the floor. A CT head shows ventricles enlarged out of proportion to sulcal atrophy. What is the SINGLE most likely diagnosis?', 'The triad of gait apraxia, urinary incontinence and cognitive impairment (''wet, wobbly and wacky'') with ventriculomegaly suggests normal pressure hydrocephalus. A lumbar tap test (removing CSF) may improve gait and predicts a response to a ventriculoperitoneal shunt. It is a potentially reversible cause of dementia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c2a47fd-7114-52da-8300-5c45fce04a48', 'ccb5c21b-3dad-521e-9975-3690f3a757e1', 'A', 'Parkinson''s disease', false, 0),
  ('13e767a1-164d-5ce3-a35e-39acea6dafd7', 'ccb5c21b-3dad-521e-9975-3690f3a757e1', 'B', 'Vascular dementia', false, 1),
  ('3cf5ba25-9d7d-5c87-ab04-01169f3ebb57', 'ccb5c21b-3dad-521e-9975-3690f3a757e1', 'C', 'Alzheimer''s disease', false, 2),
  ('addbc398-2674-527d-958b-3be3c0595cab', 'ccb5c21b-3dad-521e-9975-3690f3a757e1', 'D', 'Normal pressure hydrocephalus', true, 3),
  ('c67c4006-b13f-55ab-98d0-e0037f7eac3a', 'ccb5c21b-3dad-521e-9975-3690f3a757e1', 'E', 'Lewy body dementia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ec2d443e-4b2e-5960-ad26-8e52167fd499', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 74 year old man has had fluctuating confusion, visual hallucinations of small people in his room and falls for 9 months. On examination he has mild bradykinesia and rigidity. His family say he acts out his dreams. What is the SINGLE most likely diagnosis?', 'Dementia with Lewy bodies has fluctuating cognition, well-formed visual hallucinations, parkinsonism and REM sleep behaviour disorder. Antipsychotics must be avoided or used with great caution because of severe sensitivity reactions. Acetylcholinesterase inhibitors (donepezil, rivastigmine) are recommended. If dementia appears more than a year after Parkinson''s motor symptoms, it is Parkinson''s disease dementia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f720eb38-e22f-551c-8fe6-8fdb025130ed', 'ec2d443e-4b2e-5960-ad26-8e52167fd499', 'A', 'Vascular dementia', false, 0),
  ('addd1aa8-f68e-5719-bf8a-025ce150c5c7', 'ec2d443e-4b2e-5960-ad26-8e52167fd499', 'B', 'Frontotemporal dementia', false, 1),
  ('5d990d1f-a29f-54e8-a511-5f08eb78df44', 'ec2d443e-4b2e-5960-ad26-8e52167fd499', 'C', 'Alzheimer''s disease', false, 2),
  ('a0d2df1d-547c-5a73-833e-ab8ae7d4a4bf', 'ec2d443e-4b2e-5960-ad26-8e52167fd499', 'D', 'Parkinson''s disease without dementia', false, 3),
  ('6ffa17f7-9c0e-50f7-9890-79785e0fc351', 'ec2d443e-4b2e-5960-ad26-8e52167fd499', 'E', 'Dementia with Lewy bodies', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 76 year old woman has had progressive memory loss for 2 years. She repeats questions, misplaces items and got lost driving to a familiar shop. Blood tests and CT head (showing generalised atrophy) exclude reversible causes. MMSE is 21/30. What is the SINGLE most appropriate medication?', 'Mild-moderate Alzheimer''s disease is treated with an acetylcholinesterase inhibitor (donepezil, galantamine or rivastigmine). Memantine is for moderate disease when AChE inhibitors are not tolerated, for severe disease, or as add-on. Before starting, an ECG is considered because AChE inhibitors can cause bradycardia. Cognitive stimulation and carer support are also key.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8bd85e52-4c5c-5768-8179-fad82c1aa9cd', 'a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'A', 'Diazepam', false, 0),
  ('dd4b2129-1254-5bdf-899f-7f72900db929', 'a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'B', 'Memantine as first-line monotherapy for mild-moderate disease', false, 1),
  ('67ff874f-4f66-510b-b3f9-df9d73fd58fe', 'a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'C', 'Aspirin', false, 2),
  ('41fc0b41-a68a-50fc-9b21-a798b4e0c9ea', 'a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'D', 'Haloperidol', false, 3),
  ('afd72df4-ecc6-5b88-8346-c0048f06959a', 'a079d80c-6da1-5f28-aa5c-78c36cad9a1a', 'E', 'Donepezil', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('385d6454-b726-5429-bd4c-52c92a7c34f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 58 year old man has had weakness of his right hand for 6 months and is now dropping things. He has wasting of the small muscles of the hands with fasciculations, together with brisk reflexes and extensor plantars. Sensation is normal. What is the SINGLE most likely diagnosis?', 'A mix of upper (brisk reflexes, extensor plantars) and lower (wasting, fasciculations) motor neurone signs with no sensory involvement suggests motor neurone disease (ALS). EMG supports the diagnosis. Riluzole modestly prolongs survival. NIV for respiratory failure and gastrostomy for nutrition improve quality of life and survival. Eye movements and sphincters are usually spared.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d59f9d2c-7a48-5214-ab87-4eed16eee9d8', '385d6454-b726-5429-bd4c-52c92a7c34f8', 'A', 'Peripheral neuropathy', false, 0),
  ('2ec90dc3-1816-54bc-a038-0b4322dbe115', '385d6454-b726-5429-bd4c-52c92a7c34f8', 'B', 'Motor neurone disease', true, 1),
  ('f8de1450-4c76-5674-8b83-6719162b2e3a', '385d6454-b726-5429-bd4c-52c92a7c34f8', 'C', 'Multiple sclerosis', false, 2),
  ('30386332-9101-50b1-97cb-e425372a1188', '385d6454-b726-5429-bd4c-52c92a7c34f8', 'D', 'Cervical myelopathy', false, 3),
  ('77570860-0f58-5e10-ad3a-cd7f2925fe8a', '385d6454-b726-5429-bd4c-52c92a7c34f8', 'E', 'Myasthenia gravis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('224db58d-980d-5c8d-98c8-5666c994b57c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old woman has had numbness and tingling in both feet that is spreading up her legs over a year, in a ''stocking'' pattern. Her ankle reflexes are absent. She has type 2 diabetes with an HbA1c of 82 mmol/mol. Which test is MOST important to identify loss of protective sensation in her feet?', 'Diabetic peripheral neuropathy is length-dependent and symmetrical. NICE recommends annual foot checks including 10 g monofilament testing to identify loss of protective sensation, which predicts ulceration. Patients are risk-stratified (low, moderate, high, active foot problem). Management is glycaemic control, foot care education and treatment of neuropathic pain (amitriptyline, duloxetine, gabapentin or pregabalin).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1c5d3564-cd82-54d3-ae63-2c2774ac67bc', '224db58d-980d-5c8d-98c8-5666c994b57c', 'A', 'MRI spine', false, 0),
  ('5b06a20b-50ff-5650-8d05-197b00f926ba', '224db58d-980d-5c8d-98c8-5666c994b57c', 'B', 'Lumbar puncture', false, 1),
  ('c0f0107e-9ffc-56ee-ad01-98711b2bd318', '224db58d-980d-5c8d-98c8-5666c994b57c', 'C', 'Vibration testing with a 512 Hz fork', false, 2),
  ('0eec06f9-4317-5b21-9596-b1310c3deb57', '224db58d-980d-5c8d-98c8-5666c994b57c', 'D', 'Nerve conduction studies', false, 3),
  ('e783a049-792f-5132-899a-c16f029fa652', '224db58d-980d-5c8d-98c8-5666c994b57c', 'E', '10 g monofilament testing', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 35 year old man has a sudden severe headache and neck pain 3 days after a chiropractic neck manipulation. He has a right Horner''s syndrome and is now unsteady. What is the SINGLE most likely diagnosis?', 'Arterial dissection is an important cause of stroke in young adults. Risk factors include neck trauma or manipulation and connective tissue disorders. It presents with neck pain, headache, Horner''s syndrome (carotid) and posterior circulation stroke symptoms (vertebral). CT or MR angiography confirms it. Antithrombotic treatment (antiplatelet or anticoagulant) is used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('91e6220d-6e8d-5686-be16-38bd9beaf1e9', '4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'A', 'Cluster headache', false, 0),
  ('49315dc0-cb85-589c-a2d6-2a7ec68eb5f2', '4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'B', 'Subarachnoid haemorrhage from berry aneurysm', false, 1),
  ('c33e7bfb-b9f5-5f85-a9f4-0fb1c0d355e5', '4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'C', 'Vertebral or carotid artery dissection', true, 2),
  ('57d04dad-a191-5c9c-b9a5-047240ab7246', '4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'D', 'Migraine with aura', false, 3),
  ('f24ca3df-b497-5040-a567-56578c4bcbe8', '4d8c83ab-df0c-52dc-81ff-e4159b60f28a', 'E', 'Tension headache', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 70 year old woman has sudden onset vertigo, vomiting and difficulty walking. On examination she has nystagmus, right-sided ataxia with past-pointing and dysdiadochokinesis, and she cannot walk unsupported. Her head impulse test is normal. What is the SINGLE most appropriate investigation?', 'Acute vertigo with cerebellar signs, severe gait ataxia and a normal head impulse test (part of HINTS) suggests a posterior circulation stroke rather than vestibular neuritis. An urgent MRI with diffusion weighting is needed, because CT is poor for the posterior fossa. In vestibular neuritis the head impulse test is abnormal and the patient can usually walk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('27fc6afe-2e5d-5310-8220-438082605166', '2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'A', 'Dix-Hallpike test and discharge', false, 0),
  ('c71ee335-549e-5dba-8d5b-722e7ea3522b', '2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'B', 'Audiogram', false, 1),
  ('6b81f9d0-0470-591b-9aef-4089d39b4555', '2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'C', 'Epley manoeuvre', false, 2),
  ('eeacf4e5-0f88-58c3-a042-a9a85bf04207', '2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'D', 'Blood glucose only', false, 3),
  ('49e17324-cd52-5f63-9864-cd50bed71a14', '2e7e81c1-1dc8-5f11-a2e9-6a3f2c179018', 'E', 'Urgent MRI brain (diffusion-weighted)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3e49cb0-f253-5afd-9194-872a776b42cf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 42 year old woman has had episodes of rotatory vertigo lasting 2-3 hours for 6 months, with fluctuating hearing loss, tinnitus and a feeling of fullness in her left ear. Audiometry shows low-frequency sensorineural hearing loss. What is the SINGLE most likely diagnosis?', 'Ménière''s disease causes recurrent vertigo lasting 20 minutes to hours, fluctuating low-frequency sensorineural hearing loss, tinnitus and aural fullness, from endolymphatic hydrops. Acute attacks are treated with prochlorperazine or antihistamines, and betahistine is used for prevention. Patients should tell the DVLA. Unilateral symptoms warrant an MRI to exclude a vestibular schwannoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cd9d2d9e-8791-5d69-b5f9-2367333eab23', 'a3e49cb0-f253-5afd-9194-872a776b42cf', 'A', 'Vestibular neuritis', false, 0),
  ('4e202c0f-7e5c-52e3-a796-e8c10723c764', 'a3e49cb0-f253-5afd-9194-872a776b42cf', 'B', 'Labyrinthitis', false, 1),
  ('f3d76a33-b5fe-5068-b103-77a025c99776', 'a3e49cb0-f253-5afd-9194-872a776b42cf', 'C', 'Ménière''s disease', true, 2),
  ('0d105fa2-9e62-5ce0-899b-fa4a4eaba131', 'a3e49cb0-f253-5afd-9194-872a776b42cf', 'D', 'Benign paroxysmal positional vertigo', false, 3),
  ('f66dea7c-510f-5a09-bc85-d91c90b3674a', 'a3e49cb0-f253-5afd-9194-872a776b42cf', 'E', 'Acoustic neuroma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 52 year old man has had progressive unilateral hearing loss and tinnitus in his right ear for a year. He also has numbness of his right cheek and an absent right corneal reflex. What is the SINGLE most appropriate investigation?', 'Unilateral sensorineural hearing loss and tinnitus with trigeminal involvement (an absent corneal reflex) suggests a vestibular schwannoma (acoustic neuroma) at the cerebellopontine angle. MRI with gadolinium is diagnostic. Bilateral schwannomas suggest neurofibromatosis type 2. Management is surveillance, radiosurgery or microsurgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('801093f1-97a1-5a00-bcb3-34f51f6e144d', 'f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'A', 'Audiometry only', false, 0),
  ('b24a54e3-9c1e-5919-8316-d182d83884f9', 'f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'B', 'EEG', false, 1),
  ('e2d16662-a2d9-5650-b2f4-c5ea1a3c0806', 'f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'C', 'MRI of the internal auditory meatus/cerebellopontine angle', true, 2),
  ('2800647e-f5ae-57d1-8dd0-c866882e7b9f', 'f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'D', 'CT of the sinuses', false, 3),
  ('a8c3164d-503b-5338-aca9-0832ca984ff8', 'f837beb7-62a6-5d64-ac40-84d69d94b8fa', 'E', 'Tympanometry', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a1e70462-ab91-579a-b500-d5224a6dec4d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 30 year old woman with epilepsy, well controlled on lamotrigine, plans to become pregnant. What is the SINGLE most appropriate advice?', 'Women with epilepsy on antiepileptic drugs should take folic acid 5 mg daily from before conception until at least 12 weeks to reduce the risk of neural tube defects. Lamotrigine and levetiracetam carry the lowest teratogenic risk and should be continued, with level monitoring, because lamotrigine levels fall in pregnancy. Valproate must be avoided because of its high risk of malformations and neurodevelopmental problems.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('359e7b13-162f-5a52-a418-979e9f9b0180', 'a1e70462-ab91-579a-b500-d5224a6dec4d', 'A', 'Take folic acid 400 micrograms only after 12 weeks', false, 0),
  ('6db1d8b3-3358-5ce7-82b1-948c6bf94566', 'a1e70462-ab91-579a-b500-d5224a6dec4d', 'B', 'Switch to sodium valproate', false, 1),
  ('26af2b6f-2ca8-5650-a5e2-812e46a8b7b4', 'a1e70462-ab91-579a-b500-d5224a6dec4d', 'C', 'Stop lamotrigine before conception', false, 2),
  ('212fccfa-d41c-5d20-a759-0758029a28a1', 'a1e70462-ab91-579a-b500-d5224a6dec4d', 'D', 'Continue lamotrigine and take folic acid 5 mg daily before conception', true, 3),
  ('bb425a71-379e-581b-b340-10358453db2d', 'a1e70462-ab91-579a-b500-d5224a6dec4d', 'E', 'Avoid pregnancy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4d242306-21b1-5500-b862-57efbeebd580', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 23 year old man is brought to the Emergency Department after his first generalised tonic-clonic seizure. He has fully recovered with a normal examination. His blood tests and ECG are normal. What is the SINGLE most appropriate next step?', 'NICE (NG217) recommends that anyone with a suspected first seizure is seen urgently by a specialist (within 2 weeks), with an MRI and EEG as indicated. Antiepileptics are not usually started after a single unprovoked seizure unless there are high-risk features. He must stop driving and tell the DVLA. Safety advice (bathing, heights) should be given.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dfec29c9-df32-5a5d-bbfb-46e14c4500c2', '4d242306-21b1-5500-b862-57efbeebd580', 'A', 'Discharge with no follow-up', false, 0),
  ('e0d44c90-1117-5685-b50a-c232f59c123f', '4d242306-21b1-5500-b862-57efbeebd580', 'B', 'Start sodium valproate immediately', false, 1),
  ('43bb7806-21c4-5368-80ca-f3e70a4913fd', '4d242306-21b1-5500-b862-57efbeebd580', 'C', 'Refer to a first seizure clinic to be seen by a specialist within 2 weeks, with driving advice', true, 2),
  ('e35f2f1b-727c-5d2f-a0b9-241593e204c2', '4d242306-21b1-5500-b862-57efbeebd580', 'D', 'Start lamotrigine and review in 6 months', false, 3),
  ('9cb7df12-1afa-5713-ab56-35e07dcab527', '4d242306-21b1-5500-b862-57efbeebd580', 'E', 'Admit for 72 hours of observation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ef72142-e048-5aea-82d9-84aee15adcf2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 62 year old man has had increasing difficulty swallowing and slurred speech for 6 months. His tongue is wasted and fasciculating, and his jaw jerk is normal. What is the SINGLE most likely diagnosis?', 'Bulbar palsy is a lower motor neurone lesion of cranial nerves IX-XII, causing a wasted, fasciculating tongue, nasal speech, an absent or normal jaw jerk and dysphagia. It is often caused by MND (progressive bulbar palsy). Pseudobulbar palsy is an upper motor neurone lesion with a spastic tongue, a brisk jaw jerk and emotional lability.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19d5256d-ca96-5f83-b36c-7fdac0812fc3', '3ef72142-e048-5aea-82d9-84aee15adcf2', 'A', 'Bulbar palsy', true, 0),
  ('2ac5aacb-8fe5-532d-9b8f-f4c0dfa58e01', '3ef72142-e048-5aea-82d9-84aee15adcf2', 'B', 'Stroke', false, 1),
  ('23db34c6-0bd2-5a0f-87b7-07b9d00fbe4a', '3ef72142-e048-5aea-82d9-84aee15adcf2', 'C', 'Parkinson''s disease', false, 2),
  ('4668d448-c8bd-5778-810c-8aee7407a7f1', '3ef72142-e048-5aea-82d9-84aee15adcf2', 'D', 'Myasthenia gravis', false, 3),
  ('f4a49dd1-a2cb-5b7e-87d6-e347b6967c69', '3ef72142-e048-5aea-82d9-84aee15adcf2', 'E', 'Pseudobulbar palsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b4cf4acd-de8b-5afd-a39e-46789d569d79', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 55 year old woman has had severe right-sided throbbing headache, jaw pain on chewing and scalp tenderness for 3 weeks. Her ESR is 76 mm/hour. While waiting for clinic she suddenly loses vision in her right eye. What is the SINGLE most appropriate immediate treatment?', 'Giant cell arteritis with visual loss is an emergency, caused by anterior ischaemic optic neuropathy. BSR recommends IV methylprednisolone (500 mg-1 g daily for 3 days) before oral prednisolone, with same-day ophthalmology review. Vision lost is usually permanent, but treatment protects the other eye. Biopsy or ultrasound should not delay treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('510daeb7-a15c-56b5-a9b6-e2a5da439c1e', 'b4cf4acd-de8b-5afd-a39e-46789d569d79', 'A', 'Aspirin only', false, 0),
  ('8e82e867-7b0f-548c-9283-fc37b1b60822', 'b4cf4acd-de8b-5afd-a39e-46789d569d79', 'B', 'Oral prednisolone 15 mg', false, 1),
  ('8514807d-5c21-5aef-ab45-69fbef01714e', 'b4cf4acd-de8b-5afd-a39e-46789d569d79', 'C', 'Wait for temporal artery biopsy results', false, 2),
  ('ed514c9a-839b-51f7-bd1a-49cf1bdc2f10', 'b4cf4acd-de8b-5afd-a39e-46789d569d79', 'D', 'IV methylprednisolone and urgent ophthalmology review', true, 3),
  ('d7b316b1-4145-5d3e-a5b8-5a0baf849c41', 'b4cf4acd-de8b-5afd-a39e-46789d569d79', 'E', 'Oral ibuprofen', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7a3c563d-7954-563a-af86-a28fb2f6eb36', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 40 year old man has had a progressive involuntary jerky movement disorder, irritability and declining memory for 2 years. His father died aged 50 with similar symptoms and dementia. What is the SINGLE most likely diagnosis?', 'Huntington''s disease is autosomal dominant (CAG repeat in the HTT gene) with anticipation. It presents in mid-adulthood with chorea, psychiatric and behavioural change, and cognitive decline. Diagnosis is by genetic testing, with pre-test counselling. Tetrabenazine can reduce chorea. There is no cure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c191a070-ee4a-52c1-9448-386cac0a3318', '7a3c563d-7954-563a-af86-a28fb2f6eb36', 'A', 'Wilson''s disease', false, 0),
  ('8ab96642-6bec-52f6-9978-d9bf9d270d2c', '7a3c563d-7954-563a-af86-a28fb2f6eb36', 'B', 'Tardive dyskinesia', false, 1),
  ('206a9553-6e67-5a62-9a19-4ec04d15e796', '7a3c563d-7954-563a-af86-a28fb2f6eb36', 'C', 'Huntington''s disease', true, 2),
  ('bd6a9f40-cb5f-5205-9352-5240f016489d', '7a3c563d-7954-563a-af86-a28fb2f6eb36', 'D', 'Sydenham''s chorea', false, 3),
  ('b8b9eae5-fad3-54c5-a539-40efedbf12c1', '7a3c563d-7954-563a-af86-a28fb2f6eb36', 'E', 'Parkinson''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 19 year old man has had tremor, dysarthria and abnormal behaviour for 6 months. His LFTs are abnormal. A slit-lamp examination shows golden-brown rings at the edge of the cornea. What is the SINGLE most likely diagnosis?', 'Wilson''s disease is an autosomal recessive disorder of copper metabolism (ATP7B gene). It causes liver disease, neuropsychiatric features and Kayser-Fleischer rings. Investigations show low serum caeruloplasmin and raised 24-hour urinary copper. Treatment is chelation with penicillamine or trientine, plus zinc. Siblings should be screened.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f3e0fcbb-37b9-54c3-b769-86c3614ae147', 'a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'A', 'Huntington''s disease', false, 0),
  ('7d623b08-19f4-5dec-a215-b3d151708aba', 'a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'B', 'Wilson''s disease', true, 1),
  ('f64bacec-4281-59a8-87ea-ca90ba061ec2', 'a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'C', 'Multiple sclerosis', false, 2),
  ('30c71c01-8d21-58a3-b30b-a2827d42f36c', 'a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'D', 'Alcohol-related liver disease', false, 3),
  ('f7d87fae-22b6-5033-9671-4b03f97b0114', 'a6bbdd08-9f4a-5406-91f3-2c61c78735fd', 'E', 'Haemochromatosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 28 year old man was hit on the head during a fight 6 hours ago. He had no loss of consciousness and has a mild headache. He has vomited twice since the injury. His GCS is 15/15 and examination is normal. According to NICE, what is the SINGLE most appropriate investigation?', 'NICE head injury criteria for CT within 1 hour in adults include GCS under 13 on initial assessment, GCS under 15 at 2 hours, suspected open or depressed skull fracture, signs of basal skull fracture, a post-traumatic seizure, a focal neurological deficit, or more than one episode of vomiting. He has vomited twice, so he needs CT within 1 hour.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('de242783-4cd0-5f93-ab08-13f7bc6d1793', '9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'A', 'CT head within 8 hours', false, 0),
  ('8731ce79-ea41-5fac-96d9-ec042a56a5fe', '9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'B', 'Skull X-ray', false, 1),
  ('c5a17661-3468-5ead-9e6c-f39981e3973c', '9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'C', 'CT head within 1 hour', true, 2),
  ('7d466231-64af-59a1-9ebd-5d6bddacd7f9', '9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'D', 'MRI brain within 24 hours', false, 3),
  ('b216a3a6-2e93-5abf-af40-941de58e40e0', '9ceeeba4-4e83-5c73-81c5-27a0159c2177', 'E', 'No imaging; discharge with advice', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 24 year old woman has sudden onset of headache, vomiting, seizures and reduced vision 5 days after giving birth. She has no history of hypertension. MRI venography shows thrombosis of the superior sagittal sinus. What is the SINGLE most appropriate treatment?', 'Cerebral venous sinus thrombosis presents with headache, seizures, focal deficits and papilloedema. Risk factors include pregnancy, the postpartum period, the COCP, thrombophilia and dehydration. It is diagnosed by MR or CT venography. Anticoagulation with LMWH is first-line, even if there is a venous haemorrhage. Long-term oral anticoagulation then follows.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4e694a3a-0f70-544d-8bd4-2fa0af68eae1', 'f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'A', 'Anticoagulation with low molecular weight heparin', true, 0),
  ('da5d24d3-3fbd-513b-8297-f6f05c9984c1', 'f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'B', 'IV mannitol only', false, 1),
  ('eeecaeef-e2bd-585a-be43-fce0c5bba074', 'f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'C', 'Thrombolysis as first-line', false, 2),
  ('6ca06066-a107-59e3-ac87-b39e1ffb1a23', 'f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'D', 'No treatment', false, 3),
  ('113efca6-2564-5396-b0ff-ce3501fcac8e', 'f583cb67-0ebb-5a84-ae6a-9a5d4fdea6bc', 'E', 'Aspirin only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 32 year old woman has had weakness of both legs for 2 days, a band-like sensation around her chest at the level of her nipples, and urinary retention. She had a viral illness 2 weeks ago. MRI spine shows an inflammatory lesion over several segments of the thoracic cord with no compression. What is the SINGLE most likely diagnosis?', 'Transverse myelitis is inflammation across a segment of the spinal cord, causing bilateral weakness, a sensory level and sphincter disturbance, often after infection. It can be the first presentation of MS or neuromyelitis optica (AQP4 antibodies). Treatment is high-dose IV methylprednisolone. Compression must be excluded with urgent MRI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e348fb17-8626-5763-8653-b99bb9b929af', 'a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'A', 'Guillain-Barré syndrome', false, 0),
  ('1acfa63a-4ffe-5418-92dd-89e2a9183b4a', 'a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'B', 'Spinal cord compression from metastasis', false, 1),
  ('f6843b24-e625-5908-af04-8c4e00f7ddb5', 'a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'C', 'Transverse myelitis', true, 2),
  ('13d6be87-129d-5e10-b439-989ff089b67b', 'a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'D', 'Motor neurone disease', false, 3),
  ('a89da065-21fe-5aa4-a908-8db112dbb513', 'a3d0df69-3268-518f-bde9-b76f18fc2ec8', 'E', 'Cauda equina syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 66 year old man woke with weakness of his left arm and leg and left-sided facial droop. His left arm and leg are weaker than his face. He also has left-sided neglect and a left homonymous hemianopia. Using the Oxford (Bamford) classification, what type of stroke is this?', 'TACS requires all three: unilateral weakness or sensory loss of face, arm and leg; homonymous hemianopia; and higher cortical dysfunction (dysphasia or visuospatial neglect). PACS has two of these. LACS is pure motor, pure sensory, sensorimotor or ataxic hemiparesis without cortical signs. POCS involves cerebellar or brainstem signs, or isolated hemianopia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b0d7b608-0aa3-51e8-9dfc-eaac40aa6ce5', '518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'A', 'Total anterior circulation stroke (TACS)', true, 0),
  ('5bb71b28-1c40-5692-8daa-a8f316733092', '518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'B', 'Transient ischaemic attack', false, 1),
  ('e64a3d39-e7f5-5091-a1b8-49e080ce9c22', '518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'C', 'Posterior circulation stroke (POCS)', false, 2),
  ('cf8bccce-c702-5457-9097-d92ea3ef3892', '518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'D', 'Lacunar stroke (LACS)', false, 3),
  ('43add1b4-6df9-522d-b70d-3ca079c6dd61', '518f094b-ce8f-5fda-ae67-2e9c3e01714c', 'E', 'Partial anterior circulation stroke (PACS)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b02d4eee-a279-5099-a48c-4afba03292c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 70 year old man had an ischaemic stroke 2 weeks ago. He has no atrial fibrillation. Carotid imaging shows 80% stenosis of the symptomatic left internal carotid artery. What is the SINGLE most appropriate management?', 'NICE recommends urgent carotid endarterectomy (within 2 weeks of symptoms) for symptomatic carotid stenosis of 50-99% (NASCET criteria). This is combined with best medical therapy: clopidogrel 75 mg, high-intensity statin and BP control. Asymptomatic stenosis is managed medically in most cases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5a9c2d2-1358-5228-8035-d8daa1d7b262', 'b02d4eee-a279-5099-a48c-4afba03292c2', 'A', 'Carotid stenting in 1 year', false, 0),
  ('332452f2-427b-5875-8524-cb0a3cb18d39', 'b02d4eee-a279-5099-a48c-4afba03292c2', 'B', 'Lifelong warfarin', false, 1),
  ('823469ae-c7eb-5110-b838-53235dbf98ae', 'b02d4eee-a279-5099-a48c-4afba03292c2', 'C', 'No intervention as the stroke has happened', false, 2),
  ('62717a6f-42e8-5917-9f48-5ffd8299d5f0', 'b02d4eee-a279-5099-a48c-4afba03292c2', 'D', 'Repeat carotid imaging in 1 year', false, 3),
  ('7b5208cb-a60a-5147-b2ea-083e216871b0', 'b02d4eee-a279-5099-a48c-4afba03292c2', 'E', 'Refer for carotid endarterectomy within 2 weeks of symptom onset', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('43c309dc-c468-5b24-89c7-88e9c6f17919', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 75 year old woman had an ischaemic stroke 2 weeks ago. A 24-hour ECG now shows paroxysmal atrial fibrillation. Her stroke was moderate with no haemorrhage on imaging. When should anticoagulation be started for secondary prevention?', 'Recent evidence (ELAN, TIMING trials) supports early DOAC initiation after ischaemic stroke with AF, guided by severity, rather than routinely delaying for 2 weeks. Haemorrhage should be excluded on imaging. AF is a major cause of cardioembolic stroke, and anticoagulation markedly reduces recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ca2742e3-7f95-5a14-a7ea-28355d5420ed', '43c309dc-c468-5b24-89c7-88e9c6f17919', 'A', 'Aspirin only lifelong', false, 0),
  ('73aa2c28-423d-5ac4-a83e-fa85ad5ecc05', '43c309dc-c468-5b24-89c7-88e9c6f17919', 'B', 'Never, because of the stroke', false, 1),
  ('194c09b9-8904-5407-82b3-0d350f3a78fe', '43c309dc-c468-5b24-89c7-88e9c6f17919', 'C', 'After 6 months', false, 2),
  ('eeb458b7-e8d7-5321-9d07-0ed89013cb58', '43c309dc-c468-5b24-89c7-88e9c6f17919', 'D', 'Start a DOAC; timing is usually soon after the stroke as guided by severity', true, 3),
  ('d9e4136c-72c0-525b-9e52-dc007045ac7b', '43c309dc-c468-5b24-89c7-88e9c6f17919', 'E', 'Only if she has another stroke', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old man has had pain radiating from his lower back down the back of his right leg to the lateral border of his foot for 3 weeks. His right ankle reflex is absent, and he has weakness of plantarflexion and sensory loss over the lateral foot. Which nerve root is MOST likely affected?', 'S1 radiculopathy (usually from an L5/S1 disc) causes pain to the posterior leg and lateral foot, weak plantarflexion and an absent ankle reflex. L5 affects great toe extension and foot dorsiflexion, with sensory loss over the dorsum of the foot, and no reflex change. L4 affects the knee reflex and medial shin sensation. Most sciatica improves with conservative management.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0ed8194-a150-575e-8857-43b1ef22327e', '48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'A', 'L5', false, 0),
  ('38df79d3-1bf1-5f4e-be90-0fa42748a0e3', '48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'B', 'L4', false, 1),
  ('ef994a0d-85c7-5ce9-8f72-1d44caa796e5', '48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'C', 'S3', false, 2),
  ('e7785e17-c2cf-573a-a58e-c10c74cbc7ff', '48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'D', 'L3', false, 3),
  ('1c742162-81dc-5208-b16f-21b847dbc67d', '48256bc1-0f7b-5421-a989-0d2ee7e098d1', 'E', 'S1', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 58 year old woman has had neck pain and stiffness, clumsy hands and an unsteady gait for 6 months. She has brisk reflexes and up-going plantars in her legs, and a positive Hoffmann''s sign. What is the SINGLE most likely diagnosis?', 'Degenerative cervical myelopathy is cord compression from spondylosis. It causes neck pain, loss of hand dexterity, gait imbalance and upper motor neurone signs (Hoffmann''s sign, hyperreflexia, clonus). It is often missed. Urgent MRI of the cervical spine and referral to spinal surgery are needed, because decompression prevents further progression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d99ecc58-ac53-59aa-9d30-6ce69911e7f5', 'e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'A', 'Carpal tunnel syndrome', false, 0),
  ('efcc9835-73a4-5645-a31f-be47bdb36fe5', 'e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'B', 'Degenerative cervical myelopathy', true, 1),
  ('52462d00-e197-56c4-847c-d25831c5f568', 'e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'C', 'Multiple sclerosis', false, 2),
  ('a4830c54-8b47-5240-90c1-59435b620a47', 'e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'D', 'Motor neurone disease', false, 3),
  ('c54e4f34-e586-522e-8300-eb6a6c41422e', 'e1b453cc-e79b-5cb1-803b-aa2cebb96ac4', 'E', 'Peripheral neuropathy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 52 year old man with alcohol dependence has had a gradually worsening, broad-based, unsteady gait over months. There is no nystagmus or confusion. His heel-shin test is abnormal bilaterally, while finger-nose testing is relatively normal. What is the SINGLE most likely diagnosis?', 'Chronic alcohol use causes degeneration of the anterior superior cerebellar vermis, producing truncal and gait ataxia with relatively spared upper limb coordination. This differs from Wernicke''s encephalopathy, which is acute with confusion and ophthalmoplegia. Management is stopping alcohol and thiamine supplementation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ab533653-f6d7-59bc-b3ba-0a248b82f585', 'fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'A', 'Wernicke''s encephalopathy', false, 0),
  ('512ea43e-b938-5d1f-af87-ea68dfecb122', 'fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'B', 'Parkinson''s disease', false, 1),
  ('a067b86c-db06-5203-b568-726cffa1ed44', 'fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'C', 'Peripheral neuropathy', false, 2),
  ('6f999a53-0306-5b17-a44d-f958793431ab', 'fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'D', 'Normal pressure hydrocephalus', false, 3),
  ('1df43fdd-6f23-5683-804d-d32b27f017f5', 'fbb7ad04-1692-5a77-8b04-9fb02c9cab2f', 'E', 'Alcohol-related cerebellar degeneration (anterior vermis)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4263b701-ed91-5664-b576-1ae387babe2e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 22 year old woman has had progressive weakness of her hip and shoulder muscles over months, with difficulty climbing stairs and combing her hair. She has a violaceous rash around her eyes and raised scaly papules over her knuckles. Her CK is raised. What is the SINGLE most likely diagnosis?', 'Proximal myopathy, a raised CK and skin signs (heliotrope rash, Gottron''s papules) indicate dermatomyositis. Myositis-specific antibodies (such as anti-Jo-1, anti-Mi-2) and muscle biopsy or MRI help confirm it. In adults it is associated with underlying malignancy, so screening is needed. Treatment is corticosteroids and steroid-sparing agents.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c0e9b7f4-12a8-51e8-b133-6b268142ffa0', '4263b701-ed91-5664-b576-1ae387babe2e', 'A', 'Polymyalgia rheumatica', false, 0),
  ('c106f30b-74fb-5bf9-a17f-96a9700f9e64', '4263b701-ed91-5664-b576-1ae387babe2e', 'B', 'Dermatomyositis', true, 1),
  ('e37bb4b5-eb92-52b7-aaa0-cbe48b104fc8', '4263b701-ed91-5664-b576-1ae387babe2e', 'C', 'Hypothyroid myopathy', false, 2),
  ('0c16203a-f663-5717-8a35-726485cda080', '4263b701-ed91-5664-b576-1ae387babe2e', 'D', 'Myasthenia gravis', false, 3),
  ('c60853a7-b9ed-5a32-9a69-1260ce13724f', '4263b701-ed91-5664-b576-1ae387babe2e', 'E', 'Systemic lupus erythematosus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 32 year old woman has had episodes of sudden weakness and loss of muscle tone in her legs triggered by laughter, plus excessive daytime sleepiness with sudden sleep attacks. She has vivid hallucinations as she falls asleep. What is the SINGLE most likely diagnosis?', 'Narcolepsy causes excessive daytime sleepiness, cataplexy (sudden loss of muscle tone triggered by emotion, especially laughter), hypnagogic hallucinations and sleep paralysis. Type 1 narcolepsy is linked to hypocretin (orexin) deficiency. Diagnosis is by polysomnography and a multiple sleep latency test. Treatment includes modafinil, sodium oxybate and pitolisant. Patients must tell the DVLA.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0eb08341-c5a6-5686-918b-fc68be590410', '70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'A', 'Narcolepsy with cataplexy', true, 0),
  ('7d181596-158e-58dd-a498-cee3afcf255e', '70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'B', 'Depression', false, 1),
  ('0d893ac5-eb1f-5849-b4a7-8eaf3e0ad441', '70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'C', 'Syncope', false, 2),
  ('41545272-86b8-59e2-8ae7-410dc8bef536', '70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'D', 'Obstructive sleep apnoea', false, 3),
  ('c70b5a71-ea2c-58ef-ab64-49923452c02a', '70e8149d-acaa-50c2-9a63-1d12c3bff7b0', 'E', 'Epilepsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8b2cd735-8d17-57d0-b5d8-bab684245c69', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old woman has had an uncomfortable urge to move her legs in the evenings, relieved by movement, which disturbs her sleep. She has iron deficiency. What is the SINGLE most appropriate first step?', 'Restless legs syndrome (Willis-Ekbom disease) causes an urge to move the legs, worse at rest and in the evening, and relieved by movement. Secondary causes include iron deficiency, pregnancy, CKD and drugs (antidepressants, antihistamines, antipsychotics). Iron replacement (ferritin target over 75) is first-line if low. Dopamine agonists or gabapentinoids are used for persistent symptoms, with dopamine agonists carrying a risk of augmentation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3f64559a-f400-51e0-bbea-e3c6af1063c7', '8b2cd735-8d17-57d0-b5d8-bab684245c69', 'A', 'Antipsychotic', false, 0),
  ('f68a740a-a240-5fff-89b8-79f82c1ce900', '8b2cd735-8d17-57d0-b5d8-bab684245c69', 'B', 'No treatment', false, 1),
  ('c3601861-8a51-52ea-88ba-4cda53646f9d', '8b2cd735-8d17-57d0-b5d8-bab684245c69', 'C', 'Check and replace iron (ferritin), with sleep hygiene', true, 2),
  ('ae9961e4-a119-515e-8c1b-018338c77c8b', '8b2cd735-8d17-57d0-b5d8-bab684245c69', 'D', 'Start a dopamine agonist immediately', false, 3),
  ('75b4e1c1-e6a5-5936-b468-bf46beb7eda5', '8b2cd735-8d17-57d0-b5d8-bab684245c69', 'E', 'Start a benzodiazepine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d59aa069-48cb-5d1f-88b6-68b09986ecb5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 28 year old woman with epilepsy has had several episodes of shaking lasting 10 minutes, with eyes tightly closed, side-to-side head movements and recall of the events. The shaking stops and starts. Video-EEG shows no epileptic activity during episodes. What is the SINGLE most likely diagnosis?', 'Functional (psychogenic non-epileptic) seizures often have closed eyes, side-to-side head movements, pelvic thrusting, fluctuating long episodes and preserved awareness or recall. Video-EEG is the gold standard. Some patients also have epilepsy. Management is a clear, non-judgemental explanation and psychological therapy, avoiding unnecessary antiepileptics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dc6597e8-63de-5d31-b2a2-951bcc8aa58b', 'd59aa069-48cb-5d1f-88b6-68b09986ecb5', 'A', 'Absence seizures', false, 0),
  ('f080c1a6-01c1-50f3-8c6c-fe6d8383a32a', 'd59aa069-48cb-5d1f-88b6-68b09986ecb5', 'B', 'Frontal lobe epilepsy', false, 1),
  ('51f6912c-15c2-5222-8020-91e49474f396', 'd59aa069-48cb-5d1f-88b6-68b09986ecb5', 'C', 'Functional (dissociative) seizures', true, 2),
  ('4bf3dcf7-71af-53e0-9208-46e59fc30771', 'd59aa069-48cb-5d1f-88b6-68b09986ecb5', 'D', 'Generalised tonic-clonic seizures', false, 3),
  ('82e1191a-5f7d-59e6-b830-75cca30f90ae', 'd59aa069-48cb-5d1f-88b6-68b09986ecb5', 'E', 'Syncope', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5bc5ca2a-7393-5b24-8545-e15759b9d347', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 70 year old man has had a gradual decline in walking, with a wide-based ataxic gait and vibration and proprioception loss in his feet. His Romberg''s test is positive, he has absent ankle reflexes and extensor plantars. His MCV is 112 fL. What is the SINGLE most likely diagnosis?', 'B12 deficiency causes subacute combined degeneration: dorsal column loss (vibration, proprioception, positive Romberg''s), corticospinal tract involvement (extensor plantars) and peripheral neuropathy (absent ankle jerks), often with macrocytosis. Treatment is IM hydroxocobalamin before any folic acid. Nitrous oxide misuse can cause it.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5ce770b0-743a-5090-8cc9-f7da686ca82d', '5bc5ca2a-7393-5b24-8545-e15759b9d347', 'A', 'Cervical myelopathy', false, 0),
  ('25a32a6d-32e5-5d9b-bb72-0347ff8b60c4', '5bc5ca2a-7393-5b24-8545-e15759b9d347', 'B', 'Peripheral neuropathy only', false, 1),
  ('df911100-2732-5af4-8c8e-270a0748dbc4', '5bc5ca2a-7393-5b24-8545-e15759b9d347', 'C', 'Motor neurone disease', false, 2),
  ('a8c2eff1-33bd-5b56-8fe0-259cd66ca519', '5bc5ca2a-7393-5b24-8545-e15759b9d347', 'D', 'Subacute combined degeneration of the spinal cord (vitamin B12 deficiency)', true, 3),
  ('91a6d34c-1c8b-5b43-b352-3df402c1a01e', '5bc5ca2a-7393-5b24-8545-e15759b9d347', 'E', 'Multiple sclerosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f7fe352c-2739-5510-a30a-f2b58291e7f2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 74 year old man has a severe headache of sudden onset and is seen in the Emergency Department. He had no preceding symptoms. His temperature is 37.5°C. He has mild left-sided weakness at power grade 4/5 in both upper and lower limbs. Which is the most likely diagnosis?', 'A sudden-onset severe headache with focal weakness is subarachnoid haemorrhage until proven otherwise. Low-grade fever can occur. Urgent CT head is the first investigation, with lumbar puncture for xanthochromia if the CT is normal, followed by CT angiography.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc82f08f-167a-5a6d-b3d2-a4d79db463bf', 'f7fe352c-2739-5510-a30a-f2b58291e7f2', 'A', 'Benign intracranial hypertension', false, 0),
  ('bb7a54a5-6dee-5287-80b2-f5e752304004', 'f7fe352c-2739-5510-a30a-f2b58291e7f2', 'B', 'Brain tumour', false, 1),
  ('67d1c10a-6c34-5d10-b62f-751f94955e52', 'f7fe352c-2739-5510-a30a-f2b58291e7f2', 'C', 'Encephalitis', false, 2),
  ('6d855b50-38c2-5049-8822-defd34669875', 'f7fe352c-2739-5510-a30a-f2b58291e7f2', 'D', 'Meningitis', false, 3),
  ('8c3465dd-5e5d-53ec-a6c8-2194b963c959', 'f7fe352c-2739-5510-a30a-f2b58291e7f2', 'E', 'Subarachnoid haemorrhage', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e757a984-e418-5ef6-8057-bdf7b657bdbf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 72 year old man has increasing difficulty speaking clearly for last 2 years and is seen by his GP. He has worsening memory and significant changes in his personality and conduct. He has been making inappropriate sexual remarks whilst in the supermarket. Physical examination is normal. Which is the most likely diagnosis?', 'Early personality change, disinhibition (inappropriate sexual remarks) and language difficulty, with relatively later memory decline, are typical of frontotemporal dementia. It often presents before age 65. Alzheimer''s disease usually starts with short-term memory loss.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f09540a6-22ad-51ad-9992-4e77a525f97e', 'e757a984-e418-5ef6-8057-bdf7b657bdbf', 'A', 'Alzheimer’s disease', false, 0),
  ('cec5fac5-4858-55ac-8aa4-38515e3f01fc', 'e757a984-e418-5ef6-8057-bdf7b657bdbf', 'B', 'Frontal-temporal dementia', true, 1),
  ('135c0e04-319e-580d-92da-c64ba5312e59', 'e757a984-e418-5ef6-8057-bdf7b657bdbf', 'C', 'Huntington’s disease', false, 2),
  ('4d5885ef-cb46-596a-9e10-9808b25a178d', 'e757a984-e418-5ef6-8057-bdf7b657bdbf', 'D', 'Lewy body dementia', false, 3),
  ('86f6d8cc-b378-5640-8ae1-68084156c77b', 'e757a984-e418-5ef6-8057-bdf7b657bdbf', 'E', 'Multi-infarct dementia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14955cfd-e960-5224-b7cf-51da9d3b223f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 28 year old woman has intermittent headaches for 6 months and is seen in the neurology clinic. She has a dull ache lasting 1 hour on both sides of her head with tightness in her neck muscles and pressure behind her eyes. She does not take any medication. She works as a solicitor. Her temperature is 36.5°C, pulse rate 82 bpm and BP 122/70 mmHg. Neurological examination is normal. Investigations: CT scan of brain: normal Which is the most appropriate initial treatment?', 'Bilateral pressing or tightening headache without migraine features, with a normal examination, is tension-type headache. NICE recommends aspirin, paracetamol or an NSAID for acute treatment, and the GMC answer is paracetamol. Triptans are for migraine. Medication overuse headache should be avoided by limiting analgesic days.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('66c0beb7-98ff-5e50-a41a-fdb786a72a0f', '14955cfd-e960-5224-b7cf-51da9d3b223f', 'A', 'Aspirin', false, 0),
  ('82ad9ea2-a68f-579f-9a04-1e21a1bb8711', '14955cfd-e960-5224-b7cf-51da9d3b223f', 'B', 'Paracetamol', true, 1),
  ('5f7d17df-7853-5136-bb42-349f07f51cb0', '14955cfd-e960-5224-b7cf-51da9d3b223f', 'C', 'Prednisolone', false, 2),
  ('0897fe16-2fd0-5699-b69b-0a4a8877699b', '14955cfd-e960-5224-b7cf-51da9d3b223f', 'D', 'Sumatriptan', false, 3),
  ('5e39078b-702d-5a9d-b2e2-f36bbfcabe69', '14955cfd-e960-5224-b7cf-51da9d3b223f', 'E', 'Topiramate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cb326aaa-09fc-522a-b038-5589271ac255', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman presents to the Emergency Department with sudden left iliac fossa pain and pain in the tip of her left shoulder. Her last menstrual period was 7 weeks ago. She is pale and sweaty, her heart rate is 128 beats/minute and blood pressure is 84/50 mmHg. A urine pregnancy test is positive. Resuscitation has been started. What is the SINGLE most appropriate definitive management?', 'A positive pregnancy test with abdominal pain, shoulder tip pain (diaphragmatic irritation from blood) and shock indicates a ruptured ectopic pregnancy. Alongside resuscitation and a major haemorrhage call, she needs emergency surgery, usually salpingectomy. Methotrexate and expectant management are only for stable patients with an unruptured ectopic, low hCG and no significant pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f6edbae-56b9-5828-bb8c-9c99a22b9063', 'cb326aaa-09fc-522a-b038-5589271ac255', 'A', 'Emergency surgical management (laparoscopy or laparotomy)', true, 0),
  ('67e3fc3d-7b68-5491-b0b4-ed76eec02f75', 'cb326aaa-09fc-522a-b038-5589271ac255', 'B', 'Serial serum hCG measurements over 48 hours', false, 1),
  ('08184938-2ef5-5fd8-9495-b486bcb55ed4', 'cb326aaa-09fc-522a-b038-5589271ac255', 'C', 'Expectant management', false, 2),
  ('24ea7371-4a5b-5b2c-98f6-946e990f0df1', 'cb326aaa-09fc-522a-b038-5589271ac255', 'D', 'Repeat transvaginal ultrasound in 48 hours', false, 3),
  ('3b89972f-3c8b-56d9-8687-3a28165d0a3e', 'cb326aaa-09fc-522a-b038-5589271ac255', 'E', 'IM methotrexate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 37 year old woman attends her booking appointment at 10 weeks in her first pregnancy. Her BMI is 36 kg/m2. Her blood pressure is 118/74 mmHg and urinalysis is normal. She has no history of hypertension, kidney disease or autoimmune disease. What is the SINGLE most appropriate advice to reduce her risk of pre-eclampsia?', 'NICE recommends aspirin 75-150 mg daily from 12 weeks until birth for women with one high-risk factor (for example hypertensive disease in a previous pregnancy, CKD, autoimmune disease, diabetes or chronic hypertension) or two or more moderate-risk factors. Her moderate-risk factors are first pregnancy and BMI of 35 or more, so she qualifies. Other moderate-risk factors are age 40 or over, a pregnancy interval over 10 years and a family history of pre-eclampsia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('50388510-d944-52c2-9be8-35699451f799', 'acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'A', 'Take calcium supplements only from 20 weeks', false, 0),
  ('c854fd77-72c7-5e53-89c4-909ff8d54c21', 'acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'B', 'Take aspirin 75-150 mg daily from 12 weeks until birth', true, 1),
  ('a15f0827-e7db-5714-a5fd-362430b6fb47', 'acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'C', 'No medication is needed; routine antenatal care', false, 2),
  ('bb4ae7db-de99-5b60-9f9f-c159ab52d9e2', 'acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'D', 'Take labetalol from 12 weeks until birth', false, 3),
  ('3e444a80-6acb-5dde-92fe-be3987148e89', 'acddc9b8-854e-59ec-963a-ee15a26fd6fe', 'E', 'Take aspirin 75-150 mg daily from 28 weeks until birth', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman who is 36 weeks pregnant is brought to the maternity unit after a generalised tonic-clonic seizure at home. She has no history of epilepsy. On arrival she is drowsy, her blood pressure is 172/114 mmHg and urine dipstick shows 3+ protein. The seizure has now stopped. What is the SINGLE most appropriate drug treatment to prevent further seizures?', 'A seizure in a pregnant woman with hypertension and proteinuria is eclampsia. Magnesium sulfate is the treatment of choice for treating and preventing further eclamptic seizures: a 4 g IV loading dose over 5-15 minutes, then 1 g/hour for 24 hours. Severe hypertension also needs treating (for example with IV labetalol or oral nifedipine), and delivery is planned once she is stable. Check reflexes and respiratory rate for magnesium toxicity; the antidote is calcium gluconate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8fde622d-9d39-5246-8ccb-f46b8ede7bcd', 'd5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'A', 'IV lorazepam', false, 0),
  ('a953720a-9654-519c-ac4e-d9f478c5ceaf', 'd5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'B', 'IV phenytoin', false, 1),
  ('de0a242a-9368-5704-8f8b-8b22a9967565', 'd5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'C', 'IV levetiracetam', false, 2),
  ('7173e88c-5805-5152-8b6c-111e48c2281d', 'd5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'D', 'IV magnesium sulfate', true, 3),
  ('4ec99365-6a87-51f7-86c5-c3be02b106a9', 'd5879c01-5f1f-538a-a1c0-1b9fd3bdcc16', 'E', 'Oral nifedipine alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman who is 32 weeks pregnant presents with sudden painless bright red vaginal bleeding of about 200 mL. Her 20-week anomaly scan reported a low-lying placenta. Her uterus is soft and non-tender, and the fetus is in a transverse lie with a normal heart rate. What is the SINGLE most important thing to AVOID?', 'Painless bleeding with a soft uterus, an abnormal lie and a known low-lying placenta suggests placenta praevia. A digital vaginal examination must never be done until praevia is excluded, because it can provoke massive haemorrhage. Management is admission, IV access, crossmatching, anti-D if rhesus negative, steroids if delivery before 35 weeks is likely, and planned caesarean section.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3876f581-93f2-5857-a9c4-1dc9a23360b7', '68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'A', 'Digital vaginal examination', true, 0),
  ('b51151cb-bc52-54ed-ae35-1b8413dd4047', '68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'B', 'Ultrasound scan', false, 1),
  ('5110528e-5750-5d8d-822b-06a0acfb1f62', '68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'C', 'Corticosteroids for fetal lung maturity', false, 2),
  ('f678e78e-1758-5413-a1ef-7e3405d4384d', '68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'D', 'Group and save and crossmatch', false, 3),
  ('5b97e191-9540-5151-8ecd-b5d261561ccf', '68d05c17-9f81-5000-9db3-6a9a5cb678e7', 'E', 'Anti-D immunoglobulin if she is rhesus negative', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e72e9722-5d81-5738-8cdb-e690ab934a26', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman who is 34 weeks pregnant presents with sudden severe constant abdominal pain and a small amount of dark vaginal bleeding. She smokes and has pre-eclampsia. Her uterus is tense and woody-hard, and she is tachycardic. CTG shows fetal bradycardia. What is the SINGLE most likely diagnosis?', 'Painful bleeding with a tense, ''woody'' uterus and fetal distress is placental abruption, where the placenta separates before delivery. Risk factors include pre-eclampsia, smoking, cocaine, trauma and previous abruption. Visible bleeding may underestimate blood loss because of concealed haemorrhage. It is an obstetric emergency: resuscitate, monitor for DIC and deliver urgently if the fetus is distressed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b6fa3baa-ec0f-582a-a0e6-e5a200d461b7', 'e72e9722-5d81-5738-8cdb-e690ab934a26', 'A', 'Placenta praevia', false, 0),
  ('95f39027-fe38-5e8f-9004-4ae38dc2e648', 'e72e9722-5d81-5738-8cdb-e690ab934a26', 'B', 'Placental abruption', true, 1),
  ('62387d78-2e5e-5a7a-8b41-5c6162d8dcb9', 'e72e9722-5d81-5738-8cdb-e690ab934a26', 'C', 'Vasa praevia', false, 2),
  ('7c85eb85-539a-5200-a992-833aa62141e3', 'e72e9722-5d81-5738-8cdb-e690ab934a26', 'D', 'Labour', false, 3),
  ('696c66c8-861a-5064-87e3-ff200145637a', 'e72e9722-5d81-5738-8cdb-e690ab934a26', 'E', 'Uterine rupture in a primigravida', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 33 year old woman of South Asian family origin is 26 weeks pregnant. Her BMI is 33 kg/m2 and her previous baby weighed 4.6 kg. She has a 75 g oral glucose tolerance test with a fasting glucose of 5.9 mmol/L and a 2-hour glucose of 8.1 mmol/L. What is the SINGLE most likely diagnosis?', 'NICE diagnoses gestational diabetes with a fasting glucose of 5.6 mmol/L or above, or a 2-hour glucose of 7.8 mmol/L or above (''5678''). She meets both. Risk factors include BMI over 30, previous macrosomia (4.5 kg or more), previous GDM, a family history and certain ethnic backgrounds. A fasting glucose under 7 mmol/L is first managed with diet and exercise for 1-2 weeks, then metformin, then insulin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7af15de7-d2d1-5f5c-af96-f83b196bf7fc', 'c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'A', 'Maturity-onset diabetes of the young', false, 0),
  ('1c485c23-79b6-5067-a378-d80f9c8f76f3', 'c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'B', 'Impaired fasting glucose only, no action needed', false, 1),
  ('e636d6ab-412a-573d-8fe6-fb38012ae0ea', 'c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'C', 'Normal glucose tolerance', false, 2),
  ('2befaa68-aabc-56a4-ab8f-57223bcf7627', 'c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'D', 'Pre-existing type 1 diabetes', false, 3),
  ('8c7cbc8e-6021-5f23-b6fc-38135a26ac43', 'c0c02daa-546a-54a8-bf1c-11aaa55d82b6', 'E', 'Gestational diabetes', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 24 year old woman has irregular periods every 2-3 months since menarche, acne and excess hair on her upper lip and chin. Her BMI is 31 kg/m2. Her testosterone is mildly raised and pregnancy test is negative. A pelvic ultrasound shows 22 follicles in each ovary. She does not currently want to conceive. What is the SINGLE most likely diagnosis?', 'PCOS is diagnosed with the Rotterdam criteria (2 of 3): oligo-ovulation or anovulation, clinical or biochemical hyperandrogenism, and polycystic ovaries on ultrasound. Other causes of hyperandrogenism should be excluded; a very high testosterone or rapid virilisation suggests a tumour. Management includes weight loss, the COCP to regulate cycles and protect the endometrium, and screening for diabetes and cardiovascular risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ce533469-e26b-5cc0-926e-683fe11f82ae', '6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'A', 'Cushing''s syndrome', false, 0),
  ('3307ad16-ebd7-53d5-8a9b-c317e81750a2', '6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'B', 'Polycystic ovary syndrome', true, 1),
  ('e19bf8ae-167e-514b-9d88-aa6d6abe2ad1', '6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'C', 'Premature ovarian insufficiency', false, 2),
  ('4678e6ea-08b0-551c-b761-f0864adc3ec6', '6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'D', 'Androgen-secreting ovarian tumour', false, 3),
  ('e8fc0b8f-2e64-5d4c-9675-a393b9ea7c5a', '6a257e58-12bb-57bb-acac-bf52ae61a5f9', 'E', 'Congenital adrenal hyperplasia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a72772c-628b-564a-ad52-9ef6272b1117', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 29 year old woman has 2 years of severe pelvic pain that starts a few days before her period, deep pain during intercourse and pain on opening her bowels during menstruation. She has been trying to conceive for 18 months. Pelvic examination shows tender uterosacral ligaments and a fixed retroverted uterus. What is the SINGLE most likely diagnosis?', 'Cyclical pelvic pain, dysmenorrhoea, deep dyspareunia, dyschezia and subfertility with a fixed retroverted uterus and uterosacral nodularity are typical of endometriosis. Transvaginal ultrasound may show endometriomas, but laparoscopy is the gold standard for diagnosis. Treatment includes analgesia, hormonal treatment (COCP or progestogens) and surgery, which is preferred when fertility is the priority, because hormonal treatment prevents conception.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4efd10fd-3734-5866-8b32-498f3e726c89', '2a72772c-628b-564a-ad52-9ef6272b1117', 'A', 'Irritable bowel syndrome', false, 0),
  ('7b5b91d6-5228-59ec-8fa7-67d6d65998b9', '2a72772c-628b-564a-ad52-9ef6272b1117', 'B', 'Fibroids', false, 1),
  ('7963e9fb-ac64-5218-9936-46732d962d9f', '2a72772c-628b-564a-ad52-9ef6272b1117', 'C', 'Adenomyosis', false, 2),
  ('a49521a9-9afc-5283-b045-fc6d0c49cf8c', '2a72772c-628b-564a-ad52-9ef6272b1117', 'D', 'Endometriosis', true, 3),
  ('58f788b5-1da0-5451-90d4-2662fae4e40e', '2a72772c-628b-564a-ad52-9ef6272b1117', 'E', 'Pelvic inflammatory disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman attends for her routine cervical screening. Her result shows high-risk HPV positive with normal cytology. Her previous screen 5 years ago was HPV negative. What is the SINGLE most appropriate next step?', 'In the NHS Cervical Screening Programme, samples are first tested for high-risk HPV. If HPV is positive but cytology is normal, the test is repeated in 12 months. If HPV is still positive with normal cytology at 24 months, she is referred for colposcopy. If HPV is positive with abnormal cytology, she goes straight to colposcopy. HPV negative returns to routine recall.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2d4bbca2-bfe3-537d-be79-accc922663b8', 'ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'A', 'Refer for colposcopy within 2 weeks', false, 0),
  ('04f23215-384d-52c0-8eba-021caf220b50', 'ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'B', 'Total hysterectomy', false, 1),
  ('e837ad85-eabb-5d0e-8797-52f7db24073e', 'ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'C', 'Return to routine recall in 5 years', false, 2),
  ('15e2af58-c40b-59f1-8450-0fbca4e7bd81', 'ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'D', 'Return to routine recall in 3 years', false, 3),
  ('a804852d-0034-5828-8f69-f48bcaef0848', 'ca99517d-71b6-5cb1-b1aa-36cfb191f745', 'E', 'Repeat HPV test in 12 months', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 23 year old woman presents with sudden-onset severe right iliac fossa pain and vomiting that started during exercise. Pregnancy test is negative. She has a tender mass in the right adnexa. Ultrasound shows a 7 cm right ovarian cyst with reduced Doppler blood flow and a ''whirlpool sign''. What is the SINGLE most appropriate management?', 'Sudden unilateral pain and vomiting with an adnexal mass and reduced blood flow suggests ovarian torsion, a surgical emergency. A cyst over 5 cm is a risk factor. Prompt laparoscopic detorsion (with cystectomy if needed) aims to preserve the ovary, which is important in young women. A normal Doppler does not exclude torsion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e7b9fd04-5878-578b-981a-3a768b5e4040', 'b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'A', 'Urgent laparoscopy to untwist the ovary', true, 0),
  ('fbf82b6f-b4db-5662-a03b-40fe7cd0e910', 'b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'B', 'Repeat ultrasound in 6 weeks', false, 1),
  ('acdd77aa-b796-58c8-a972-c5a9dafa9a0e', 'b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'C', 'IM methotrexate', false, 2),
  ('f318e40e-b8a0-5a8f-8712-94448c96d026', 'b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'D', 'IV antibiotics', false, 3),
  ('12c49db1-1965-5dd5-9267-427f457364b0', 'b9cdf198-f1c2-5fad-98dd-2c4cf81bf22d', 'E', 'Oral analgesia and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('76081560-af25-5576-baa6-b7c69a6c85fc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 26 year old woman had unprotected sex 4 days (96 hours) ago. Her last menstrual period started 14 days ago and her cycle is regular at 28 days. She is not on contraception and has no medical problems. What is the SINGLE most effective method of emergency contraception?', 'The copper IUD is the most effective emergency contraception (failure rate under 0.1%). It can be inserted up to 5 days after unprotected sex, or up to 5 days after the earliest expected ovulation. Levonorgestrel is licensed up to 72 hours and ulipristal up to 120 hours, but both are less effective, especially around ovulation. The copper IUD can also be kept as ongoing contraception. STI testing should be offered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04a9f88e-ef3e-50c6-85de-d623b71db6d8', '76081560-af25-5576-baa6-b7c69a6c85fc', 'A', 'Copper intrauterine device', true, 0),
  ('4389b8af-68ac-5906-8a40-0fdd667f738a', '76081560-af25-5576-baa6-b7c69a6c85fc', 'B', 'Levonorgestrel 1.5 mg orally', false, 1),
  ('7d3d5372-caa8-5c9c-a8a4-1d2de15036fa', '76081560-af25-5576-baa6-b7c69a6c85fc', 'C', 'Start the COCP today', false, 2),
  ('3e8d1bae-3f64-565b-a757-40ca4218e4ec', '76081560-af25-5576-baa6-b7c69a6c85fc', 'D', 'No emergency contraception is effective after 72 hours', false, 3),
  ('68b7cda6-0a95-58fe-94f9-ce1a743be968', '76081560-af25-5576-baa6-b7c69a6c85fc', 'E', 'Ulipristal acetate 30 mg orally', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('90b10728-d703-5fae-af26-10ac4468e959', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 52 year old woman has 9 months of hot flushes, night sweats and mood changes affecting her work. Her last period was 14 months ago. She has an intact uterus and no history of breast cancer, VTE or liver disease. She wants treatment for her symptoms. What is the SINGLE most appropriate treatment?', 'Vasomotor symptoms are an indication for HRT. A woman with a uterus needs a progestogen with oestrogen to protect the endometrium from hyperplasia and cancer. She is more than 12 months after her last period (postmenopausal), so continuous combined HRT is appropriate. Sequential (cyclical) HRT is used in the perimenopause or within 12 months of the last period. Transdermal oestrogen carries no increased VTE risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('33c274cd-3bf1-5b85-a5c7-70c385ebc51e', '90b10728-d703-5fae-af26-10ac4468e959', 'A', 'Combined continuous HRT (oestrogen and progestogen)', true, 0),
  ('80afb10d-6bbe-5c4b-90d6-cb66752316b6', '90b10728-d703-5fae-af26-10ac4468e959', 'B', 'Testosterone gel alone', false, 1),
  ('7702dfc4-c081-58e7-9ad6-1b73a1d1fb7f', '90b10728-d703-5fae-af26-10ac4468e959', 'C', 'Combined oral contraceptive pill', false, 2),
  ('3ee35ca6-ec5f-54d7-8264-19480fda66cd', '90b10728-d703-5fae-af26-10ac4468e959', 'D', 'Oestrogen-only HRT', false, 3),
  ('a5c6a9ab-60c1-5f2a-967f-33d1ccf5e4a0', '90b10728-d703-5fae-af26-10ac4468e959', 'E', 'Cyclical (sequential) combined HRT', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman who is rhesus D negative is 30 weeks pregnant. She falls onto her abdomen from a step. She has no vaginal bleeding or abdominal pain and fetal movements are normal. She received routine antenatal anti-D prophylaxis at 28 weeks. What is the SINGLE most appropriate action regarding anti-D?', 'Abdominal trauma is a potentially sensitising event after 20 weeks, so a rhesus negative woman needs anti-D within 72 hours. This applies even if she has had routine prophylaxis. A Kleihauer test measures the fetomaternal haemorrhage to decide whether more anti-D is needed. Other sensitising events include antepartum haemorrhage, external cephalic version, amniocentesis and miscarriage after 12 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('295c8b5c-8f14-55a2-a933-86b719d5c738', 'a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'A', 'No anti-D needed as she had prophylaxis at 28 weeks', false, 0),
  ('d27ec5c1-25a8-5b50-a871-5852a11ed6fa', 'a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'B', 'Give anti-D only if she develops bleeding', false, 1),
  ('b83e890e-540e-543c-a6d4-d6818f29e491', 'a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'C', 'Give anti-D only after delivery', false, 2),
  ('b1b0936a-2517-5fd6-8d51-492dba71660d', 'a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'D', 'Give anti-D immunoglobulin within 72 hours and perform a Kleihauer test', true, 3),
  ('7f834a04-9eae-5464-bd87-63a5cceddd2e', 'a1f60ec8-b45f-5214-af93-7dc821b7bbb9', 'E', 'Check her partner''s blood group before deciding', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 61 year old woman presents with one episode of vaginal bleeding. Her last period was 9 years ago and she does not take HRT. Her BMI is 36 kg/m2 and she has type 2 diabetes. Speculum examination shows a normal cervix. What is the SINGLE most appropriate next step?', 'Postmenopausal bleeding (more than 12 months after the last period) in women aged 55 and over needs a suspected cancer referral for endometrial cancer. Obesity, diabetes, nulliparity and unopposed oestrogen are risk factors. A transvaginal ultrasound measuring endometrial thickness is first-line; a thickness of 4 mm or more needs hysteroscopy and biopsy. CA-125 is used for suspected ovarian cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c3b88a6-4159-544e-8add-5854f99254b6', '4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'A', 'Reassure; it is likely atrophic vaginitis', false, 0),
  ('04b87b8a-8688-56dc-b222-7445e75d4ad1', '4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'B', 'Repeat cervical screening only', false, 1),
  ('b68cfe17-6b21-5774-b746-21bf71d547a0', '4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'C', 'Suspected cancer pathway (two-week wait) referral for transvaginal ultrasound', true, 2),
  ('6975182d-1b15-520b-9507-917a7a5e79d6', '4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'D', 'Check CA-125', false, 3),
  ('c54ce271-defb-5437-b243-76fcfcb3529a', '4ab8b237-4abe-55e9-86cc-e4a07a641aef', 'E', 'Prescribe vaginal oestrogen and review in 3 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('39236bf1-c5e9-5283-be18-43dee98f62a6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 57 year old woman has 3 months of persistent bloating, feeling full quickly and needing to pass urine more often. She has no change in bowel habit. Examination shows mild abdominal distension with no palpable mass. What is the SINGLE most appropriate first investigation in primary care?', 'NICE advises testing CA-125 in women, especially those aged 50 and over, with persistent or frequent bloating, early satiety, pelvic or abdominal pain, or urinary urgency or frequency. If CA-125 is 35 IU/mL or more, arrange a pelvic and abdominal ultrasound, and refer urgently if it suggests ovarian cancer. New IBS symptoms in women over 50 should prompt consideration of ovarian cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('731851f8-11aa-5a7e-88c9-c2ccc8e45257', '39236bf1-c5e9-5283-be18-43dee98f62a6', 'A', 'Faecal immunochemical test only', false, 0),
  ('ff002cea-4918-5668-8ca7-f6f530d88d4d', '39236bf1-c5e9-5283-be18-43dee98f62a6', 'B', 'Pelvic MRI', false, 1),
  ('cac782c3-981d-5b2a-a31c-c18fd8abc091', '39236bf1-c5e9-5283-be18-43dee98f62a6', 'C', 'Colonoscopy', false, 2),
  ('65502b50-a719-54c2-ae2c-32d2393998d2', '39236bf1-c5e9-5283-be18-43dee98f62a6', 'D', 'Reassure and diagnose irritable bowel syndrome', false, 3),
  ('14e6759e-423f-550a-aa23-671bfa67d5e8', '39236bf1-c5e9-5283-be18-43dee98f62a6', 'E', 'Serum CA-125', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 31 year old woman who is 8 weeks pregnant presents with vaginal bleeding and cramping lower abdominal pain. On speculum examination the cervical os is open and products of conception are seen. She is haemodynamically stable. What is the SINGLE most likely diagnosis?', 'Bleeding with an open cervical os means an inevitable (or incomplete) miscarriage. In a threatened miscarriage the os is closed and the pregnancy is still viable. In a complete miscarriage the os is closed and the uterus is empty. A missed miscarriage is a non-viable pregnancy found on scan, often without bleeding. Options for management are expectant, medical (misoprostol) or surgical.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('67a1c1bb-a805-5985-90ee-e0ba773f5d48', 'fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'A', 'Complete miscarriage', false, 0),
  ('ddbd74ab-7cec-5093-9dd9-13b03e8b1982', 'fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'B', 'Missed miscarriage', false, 1),
  ('0b582268-e036-5f21-a387-74a55aad68fc', 'fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'C', 'Inevitable miscarriage', true, 2),
  ('99116d5a-d4b3-5fbe-a7c5-530fba68c261', 'fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'D', 'Ectopic pregnancy', false, 3),
  ('40906d08-7227-5333-bb6b-c5a4af151514', 'fbe8819c-0061-53f8-9e61-0abf7e95cdb1', 'E', 'Threatened miscarriage', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4c1ef994-700c-5b93-a174-0cf6138e4e79', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 26 year old woman has nausea and vomiting at 9 weeks of pregnancy. She cannot keep fluids down, has lost 6% of her body weight and has 3+ ketones in her urine. What is the SINGLE most appropriate management?', 'Hyperemesis gravidarum is persistent vomiting with more than 5% weight loss, dehydration and electrolyte imbalance. When she cannot tolerate oral fluids or has ketonuria, she needs admission or ambulatory care for IV fluids (0.9% saline with potassium), antiemetics and thiamine to prevent Wernicke''s. LMWH is considered for VTE prophylaxis. A scan to check for molar or multiple pregnancy is advised.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ea5f8fd3-65d9-5b3a-b23f-ad868b530cb6', '4c1ef994-700c-5b93-a174-0cf6138e4e79', 'A', 'Advise ginger and small frequent meals only', false, 0),
  ('67756924-6e26-540b-9be7-66b097607a98', '4c1ef994-700c-5b93-a174-0cf6138e4e79', 'B', 'Termination of pregnancy', false, 1),
  ('1a80a580-aa65-5b95-9c78-c51b2104d39e', '4c1ef994-700c-5b93-a174-0cf6138e4e79', 'C', 'Oral metoclopramide at home for 3 months', false, 2),
  ('b7fb7d41-b422-57c9-ad4a-cf94aa6c4d9e', '4c1ef994-700c-5b93-a174-0cf6138e4e79', 'D', 'Oral ondansetron and discharge without fluids', false, 3),
  ('3101adbf-7eb7-59c8-8e34-bc74184dfbf1', '4c1ef994-700c-5b93-a174-0cf6138e4e79', 'E', 'Admit for IV fluids, antiemetics (such as cyclizine) and thiamine', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0e524616-10cb-5954-83de-a30feeae248a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 24 year old woman has had vaginal bleeding at 10 weeks of pregnancy. Her uterus is larger than dates and her serum hCG is very high. Ultrasound shows a ''snowstorm'' appearance with no fetal parts. What is the SINGLE most likely diagnosis?', 'A complete mole (46XX, all paternal DNA) presents with bleeding, a uterus large for dates, very high hCG, hyperemesis and sometimes early pre-eclampsia or hyperthyroidism. Ultrasound shows a snowstorm pattern. Management is suction evacuation and registration with a trophoblastic screening centre for hCG monitoring, because of the risk of gestational trophoblastic neoplasia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
