  ('14c7ee11-1500-58eb-be6d-8c30fb65bc28', '0e524616-10cb-5954-83de-a30feeae248a', 'A', 'Twin pregnancy', false, 0),
  ('8547069b-dacc-5b47-936a-51380b9b8782', '0e524616-10cb-5954-83de-a30feeae248a', 'B', 'Choriocarcinoma', false, 1),
  ('096a94a3-de97-50d6-a8ff-643b8172db1b', '0e524616-10cb-5954-83de-a30feeae248a', 'C', 'Missed miscarriage', false, 2),
  ('06872177-4d21-57ea-9e48-83fa8234df42', '0e524616-10cb-5954-83de-a30feeae248a', 'D', 'Ectopic pregnancy', false, 3),
  ('6809abaa-334b-5177-89f9-7b482ef1891d', '0e524616-10cb-5954-83de-a30feeae248a', 'E', 'Complete hydatidiform mole', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f3f2659-3404-5de0-a2f8-4af897beb425', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 31 year old woman who is 7 weeks pregnant has mild left iliac fossa pain and light spotting. She is haemodynamically stable. Transvaginal ultrasound shows no intrauterine pregnancy and a 25 mm left adnexal mass. Serum hCG is 1,200 IU/L. She has no fetal heartbeat and wants to avoid surgery. What is the SINGLE most appropriate management?', 'NICE offers methotrexate for a stable ectopic pregnancy with no significant pain, an unruptured adnexal mass under 35 mm, no visible heartbeat, hCG under 1,500 IU/L and the ability to attend follow-up. Pregnancy must be avoided for 3 months afterwards because methotrexate is teratogenic. Surgery is needed for an hCG of 5,000 or more, a heartbeat, significant pain or rupture.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('31f2831c-89df-5f7a-804f-bf64f4d14eee', '9f3f2659-3404-5de0-a2f8-4af897beb425', 'A', 'IM methotrexate with hCG monitoring', true, 0),
  ('41c87cc0-df68-5c56-9954-2d9b536cb3ba', '9f3f2659-3404-5de0-a2f8-4af897beb425', 'B', 'Expectant management without follow-up', false, 1),
  ('9729cf41-f5a3-5736-a635-84fdba09bf82', '9f3f2659-3404-5de0-a2f8-4af897beb425', 'C', 'Discharge and repeat scan in 6 weeks', false, 2),
  ('ed8f9d92-b492-562d-9163-23a001ebc766', '9f3f2659-3404-5de0-a2f8-4af897beb425', 'D', 'Oral mifepristone', false, 3),
  ('74839e15-8c80-5792-9477-18297b1ee16b', '9f3f2659-3404-5de0-a2f8-4af897beb425', 'E', 'Emergency laparoscopic salpingectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman who is 6 weeks pregnant has light vaginal bleeding without pain. Her last period was certain. Transvaginal ultrasound shows a 15 mm gestational sac without a yolk sac or fetal pole. What is the SINGLE most appropriate management?', 'Miscarriage is diagnosed on transvaginal ultrasound when the mean gestational sac diameter is 25 mm or more with no embryo, or the crown-rump length is 7 mm or more without a heartbeat. Below these thresholds, the scan is repeated after 7-14 days to avoid wrongly ending a viable pregnancy. A pregnancy of uncertain viability needs a second scan.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bd1283a0-55e4-530b-ab9c-58ebd208677a', '18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'A', 'Diagnose miscarriage and offer surgical evacuation', false, 0),
  ('10bec1d4-6289-5fa1-9127-be08c4d5905b', '18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'B', 'Start methotrexate', false, 1),
  ('0faacd54-a851-5d4e-ab5a-ab192643a139', '18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'C', 'Repeat transvaginal ultrasound in 7-14 days', true, 2),
  ('1fa6a396-3e41-5c9c-a057-68803c199173', '18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'D', 'Laparoscopy', false, 3),
  ('2ab4e3e4-fdeb-5e85-9db0-ab5699a11aa5', '18208cf0-dde4-544e-83ae-efdbf2b3c4dd', 'E', 'Reassure and discharge without follow-up', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3a7124b-31d1-53d2-b313-1b3281b5b966', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman has had three consecutive first-trimester miscarriages. Which investigation is MOST appropriate to look for a treatable cause?', 'Recurrent miscarriage (3 or more consecutive losses) should be investigated with antiphospholipid antibodies, cytogenetic testing of pregnancy tissue (with parental karyotyping if abnormal) and pelvic ultrasound for uterine anomalies. Antiphospholipid syndrome is treated in later pregnancies with low-dose aspirin plus prophylactic LMWH, which improves live birth rates.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('58d72610-56a3-504c-927e-85364e587b0f', 'a3a7124b-31d1-53d2-b313-1b3281b5b966', 'A', 'Serum progesterone', false, 0),
  ('b61455de-ea83-5265-9aa3-06d6c85dd29f', 'a3a7124b-31d1-53d2-b313-1b3281b5b966', 'B', 'Testosterone level', false, 1),
  ('b4630e09-8429-5a72-8450-e04c9ed7f65b', 'a3a7124b-31d1-53d2-b313-1b3281b5b966', 'C', 'Hysterosalpingogram', false, 2),
  ('ca3ad334-101d-5a17-966e-0688ce73f34c', 'a3a7124b-31d1-53d2-b313-1b3281b5b966', 'D', 'Thyroid ultrasound', false, 3),
  ('d29b4459-cde2-5f41-97c2-476c05e2ea6a', 'a3a7124b-31d1-53d2-b313-1b3281b5b966', 'E', 'Antiphospholipid antibodies (lupus anticoagulant and anticardiolipin antibodies)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('70d714a7-e884-5575-9215-60fee84a23a5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 39 year old woman who is 32 weeks pregnant has a BP of 158/104 mmHg on two readings. Urine protein:creatinine ratio is 45 mg/mmol. She has no headache or visual symptoms, and her bloods are normal. What is the SINGLE most appropriate antihypertensive?', 'She has pre-eclampsia (new hypertension after 20 weeks with proteinuria, PCR 30 mg/mmol or above). NICE recommends labetalol first-line (nifedipine if labetalol is unsuitable, then methyldopa), targeting BP of 135/85 mmHg or below. ACE inhibitors and ARBs are contraindicated in pregnancy. MgSO4 is for severe pre-eclampsia or eclampsia. Delivery timing depends on gestation and severity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('859472ec-37fa-591c-9e27-c788cbcc36e8', '70d714a7-e884-5575-9215-60fee84a23a5', 'A', 'Oral labetalol', true, 0),
  ('29083bb2-ebd8-511b-93d2-9f02c9053aea', '70d714a7-e884-5575-9215-60fee84a23a5', 'B', 'IV magnesium sulfate', false, 1),
  ('a8c620e0-ebfb-5ba4-a729-aa1332b961e7', '70d714a7-e884-5575-9215-60fee84a23a5', 'C', 'Oral bendroflumethiazide', false, 2),
  ('81b83376-5796-5a65-8c99-baef5236a6eb', '70d714a7-e884-5575-9215-60fee84a23a5', 'D', 'Oral ramipril', false, 3),
  ('382c67d1-ca58-503f-977a-37bc2ca57c43', '70d714a7-e884-5575-9215-60fee84a23a5', 'E', 'Oral losartan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman who is 35 weeks pregnant has right upper quadrant pain, nausea and malaise. Her BP is 150/96 mmHg. Bloods show haemoglobin 92 g/L with schistocytes, raised LDH and bilirubin, ALT 260 U/L and platelets 62 x 10^9/L. What is the SINGLE most likely diagnosis?', 'HELLP (Haemolysis, Elevated Liver enzymes, Low Platelets) is a severe form of pre-eclampsia. It presents with RUQ or epigastric pain, nausea and malaise. Management is stabilisation (BP control, MgSO4, correcting coagulopathy) and delivery. Acute fatty liver of pregnancy causes marked hypoglycaemia, high ammonia and coagulopathy, often without much haemolysis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('77ced058-dfac-5da4-b3ef-80097c8b8a46', 'de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'A', 'Viral hepatitis', false, 0),
  ('42da7700-5be5-53f2-82c3-932d573dd1c2', 'de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'B', 'Intrahepatic cholestasis of pregnancy', false, 1),
  ('21ba26f8-71f0-561c-8ce7-04428c1e3bea', 'de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'C', 'Acute fatty liver of pregnancy', false, 2),
  ('1c3c2eca-37ad-592a-bf9b-274d43fd5e83', 'de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'D', 'HELLP syndrome', true, 3),
  ('25df92d9-cc40-582a-ae3c-4bb5334655c5', 'de3b7cd9-9c54-52bd-a0b7-7f170aec81b3', 'E', 'Gallstones', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('019177e7-618f-5504-81b1-35eaa4bf3090', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 29 year old woman who is 34 weeks pregnant has severe itching of her palms and soles, worse at night, with no rash. Her bile acids are raised at 45 micromol/L and ALT is mildly raised. What is the SINGLE most likely diagnosis?', 'Intrahepatic cholestasis of pregnancy causes pruritus (especially of the palms and soles) without a rash in the third trimester, with raised bile acids. Ursodeoxycholic acid may be used for symptoms. Very high bile acids (100 micromol/L or above) are linked to stillbirth, so planned birth may be advised. It resolves after delivery and recurs in future pregnancies.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('70ca4fb8-5055-588b-b3f0-54f433f3e6b4', '019177e7-618f-5504-81b1-35eaa4bf3090', 'A', 'HELLP syndrome', false, 0),
  ('bc72f4e2-7f80-5838-a258-222c1f5769bc', '019177e7-618f-5504-81b1-35eaa4bf3090', 'B', 'Polymorphic eruption of pregnancy', false, 1),
  ('bfd8683d-0be9-5efa-a017-de3ac53480b0', '019177e7-618f-5504-81b1-35eaa4bf3090', 'C', 'Pemphigoid gestationis', false, 2),
  ('269efa69-b1af-51dd-a303-e37e86b428dc', '019177e7-618f-5504-81b1-35eaa4bf3090', 'D', 'Intrahepatic cholestasis of pregnancy', true, 3),
  ('93648242-2a7c-54aa-b590-ceae773776cd', '019177e7-618f-5504-81b1-35eaa4bf3090', 'E', 'Acute fatty liver of pregnancy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4d24fc9-435b-567f-90f0-acc775ee0af0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman is 41 weeks + 3 days in her first pregnancy with no complications. She asks about induction of labour. According to NICE, what is the SINGLE most appropriate advice?', 'NICE (NG207) recommends discussing and offering induction from 41 weeks to reduce the risk of stillbirth and perinatal complications. If she declines, increased monitoring (CTG and ultrasound) is offered. Membrane sweeping is offered at antenatal visits from 39-40 weeks. Induction methods include vaginal prostaglandins, mechanical balloons and amniotomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0921fcea-b79b-59f2-88d7-f4cdd006361d', 'f4d24fc9-435b-567f-90f0-acc775ee0af0', 'A', 'Induction is never offered before 43 weeks', false, 0),
  ('43a658c3-e0c2-5c24-9954-2001dd321a3c', 'f4d24fc9-435b-567f-90f0-acc775ee0af0', 'B', 'Elective caesarean section is recommended', false, 1),
  ('0502bb3a-0aec-5af2-8637-d1cd5f48fb45', 'f4d24fc9-435b-567f-90f0-acc775ee0af0', 'C', 'Wait for spontaneous labour without monitoring', false, 2),
  ('5efb77af-1a4c-5a7e-910a-e28476912d5b', 'f4d24fc9-435b-567f-90f0-acc775ee0af0', 'D', 'Discuss and offer induction of labour from 41 weeks', true, 3),
  ('656712ca-2e3b-52e3-a8b2-4b448bdf34ff', 'f4d24fc9-435b-567f-90f0-acc775ee0af0', 'E', 'Induce at 37 weeks in all pregnancies', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('80370505-8595-5e8e-893a-081114658ae7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 25 year old woman in her first pregnancy is in labour. Her cervix is 5 cm dilated. Four hours later it has only progressed to 6 cm. Contractions are 2 in 10 minutes. The membranes are intact and the CTG is normal. What is the SINGLE most appropriate next step?', 'In the first stage of labour, delay is suspected if progress is under 2 cm in 4 hours (or slowing in parous women). NICE recommends amniotomy if membranes are intact, then review in 2 hours. If progress is still slow, oxytocin is started with continuous CTG and obstetric review. Instrumental delivery is only possible at full dilatation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('091c4606-294d-5902-bbc9-55bc903cacaf', '80370505-8595-5e8e-893a-081114658ae7', 'A', 'Amniotomy, then reassess progress in 2 hours (consider oxytocin if still slow)', true, 0),
  ('1bf68023-7051-5237-b0e9-1d654b51fda1', '80370505-8595-5e8e-893a-081114658ae7', 'B', 'IV antibiotics', false, 1),
  ('07a4a921-c11e-5b83-9547-cd37d9a8f622', '80370505-8595-5e8e-893a-081114658ae7', 'C', 'Immediate caesarean section', false, 2),
  ('9f3e5db8-735d-530f-85d8-9c9939d88873', '80370505-8595-5e8e-893a-081114658ae7', 'D', 'Forceps delivery', false, 3),
  ('f3c67018-7757-5e1a-89ba-0e43cf0af20e', '80370505-8595-5e8e-893a-081114658ae7', 'E', 'Wait 12 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e693b83c-6f8a-5af2-9403-b053117b9282', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman is in labour at 39 weeks. The CTG shows a baseline of 150 bpm, variability under 5 bpm for 50 minutes and late decelerations with over 50% of contractions for 30 minutes. What is the SINGLE most appropriate action?', 'Under NICE (NG229), reduced variability and recurrent late decelerations are concerning features that need urgent senior review. Take conservative measures (change position, give IV fluids, stop oxytocin, treat hypotension) and consider fetal blood sampling or expedited birth depending on the overall picture. A prolonged bradycardia over 3 minutes needs urgent delivery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c5238e2-9235-5d5a-b955-47eb53af351b', 'e693b83c-6f8a-5af2-9403-b053117b9282', 'A', 'No action; the CTG is normal', false, 0),
  ('0f40c5eb-b75b-5dcc-918d-b138601a2673', 'e693b83c-6f8a-5af2-9403-b053117b9282', 'B', 'Give oxytocin to speed up labour', false, 1),
  ('5a840675-552b-556a-a64a-32f8fc14935a', 'e693b83c-6f8a-5af2-9403-b053117b9282', 'C', 'Urgent obstetric review, correct reversible causes and consider fetal blood sampling or expedited delivery', true, 2),
  ('60ba097e-1fb3-5a40-a836-ebaf27bc0aea', 'e693b83c-6f8a-5af2-9403-b053117b9282', 'D', 'Discharge home', false, 3),
  ('73b118b8-d1ad-5efc-8234-17c33f82b1d4', 'e693b83c-6f8a-5af2-9403-b053117b9282', 'E', 'Continue and review in 4 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7ea42426-5076-5651-b0e0-7b07cae1370c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman has just delivered her baby vaginally and has lost 1,200 mL of blood. Her uterus is soft and boggy above the umbilicus. The placenta was complete and there are no tears. What is the SINGLE most likely cause of her bleeding?', 'The causes of primary postpartum haemorrhage are the ''4 Ts'': Tone (uterine atony, about 70%), Trauma, Tissue (retained products) and Thrombin (coagulopathy). A soft, boggy uterus indicates atony. Management is uterine massage, bimanual compression, then uterotonics (oxytocin, ergometrine, carboprost, misoprostol), tranexamic acid and escalation to surgical measures.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fea2044c-8b8c-566b-921c-4b268cc589ae', '7ea42426-5076-5651-b0e0-7b07cae1370c', 'A', 'Genital tract trauma', false, 0),
  ('51743c95-be1c-52c8-8bd8-8f34ebef8cea', '7ea42426-5076-5651-b0e0-7b07cae1370c', 'B', 'Uterine rupture', false, 1),
  ('18fa8dcc-4dbd-564a-994e-a131640ee216', '7ea42426-5076-5651-b0e0-7b07cae1370c', 'C', 'Coagulopathy', false, 2),
  ('5e44f266-81c9-5cb8-a00d-ad16d9836c0f', '7ea42426-5076-5651-b0e0-7b07cae1370c', 'D', 'Retained placental tissue', false, 3),
  ('2843538d-4b23-5dec-bf24-a3e647fb2ac1', '7ea42426-5076-5651-b0e0-7b07cae1370c', 'E', 'Uterine atony', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman delivered a baby 9 days ago. She now has a fever, offensive lochia, lower abdominal pain and a tender uterus. Her placenta was removed manually. What is the SINGLE most likely diagnosis?', 'Postpartum endometritis causes fever, uterine tenderness, offensive lochia and sometimes abnormal bleeding. Risk factors include caesarean section, prolonged rupture of membranes and manual removal of the placenta. Management is broad-spectrum antibiotics (IV if unwell, such as clindamycin plus gentamicin), with assessment for retained products and sepsis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('881fc4b1-541e-5cd1-acdf-ec60db7f871c', 'fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'A', 'Mastitis', false, 0),
  ('15b97c11-7765-561f-af12-92b0829a8991', 'fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'B', 'Pelvic vein thrombosis', false, 1),
  ('d7f1788b-834c-556b-b062-7b35f425940a', 'fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'C', 'Retained products alone without infection', false, 2),
  ('92f2fdda-57f4-5f4b-b7b2-80aee752d92c', 'fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'D', 'Endometritis', true, 3),
  ('7ca022e5-abd8-505b-be19-c3532670925a', 'fb8a58ab-d7d7-5092-8f61-92de10f98be4', 'E', 'Urinary tract infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 29 year old woman who is 39 weeks pregnant is in labour. The midwife sees the umbilical cord protruding from the vagina after the membranes rupture. The CTG shows fetal bradycardia. What is the SINGLE most appropriate immediate action?', 'Cord prolapse is an obstetric emergency. Call for help, minimise cord handling to avoid vasospasm, relieve compression by manually elevating the presenting part or filling the bladder, and use the knee-chest or left lateral position. Arrange immediate delivery, usually by category 1 caesarean section, unless vaginal delivery is imminent.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ce6b25c-e7b6-5a6b-8ed1-1f55a8ce3fba', 'e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'A', 'Push the cord back into the uterus', false, 0),
  ('d1955d27-0f94-5b39-ac57-b7112e64327a', 'e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'B', 'Wait for spontaneous delivery', false, 1),
  ('60f03639-5e21-5428-8a46-3c32f586d70c', 'e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'C', 'Give tocolytics and wait 2 hours', false, 2),
  ('641be350-6757-576f-b818-338971a4d625', 'e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'D', 'Relieve cord compression (push the presenting part up or fill the bladder, knee-chest position) and arrange immediate delivery', true, 3),
  ('dfd7a4fb-0692-5142-9177-b21e99035116', 'e13b9288-eae3-55b3-8594-3fa0584e7e8d', 'E', 'Pull on the cord', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman is in the second stage of labour. After delivery of the baby''s head, the head retracts against the perineum (''turtle sign'') and the shoulders do not deliver with gentle traction. What is the SINGLE most appropriate first manoeuvre?', 'Shoulder dystocia: call for help, then McRoberts (hyperflexion of the hips) and suprapubic pressure, which resolve most cases. Next steps are internal rotation manoeuvres or delivery of the posterior arm. Fundal pressure is contraindicated because it can cause uterine rupture and worsen impaction. Risk factors include macrosomia and diabetes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bdbd4fa0-b74a-5890-bf66-39af75ca7358', '38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'A', 'McRoberts manoeuvre with suprapubic pressure', true, 0),
  ('72a1f631-eeb8-5847-8e82-b368ceb3e6c9', '38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'B', 'Strong downward traction on the head', false, 1),
  ('5284605f-3b11-5f95-8f7b-a08a6bcc5418', '38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'C', 'Fundal pressure', false, 2),
  ('58da8124-88ed-55af-b1a8-1a6c3c743383', '38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'D', 'Zavanelli manoeuvre', false, 3),
  ('6b276d83-4808-5c06-9f0d-b54ab320a22c', '38cceb37-158d-5c91-a5f3-8895b7b9d97e', 'E', 'Cut the umbilical cord', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman at 36 weeks has a breech presentation confirmed on ultrasound. She has no complications and no previous caesarean. What is the SINGLE most appropriate management?', 'NICE and RCOG recommend offering external cephalic version from 36 weeks in nulliparous women (37 weeks in multiparous women) with an uncomplicated breech. Success is about 50%. If it fails or is declined, the options are planned caesarean section or vaginal breech birth in a hospital setting. Anti-D is given after ECV if she is rhesus negative.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('61570f71-73f7-5683-ab13-66980c5728c8', '0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'A', 'Offer external cephalic version', true, 0),
  ('461e1b42-6d86-5e6c-b455-b3e542f1e59c', '0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'B', 'Induce labour immediately', false, 1),
  ('61775b70-0908-5187-bf3f-6b927819c049', '0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'C', 'Elective caesarean section at 36 weeks', false, 2),
  ('35942bfd-b9e5-5fc9-82e5-b50fb7c84d04', '0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'D', 'Advise vaginal breech delivery at home', false, 3),
  ('652f33a3-e1f0-5dc9-9630-a4453238557a', '0b1e4ca2-0319-5163-b9ab-506cdf464fd3', 'E', 'No action', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('987f82da-47e4-5004-9a01-fea6f2f9faef', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 33 year old woman had a caesarean section for fetal distress in her first pregnancy. She is now pregnant again and asks about delivery. She has no other complications. What is the SINGLE most appropriate advice?', 'Women with one previous lower segment caesarean section can be offered planned VBAC, with a success rate of about 72-75% and a uterine rupture risk of about 1 in 200, needing continuous monitoring in hospital. Elective repeat caesarean section is an alternative, usually from 39 weeks. Contraindications to VBAC include previous rupture or a classical scar.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eff916f1-34db-5c9d-a5b4-8f8dd5769476', '987f82da-47e4-5004-9a01-fea6f2f9faef', 'A', 'A repeat caesarean section is mandatory', false, 0),
  ('e54aa1fc-5750-5161-871c-1c1f5f7fb3d0', '987f82da-47e4-5004-9a01-fea6f2f9faef', 'B', 'VBAC has a 25% risk of uterine rupture', false, 1),
  ('6592e6ec-64be-5e5a-8b83-4d681c83fd7c', '987f82da-47e4-5004-9a01-fea6f2f9faef', 'C', 'She should be induced at 36 weeks', false, 2),
  ('846d7c5a-5716-5fac-9d92-0ff8c19b3ec3', '987f82da-47e4-5004-9a01-fea6f2f9faef', 'D', 'Vaginal birth after caesarean (VBAC) is an option with about a 72-75% success rate and a small (0.5%) risk of uterine rupture', true, 3),
  ('4c936a98-8dd7-5ea2-a708-698db762d6e3', '987f82da-47e4-5004-9a01-fea6f2f9faef', 'E', 'She must deliver at home', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3383cff-6025-5106-a966-8fd2c39a461d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 24 year old woman is 28 weeks pregnant. Her oral glucose tolerance test is normal. Her haemoglobin is 98 g/L with low ferritin. What is the SINGLE most appropriate management?', 'NICE thresholds for anaemia in pregnancy are haemoglobin under 110 g/L in the first trimester, under 105 g/L in the second and third trimesters, and under 100 g/L postpartum. Iron deficiency is treated with oral iron (such as ferrous sulfate), and Hb is rechecked after 2-3 weeks. IV iron is for intolerance or a poor response. Transfusion is for severe or symptomatic anaemia near delivery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f8afaeda-5c74-5d43-abdb-41ef07ba3ea1', 'e3383cff-6025-5106-a966-8fd2c39a461d', 'A', 'No treatment', false, 0),
  ('d7a94c23-6a76-5f86-a776-44fd5801aaf1', 'e3383cff-6025-5106-a966-8fd2c39a461d', 'B', 'IV iron immediately', false, 1),
  ('c85573d9-cb55-5742-aedb-fc18e0c950fa', 'e3383cff-6025-5106-a966-8fd2c39a461d', 'C', 'Blood transfusion', false, 2),
  ('bf5ab287-22e7-5fcf-aeb9-403b03fab4bb', 'e3383cff-6025-5106-a966-8fd2c39a461d', 'D', 'Oral iron supplementation', true, 3),
  ('1e5cc142-5513-5283-9be0-f428b42add70', 'e3383cff-6025-5106-a966-8fd2c39a461d', 'E', 'Folic acid alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6c52c587-d99f-5307-9c41-5bee45506e7b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman has a booking appointment at 10 weeks. She takes no medication. She asks which supplements she should take in pregnancy. Her BMI is 24 kg/m2. What is the SINGLE most appropriate advice?', 'NICE advises folic acid 400 micrograms daily before conception until 12 weeks, and vitamin D 10 micrograms daily during pregnancy and breastfeeding. High-dose folic acid (5 mg) is for higher-risk women: previous NTD, diabetes, antiepileptic drugs, BMI 30 or above, sickle cell, or coeliac disease. Vitamin A (retinol) should be avoided because it is teratogenic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1a4a2ca7-e1a2-5be9-ba9a-03283737b0cd', '6c52c587-d99f-5307-9c41-5bee45506e7b', 'A', 'Folic acid 5 mg daily throughout', false, 0),
  ('0d9d099c-07bd-59f7-b32e-39c22e970074', '6c52c587-d99f-5307-9c41-5bee45506e7b', 'B', 'No supplements needed', false, 1),
  ('5a5722f7-b8ba-5040-8973-680ea4b680a9', '6c52c587-d99f-5307-9c41-5bee45506e7b', 'C', 'Vitamin A supplements', false, 2),
  ('cb449d70-c0d3-5382-9d6b-6648409b1b67', '6c52c587-d99f-5307-9c41-5bee45506e7b', 'D', 'Folic acid 400 micrograms daily until 12 weeks and vitamin D 10 micrograms daily throughout', true, 3),
  ('50787205-cf21-5207-95c7-ca098bf07c4b', '6c52c587-d99f-5307-9c41-5bee45506e7b', 'E', 'Iron for all women', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('815037f9-e76b-54ec-a56d-047336e6eb41', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 26 year old woman who is 30 weeks pregnant has a ''gush'' of clear fluid from her vagina. She has no contractions. Speculum examination shows a pool of amniotic fluid. She is apyrexial and the CTG is normal. What is the SINGLE most appropriate management?', 'Preterm prelabour rupture of membranes (PPROM) is managed with erythromycin for 10 days (or until labour) to reduce chorioamnionitis and neonatal morbidity, plus antenatal corticosteroids for fetal lung maturity. Digital examination should be avoided. Delivery is usually planned at 37 weeks, or earlier if there is infection. Magnesium sulfate is given for neuroprotection if delivery is expected before 30 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a68c9e81-c7b4-5ddc-903e-9da3137a4848', '815037f9-e76b-54ec-a56d-047336e6eb41', 'A', 'No treatment and discharge', false, 0),
  ('89a6ad16-5a0f-5d56-94ed-dc2fea617b49', '815037f9-e76b-54ec-a56d-047336e6eb41', 'B', 'Tocolysis for 2 weeks', false, 1),
  ('6c7ca8b0-1b68-512f-a483-ca36801e248f', '815037f9-e76b-54ec-a56d-047336e6eb41', 'C', 'Immediate induction of labour', false, 2),
  ('3d8be314-a6b8-50ab-9af6-e24ed9ecedbe', '815037f9-e76b-54ec-a56d-047336e6eb41', 'D', 'Digital vaginal examination', false, 3),
  ('b672a6cb-35a8-5734-b4ff-a1747b4db21a', '815037f9-e76b-54ec-a56d-047336e6eb41', 'E', 'Oral erythromycin for 10 days, antenatal corticosteroids and monitoring for chorioamnionitis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8a724fd5-82db-5efd-b4a2-49113be83d6b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman has had heavy periods for 2 years. Pelvic examination and ultrasound are normal. She is not trying to conceive. Her haemoglobin is 112 g/L. What is the SINGLE most appropriate first-line treatment?', 'NICE recommends the LNG-IUS as first-line for heavy menstrual bleeding with no structural or histological abnormality, or with fibroids under 3 cm that do not distort the cavity. If it is unsuitable, tranexamic acid, NSAIDs (mefenamic acid) or the COCP are used. Surgery (ablation, hysterectomy) is considered if medical treatment fails.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0ada06ed-7cbf-5b09-8127-4769f8b7c114', '8a724fd5-82db-5efd-b4a2-49113be83d6b', 'A', 'Hysterectomy', false, 0),
  ('6394280d-abe6-50c3-a08c-e1a4cfe1a9c3', '8a724fd5-82db-5efd-b4a2-49113be83d6b', 'B', 'Tranexamic acid only if she wants contraception', false, 1),
  ('b26bfeb6-487a-5af9-9951-939501a7c629', '8a724fd5-82db-5efd-b4a2-49113be83d6b', 'C', 'Endometrial ablation', false, 2),
  ('932be002-5ada-594e-93b2-c99bee5953bf', '8a724fd5-82db-5efd-b4a2-49113be83d6b', 'D', 'Oral norethisterone for 12 months', false, 3),
  ('a610c8cf-0bd9-5369-82a1-2a8ea4329225', '8a724fd5-82db-5efd-b4a2-49113be83d6b', 'E', 'Levonorgestrel-releasing intrauterine system (LNG-IUS)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 42 year old woman has heavy periods and pressure symptoms. Ultrasound shows a 6 cm intramural fibroid. She has completed her family and wants a definitive treatment. Medical treatment has failed. What is the SINGLE most appropriate definitive management?', 'Fibroids (leiomyomas) are oestrogen-dependent benign tumours. For large fibroids with heavy bleeding after failed medical treatment, options include uterine artery embolisation, myomectomy (to preserve fertility) or hysterectomy (definitive, when the family is complete). GnRH analogues can shrink fibroids before surgery. Red degeneration in pregnancy causes pain and fever.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5b182c5-8b38-51fb-85cf-6eee395d1dc3', '6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'A', 'Myomectomy only', false, 0),
  ('b55a95bf-18c2-537e-a39a-76864927bcfc', '6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'B', 'Hysterectomy', true, 1),
  ('e2d9a65a-4182-5e98-98c0-3f50b75f5848', '6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'C', 'No treatment', false, 2),
  ('a160a19b-3e02-5e42-973e-61dceca0ebfb', '6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'D', 'Tranexamic acid', false, 3),
  ('2e4011cc-31d3-5af5-b116-fcf027219920', '6f4bd39f-2d2a-5c0f-a1d7-9ef44a7e5dc3', 'E', 'Levonorgestrel-releasing intrauterine system', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2dbaa534-ec71-5200-a791-73db8ad6799d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 47 year old woman has had heavy, painful periods for 2 years. She has a symmetrically enlarged, boggy, tender uterus. Ultrasound shows a diffusely enlarged uterus with myometrial cysts and no discrete fibroids. What is the SINGLE most likely diagnosis?', 'Adenomyosis is endometrial tissue within the myometrium. It is more common in multiparous women in their 40s and presents with heavy, painful periods and a bulky, tender uterus. MRI is the most accurate investigation. Management is the LNG-IUS, NSAIDs, tranexamic acid or GnRH analogues, with hysterectomy as the definitive treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5c9f3a9d-fad4-50b6-a8c8-38976b39e9f0', '2dbaa534-ec71-5200-a791-73db8ad6799d', 'A', 'Adenomyosis', true, 0),
  ('e78732c5-a52c-5259-afc1-fdc5553b0f36', '2dbaa534-ec71-5200-a791-73db8ad6799d', 'B', 'Fibroids', false, 1),
  ('19264f4e-f9e9-5704-8a16-4f0cd4b49bf4', '2dbaa534-ec71-5200-a791-73db8ad6799d', 'C', 'Endometriosis', false, 2),
  ('64a81a7c-7c82-5f22-b686-c6e871432d01', '2dbaa534-ec71-5200-a791-73db8ad6799d', 'D', 'Pelvic inflammatory disease', false, 3),
  ('b472ac72-6be7-5ee0-9ed5-6f978ddc5dcd', '2dbaa534-ec71-5200-a791-73db8ad6799d', 'E', 'Endometrial cancer', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1dfa98c8-1658-5a4b-a872-76e00559ee95', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 22 year old woman has had lower abdominal pain, deep dyspareunia and a vaginal discharge for 5 days. Her temperature is 38.1°C, and she has cervical motion tenderness and adnexal tenderness. Pregnancy test is negative. What is the SINGLE most appropriate management?', 'Pelvic inflammatory disease is a clinical diagnosis: lower abdominal pain, cervical motion tenderness or adnexal tenderness. Antibiotics are started empirically without waiting for results. BASHH recommends IM ceftriaxone 1 g single dose, plus doxycycline 100 mg twice daily and metronidazole 400 mg twice daily for 14 days. Complications include tubal infertility, ectopic pregnancy and Fitz-Hugh-Curtis syndrome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9339de50-e6cc-55e2-8fec-058a3d889bd1', '1dfa98c8-1658-5a4b-a872-76e00559ee95', 'A', 'Laparoscopy as first-line', false, 0),
  ('e80fb598-fcef-51a1-9e8f-b820b239f96d', '1dfa98c8-1658-5a4b-a872-76e00559ee95', 'B', 'Swabs for STIs, then IM ceftriaxone, oral doxycycline and metronidazole for 14 days', true, 1),
  ('74df2053-61f7-5281-a020-c07ec5c93135', '1dfa98c8-1658-5a4b-a872-76e00559ee95', 'C', 'No treatment until swab results', false, 2),
  ('321e27a0-83f0-58d0-a4ee-d50f908a15b3', '1dfa98c8-1658-5a4b-a872-76e00559ee95', 'D', 'Oral amoxicillin for 5 days', false, 3),
  ('0296e717-0425-5dc6-9aa7-9120a1f79951', '1dfa98c8-1658-5a4b-a872-76e00559ee95', 'E', 'Oral nitrofurantoin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('244a39ce-a633-5c33-ac71-4e9389ea63fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 21 year old woman has severe lower abdominal cramps on the first two days of each period since menarche. Her pelvic examination is normal. She is sexually active and wants contraception. What is the SINGLE most appropriate management?', 'Primary dysmenorrhoea (painful periods without pelvic pathology) usually starts within 6-12 months of menarche. First-line treatment is an NSAID such as mefenamic acid or ibuprofen, and/or the COCP, which also provides contraception. Secondary dysmenorrhoea (new onset later, associated symptoms) should prompt investigation for endometriosis, adenomyosis or PID.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb87045a-fd3a-55e0-ae0c-9ccee7f755f3', '244a39ce-a633-5c33-ac71-4e9389ea63fe', 'A', 'Laparoscopy', false, 0),
  ('3db3222f-04c7-5af7-a3fa-4d75867eefd5', '244a39ce-a633-5c33-ac71-4e9389ea63fe', 'B', 'Opioid analgesia', false, 1),
  ('acc61aa9-131d-5cac-a6df-7e132f96617f', '244a39ce-a633-5c33-ac71-4e9389ea63fe', 'C', 'NSAID (such as mefenamic acid) and/or the combined oral contraceptive pill', true, 2),
  ('c8b08d26-fba0-5dd3-beb2-f964f2589f8e', '244a39ce-a633-5c33-ac71-4e9389ea63fe', 'D', 'Pelvic MRI', false, 3),
  ('a58e6e7f-919c-532d-a21f-fd1a9fd14c9b', '244a39ce-a633-5c33-ac71-4e9389ea63fe', 'E', 'Hysterectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('86820757-13b6-5b26-a5a5-862dda307ac1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman has had severe low mood, irritability, breast tenderness and bloating in the week before each period for 2 years. Her symptoms go away a few days after her period starts. What is the SINGLE most appropriate first-line pharmacological treatment for severe symptoms?', 'Premenstrual syndrome (and its severe form, premenstrual dysphoric disorder) causes cyclical symptoms in the luteal phase that resolve with menstruation. A symptom diary is used to diagnose it. Management includes lifestyle measures and CBT. For moderate-severe symptoms, a drospirenone-containing COCP or an SSRI (continuous or luteal phase) is used. GnRH analogues are a specialist option.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9ef21220-5624-53e4-b74d-d4c81b48bf2b', '86820757-13b6-5b26-a5a5-862dda307ac1', 'A', 'Diazepam', false, 0),
  ('7af5d10f-0d9d-5360-8f1d-d29bf4f547f5', '86820757-13b6-5b26-a5a5-862dda307ac1', 'B', 'Oestrogen-only HRT', false, 1),
  ('172b8220-5115-5c9e-bed1-90d59e4ea61a', '86820757-13b6-5b26-a5a5-862dda307ac1', 'C', 'Progesterone pessaries', false, 2),
  ('309df3da-96cb-5ed7-a17f-8e79f529c0bc', '86820757-13b6-5b26-a5a5-862dda307ac1', 'D', 'A new-generation combined oral contraceptive (drospirenone-containing) or an SSRI', true, 3),
  ('2cc2311f-8b8f-5839-8908-e1e0f5c7ce59', '86820757-13b6-5b26-a5a5-862dda307ac1', 'E', 'Testosterone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 38 year old woman has not had a period for 8 months. Her FSH is raised at 52 IU/L on two occasions 4-6 weeks apart. She has hot flushes. Pregnancy test is negative. What is the SINGLE most likely diagnosis?', 'Premature ovarian insufficiency is loss of ovarian function before age 40, with oligo- or amenorrhoea and a raised FSH (over 25 IU/L on two samples 4 weeks apart). Hormone replacement (HRT or COCP) is recommended until the natural age of menopause to protect bones and the heart. Causes include autoimmune disease, Turner syndrome, Fragile X premutation and chemotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4e4b9a07-675a-5c61-8d06-20c54aefefdd', '87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'A', 'Prolactinoma', false, 0),
  ('67e77009-025e-5031-85b4-441fbefcf9f7', '87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'B', 'Polycystic ovary syndrome', false, 1),
  ('2a0164d6-5a92-5d29-b3f7-ada252029965', '87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'C', 'Pregnancy', false, 2),
  ('a68560b1-0799-5034-b8a1-a97c100cbac0', '87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'D', 'Hypothalamic amenorrhoea', false, 3),
  ('949ae847-e223-5986-b3f8-ad838d48de51', '87830a9a-7c4d-5965-a9c0-9b33e4e13f05', 'E', 'Premature ovarian insufficiency', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('18dd1649-885d-59e8-a3a0-a5870f711673', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman has not had a period for 6 months and has a milky discharge from both nipples. Pregnancy test is negative. Her serum prolactin is very high, and she has a bitemporal visual field defect. What is the SINGLE most appropriate first-line treatment?', 'A prolactinoma causes amenorrhoea, galactorrhoea and infertility (prolactin suppresses GnRH), and a macroadenoma may cause bitemporal hemianopia. First-line treatment is a dopamine agonist (cabergoline, or bromocriptine), which usually shrinks the tumour and normalises prolactin. Surgery is for patients who do not respond or cannot tolerate treatment. Drugs that raise prolactin (antipsychotics, metoclopramide) should be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
