insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('aba72208-700e-536c-b288-af715c2d633f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old couple have been trying to conceive for 2 years. The woman has regular cycles with a mid-luteal progesterone confirming ovulation. Her tubes are patent on hysterosalpingogram. Which investigation is MOST appropriate for her partner?', 'Infertility is failure to conceive after 1 year of regular unprotected sex. Initial investigations for the woman include a mid-luteal progesterone and tests of tubal patency, and for the man a semen analysis, repeated after 3 months if abnormal. Treatments include ovulation induction (clomifene, letrozole), IUI and IVF/ICSI depending on the cause. NICE recommends lifestyle advice for both partners.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
