insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fde1c7f2-5399-5eae-9c65-989af2cc55b5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman having IVF develops abdominal pain, distension, nausea and breathlessness 5 days after egg collection. Ultrasound shows enlarged ovaries and ascites. Her haematocrit is raised. What is the SINGLE most likely diagnosis?', 'OHSS is a complication of ovarian stimulation, with enlarged ovaries and fluid shifting into the third space (ascites, pleural effusion), causing haemoconcentration, VTE and renal impairment. Management is supportive: analgesia, fluid balance monitoring, thromboprophylaxis, and paracentesis for tense ascites. Severe cases need admission.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
