insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ed92cb9d-431e-514e-9763-8f145d74d1b1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 64 year old woman has a dragging sensation in her vagina and a lump that is worse at the end of the day. Examination shows descent of the anterior vaginal wall to the hymen. She has urinary frequency. What is the SINGLE most appropriate initial management?', 'A cystocele (anterior prolapse) is common after childbirth and menopause. NICE recommends lifestyle changes (weight loss, treating constipation), supervised pelvic floor muscle training for at least 16 weeks, and vaginal oestrogen if there is atrophy. Vaginal pessaries (ring or shelf) are an alternative. Surgery is for persistent bothersome symptoms. Transvaginal mesh is restricted.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
