insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08fdf8a4-35fd-5c98-ace0-e4d3e8d4eb3e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 52 year old woman leaks urine when she coughs, sneezes or laughs. She has no urgency. Urinalysis is normal. What is the SINGLE most appropriate first-line treatment?', 'Stress urinary incontinence is leakage with raised abdominal pressure, from weak pelvic floor or urethral sphincter. NICE recommends supervised pelvic floor muscle training (at least 8 contractions 3 times a day for at least 3 months) first-line, plus lifestyle changes. Duloxetine is second-line if surgery is not wanted. Surgery (colposuspension, autologous sling) is considered if conservative treatment fails.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
