insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a5d17c39-22dd-5306-9349-44822655dbb1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 26 year old woman has had a thin, grey, fishy-smelling vaginal discharge for 1 week, worse after sex. There is no itch or soreness. Vaginal pH is 5.5 and a whiff test is positive. What is the SINGLE most appropriate treatment?', 'Bacterial vaginosis is an overgrowth of anaerobes (such as Gardnerella vaginalis). Amsel criteria are a thin homogeneous discharge, pH over 4.5, a positive whiff test and clue cells. Treatment is oral metronidazole (5-7 days, or 2 g single dose), or topical metronidazole or clindamycin. Male partners do not need treatment. In pregnancy, BV is linked to preterm birth.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
